-- Neurology (new topics) question bank: exactly 350 hand-written NCLEX-style
-- questions (single-best-answer + select-all-that-apply), 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Neurology/Autonomic-Dysreflexia.html
--   Notes/Neurology/Brain-Tumors.html
--   Notes/Neurology/Encephalitis.html
--   Notes/Neurology/Hydrocephalus.html
--   Notes/Neurology/Scleroderma.html
--   Notes/Neurology/TBI-Concussion.html
--   Notes/Neurology/Trigeminal-Neuralgia.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (350) exist after insert.
BEGIN;

CREATE TEMP TABLE _neuro2_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _neuro2_sources (source_key, source_path, category) VALUES
  ('ad', 'Notes/Neurology/Autonomic-Dysreflexia.html', 'Neurology NCLEX seed v2 - autonomic dysreflexia'),
  ('brain_tumors', 'Notes/Neurology/Brain-Tumors.html', 'Neurology NCLEX seed v2 - brain tumors'),
  ('encephalitis', 'Notes/Neurology/Encephalitis.html', 'Neurology NCLEX seed v2 - encephalitis'),
  ('hydrocephalus', 'Notes/Neurology/Hydrocephalus.html', 'Neurology NCLEX seed v2 - hydrocephalus'),
  ('scleroderma', 'Notes/Neurology/Scleroderma.html', 'Neurology NCLEX seed v2 - scleroderma'),
  ('tbi', 'Notes/Neurology/TBI-Concussion.html', 'Neurology NCLEX seed v2 - tbi concussion'),
  ('trigeminal', 'Notes/Neurology/Trigeminal-Neuralgia.html', 'Neurology NCLEX seed v2 - trigeminal neuralgia');

CREATE TEMP TABLE _neuro2_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _neuro2_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'neurology'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Neurology"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'neurology'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _neuro2_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Neurology subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Neurology points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _neuro2_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Neurology seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _neuro2_seed_map) <> 7 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 7 note mappings, found %.',
      (SELECT count(*) FROM _neuro2_seed_map);
  END IF;

  INSERT INTO _neuro2_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _neuro2_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, v.is_multi, v.display_order, 1, true
  FROM (VALUES
  ('ad', 1, 'A client with a C6 spinal cord injury suddenly reports a severe pounding headache. BP is 168/94 mm Hg (baseline 98/60 mm Hg), heart rate is 52/min, and the face is flushed and sweaty. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Check the urinary catheter for kinks, blockage, or drainage failure"}, {"id": "b", "text": "Sit the patient upright, raising the HOB to near 90 degrees"}, {"id": "c", "text": "Notify the provider to obtain a rapid-acting antihypertensive"}, {"id": "d", "text": "Assess the client for bowel distention and fecal impaction"}]'::jsonb, '["b"]', 'These findings (SCI above T6, pounding headache, systolic rise well over 20 mm Hg, flushing and sweating, bradycardia) indicate AD, and sitting the patient upright near 90 degrees is the FIRST action because the orthostatic effect helps lower BP. Checking the catheter is the first priority of the trigger search, but it follows positioning; medication is for BP that stays elevated or a trigger that is not found.', false),
  ('ad', 2, 'A client with a T2 spinal cord injury has BP 172/100 mm Hg (baseline 100/64 mm Hg) and a throbbing headache after the urine leg bag was found overfilled. Which findings should the nurse expect when assessing the client''s skin? Select all that apply.', '[{"id": "a", "text": "Flushing of the skin above the injury level"}, {"id": "b", "text": "Heavy sweating below the injury level"}, {"id": "c", "text": "Pale, cool skin below the injury level"}, {"id": "d", "text": "Warm, flushed skin below the injury level"}, {"id": "e", "text": "Goosebumps below or around the injury level"}]'::jsonb, '["a", "c", "e"]', 'In AD the response differs above and below the injury. (a) Correct: flushing occurs above the injury from parasympathetic compensation. (c) Correct: vasoconstriction below the injury causes pale, cool skin. (e) Correct: goosebumps appear below or around the injury level. (b) Wrong: heavy sweating occurs above, not below, the injury. (d) Wrong: skin below the injury is pale and cool from vasoconstriction, not warm and flushed.', true),
  ('ad', 3, 'A client with a T4 spinal cord injury has a usual BP of 90/58 mm Hg. The client now reports a mild headache and nasal congestion, and the BP is 114/72 mm Hg. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The reading is within the normal adult range, so AD is unlikely"}, {"id": "b", "text": "The rise is expected after SCI; recheck the BP in one hour"}, {"id": "c", "text": "A systolic rise of 20 mm Hg or more above baseline signals AD"}, {"id": "d", "text": "AD is unlikely until the systolic pressure exceeds 140 mm Hg"}]'::jsonb, '["c"]', 'The systolic BP is 24 mm Hg above this client''s baseline, which meets the key AD threshold of a rise of 20 mm Hg or more above the patient''s own baseline. Judging the reading against average adult values is the tempting error, because baseline BP in high-level SCI is often lower than average.', false),
  ('ad', 4, 'The nurse on a rehabilitation unit reviews the records of four clients with spinal cord injuries before planning care. Which client is at HIGHEST risk for autonomic dysreflexia?', '[{"id": "a", "text": "A patient with a T10 injury who has an indwelling urinary catheter"}, {"id": "b", "text": "A patient with a T7 injury who reports constipation for 3 days"}, {"id": "c", "text": "A patient with a T8 injury who has a sacral pressure injury"}, {"id": "d", "text": "A patient with a C5 injury on scheduled bladder emptying"}]'::jsonb, '["d"]', 'AD occurs mainly with SCI at or above T6, and cervical and upper thoracic injuries carry the highest risk, so the C5 client is at highest risk. The catheter, constipation, and pressure injury in the other clients are possible triggers, but T7, T8, and T10 are all below T6.', false),
  ('ad', 5, 'A client with a T3 spinal cord injury has BP 164/96 mm Hg (baseline 102/66 mm Hg). The catheter is draining well and no stool is found in the rectum. Which findings on further assessment could be the trigger that the nurse must remove? Select all that apply.', '[{"id": "a", "text": "Flushing and heavy sweating on the face and neck"}, {"id": "b", "text": "Ingrown toenails on both feet"}, {"id": "c", "text": "A sore throat from a recent cold"}, {"id": "d", "text": "Wrinkled sheets under the patient''s sacrum"}, {"id": "e", "text": "Tight shoes on both swollen feet"}]'::jsonb, '["b", "d", "e"]', 'After bladder and bowel, the nurse checks skin and other sources below the injury. (b) Correct: ingrown toenails are a listed trigger. (d) Correct: wrinkled sheets are a skin trigger. (e) Correct: tight shoes are a listed trigger. (a) Wrong: flushing and sweating above the injury are symptoms of AD, not the trigger. (c) Wrong: AD is triggered by a painful or irritating stimulus below the injury level; a sore throat is above a T3 injury.', true),
  ('ad', 6, 'A client with a C7 spinal cord injury has a pounding headache and BP 176/98 mm Hg (baseline 104/68 mm Hg). The nurse has raised the HOB and loosened the client''s clothing. The urine drainage bag has been empty for 3 hours, and the tubing is kinked under the thigh. What should the nurse do NEXT?', '[{"id": "a", "text": "Relieve the obstruction so that urine drains from the catheter"}, {"id": "b", "text": "Perform a digital rectal check for fecal impaction"}, {"id": "c", "text": "Give a rapid-acting antihypertensive per protocol"}, {"id": "d", "text": "Lower the HOB flat so the sacral skin can be inspected for pressure"}]'::jsonb, '["a"]', 'The bladder is the most common trigger and the catheter is checked first in the trigger search; a kinked, non-draining catheter must be relieved. The bowel is assessed only if the bladder is not the cause, and medication is reserved for BP that stays elevated or a trigger that is not found.', false),
  ('ad', 7, 'A client with a T2 spinal cord injury is sitting upright with clothing loosened. BP is 170/100 mm Hg (baseline 100/62 mm Hg). The catheter is patent and draining clear urine. The last bowel movement was 4 days ago and the abdomen is distended. Which action is the nurse''s PRIORITY now?', '[{"id": "a", "text": "Inspect the skin of the feet for burns and ingrown toenails"}, {"id": "b", "text": "Replace the indwelling catheter with a new one"}, {"id": "c", "text": "Assess for bowel impaction, managing it carefully"}, {"id": "d", "text": "Wait 30 minutes for sitting upright to lower the BP"}]'::jsonb, '["c"]', 'With the bladder ruled out, the bowel is the second most common trigger and is assessed next, managed carefully because rectal stimulation can worsen AD. Skin is checked after bladder and bowel, and waiting is unsafe because BP stays high until the trigger is removed.', false),
  ('ad', 8, 'A client with a C5 spinal cord injury is having an episode of autonomic dysreflexia with BP 180/104 mm Hg (baseline 96/60 mm Hg). Which action by the assistive personnel (UAP) requires immediate intervention by the nurse?', '[{"id": "a", "text": "Loosening the client''s abdominal binder and shoe straps"}, {"id": "b", "text": "Lowering the HOB flat so the client can rest"}, {"id": "c", "text": "Rechecking and reporting the BP every 2 to 3 minutes"}, {"id": "d", "text": "Reporting that the urine drainage bag has stopped filling"}]'::jsonb, '["b"]', 'The patient must be sitting upright, because the orthostatic effect helps lower BP; lowering the HOB flat removes this effect and must be stopped. Loosening restrictive items, monitoring BP every 2–3 minutes, and reporting a non-draining bag are all appropriate.', false),
  ('ad', 9, 'A client with a C4 spinal cord injury has BP 182/102 mm Hg (baseline 96/60 mm Hg). The nurse has positioned the client upright, loosened clothing, and is starting the trigger search. Which BP monitoring plan is MOST appropriate?', '[{"id": "a", "text": "Every 15 minutes until the trigger has been found and removed"}, {"id": "b", "text": "Every hour once the client is sitting upright"}, {"id": "c", "text": "Every 30 minutes after any medication is given"}, {"id": "d", "text": "Every 2–3 minutes while identifying and removing the cause"}]'::jsonb, '["d"]', 'BP is monitored every 2–3 minutes to track the trend while the cause is identified and removed. Every 15 minutes is the tempting choice but is too infrequent for a rapidly changing hypertensive emergency.', false),
  ('ad', 10, 'The nurse teaches the spouse of a client with a C6 spinal cord injury about autonomic dysreflexia before discharge. Which statements by the spouse indicate understanding? Select all that apply.', '[{"id": "a", "text": "If he gets a pounding headache, I''ll have him lie flat and rest."}, {"id": "b", "text": "I''ll check his bladder and bowel causes first."}, {"id": "c", "text": "I''ll learn his normal baseline blood pressure so I can compare."}, {"id": "d", "text": "I''ll give him a pain pill and recheck his BP in the morning."}, {"id": "e", "text": "I''ll check his BP quickly if any symptoms begin."}]'::jsonb, '["b", "c", "e"]', '(b) Correct: family should check bladder and bowel causes first. (c) Correct: they must know the patient''s normal baseline BP, since a rise of 20 mm Hg or more above it is the key threshold. (e) Correct: BP should be checked quickly if any symptoms begin. (a) Wrong: the patient should sit upright right away, not lie flat. (d) Wrong: AD is an emergency; do not wait to act.', true),
  ('ad', 11, 'A client with a T3 spinal cord injury is being treated for autonomic dysreflexia. BP is 190/110 mm Hg (baseline 104/66 mm Hg) and the nurse is still checking the bowel for a trigger. Which new finding requires IMMEDIATE notification of the emergency team?', '[{"id": "a", "text": "New chest pain with a worsening headache"}, {"id": "b", "text": "Goosebumps below or around the injury level"}, {"id": "c", "text": "Nasal congestion and facial flushing"}, {"id": "d", "text": "Heart rate of 56/min with sweating"}]'::jsonb, '["a"]', 'The nurse continues monitoring for complications such as neurologic changes, chest pain, worsening headache, and persistent hypertension, so new chest pain with a worsening headache needs immediate escalation. Goosebumps, nasal congestion, flushing, and bradycardia with sweating are expected signs of the episode itself.', false),
  ('ad', 12, 'A client with a T1 spinal cord injury had BP above 200/110 mm Hg (baseline 98/62 mm Hg) for 40 minutes before a kinked catheter was found. Which complications of this untreated period should the nurse monitor for? Select all that apply.', '[{"id": "a", "text": "Stroke"}, {"id": "b", "text": "Seizure"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Retinal hemorrhage"}, {"id": "e", "text": "Pulmonary edema"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: stroke is a consequence of untreated AD. (b) Correct: seizure is a listed consequence. (d) Correct: retinal hemorrhage is a listed consequence. (e) Correct: pulmonary edema is a listed consequence. (c) Wrong: hypoglycemia is not a consequence of AD; the danger comes from the severe hypertension.', true),
  ('ad', 13, 'The nurse receives handoff report on four clients with spinal cord injuries on a neurology rehabilitation unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "C6 injury; BP 102/64 mm Hg (baseline 98/62); last bowel movement yesterday"}, {"id": "b", "text": "L3 injury; BP 150/90 mm Hg (baseline 142/88); no headache reported"}, {"id": "c", "text": "T5 injury; BP 132/84 mm Hg (baseline 94/60); new throbbing headache"}, {"id": "d", "text": "T8 injury; due for a pressure injury dressing change in 1 hour"}]'::jsonb, '["c"]', 'The T5 client has an injury at or above T6, a systolic rise of 38 mm Hg above baseline (20 mm Hg or more is the threshold), and a new throbbing headache, which signals AD, a medical emergency. The L3 client''s reading looks higher but is only 8 mm Hg above baseline and the injury is below T6.', false),
  ('ad', 14, 'A client with a C5 spinal cord injury who uses intermittent catheterization has BP 158/96 mm Hg (baseline 100/60 mm Hg), a pounding headache, and a distended bladder, and is unable to void. After sitting the client upright and loosening clothing, which action is MOST appropriate?', '[{"id": "a", "text": "Offer extra oral fluids so that the client can void on their own"}, {"id": "b", "text": "Bladder drainage per protocol and provider direction"}, {"id": "c", "text": "Wait 30 minutes to see whether the client voids spontaneously"}, {"id": "d", "text": "Assess for fecal impaction before draining the bladder"}]'::jsonb, '["b"]', 'When there is no catheter and the patient cannot void, the bladder is drained per emergency protocol and provider direction, because a distended bladder is the most common trigger. Assessing the bowel first reverses the trigger-search order (bladder first, bowel second).', false),
  ('ad', 15, 'A client with a C6 spinal cord injury has had three episodes of autonomic dysreflexia this month. Which measures should the nurse include in the client''s prevention plan? Select all that apply.', '[{"id": "a", "text": "Keep the bladder empty with scheduled emptying"}, {"id": "b", "text": "Wear a snug abdominal binder throughout the day"}, {"id": "c", "text": "Follow a regular bowel program to prevent constipation"}, {"id": "d", "text": "Reposition regularly to prevent skin breakdown"}, {"id": "e", "text": "Check BP only when the headache becomes severe"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: keeping the bladder empty with proper catheter care or scheduled emptying prevents the most common trigger. (c) Correct: regular bowel programs prevent constipation. (d) Correct: regular repositioning prevents skin breakdown. (b) Wrong: tight clothing and constrictive items should be avoided. (e) Wrong: BP should be checked quickly if any symptoms begin, because AD is an emergency.', true),
  ('ad', 16, 'A client with a T4 spinal cord injury is sitting upright with clothing loosened. The catheter is patent, no stool is found, and the skin shows no pressure areas or other irritants. BP remains 186/104 mm Hg (baseline 100/64 mm Hg). What is the nurse''s NEXT action?', '[{"id": "a", "text": "Recheck the catheter and the bowel again in 1 hour"}, {"id": "b", "text": "Lower the HOB to help relieve the client''s headache"}, {"id": "c", "text": "Document the episode and recheck the client''s BP in 30 minutes"}, {"id": "d", "text": "Notify the provider or emergency team for further orders"}]'::jsonb, '["d"]', 'The provider or emergency team is notified when BP stays elevated or the trigger is not found, because rapid-acting antihypertensive therapy may be needed per order or protocol. Delaying with a recheck in 30–60 minutes ignores that AD is an emergency.', false),
  ('ad', 17, 'The spouse of a client with a C7 spinal cord injury asks why the client''s BP keeps climbing during an episode of autonomic dysreflexia when the body ''should fix it.'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The brain cannot send signals back down past the injury to stop it"}, {"id": "b", "text": "Parasympathetic activity above the injury is driving the BP up"}, {"id": "c", "text": "The slow heart rate below the injury is raising the blood pressure"}, {"id": "d", "text": "Blood vessels below the injury widen, so the heart pumps harder"}]'::jsonb, '["a"]', 'The brain tries to send inhibitory signals back down, but they cannot pass the injury, so the reflex cannot be turned off. The parasympathetic response above the injury is compensation that cannot correct the BP, and vessels below the injury constrict rather than widen.', false),
  ('ad', 18, 'A client with a T1 spinal cord injury suddenly reports a pounding headache and blurred vision while sitting in a wheelchair. Which assessments should the nurse perform IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Blood pressure compared with the known baseline"}, {"id": "b", "text": "Bladder drainage and catheter patency"}, {"id": "c", "text": "Bowel status, including last bowel movement"}, {"id": "d", "text": "Serum electrolytes before any position change"}, {"id": "e", "text": "Sweating and flushing pattern above vs below injury"}]'::jsonb, '["a", "b", "c", "e"]', '(a) Correct: BP is checked immediately and compared to the known baseline. (b) Correct: bladder drainage and catheter patency are part of the trigger search. (c) Correct: bowel status, including last bowel movement, is part of the trigger search. (e) Correct: the sweating and flushing pattern above vs below the injury is an immediate vital assessment. (d) Wrong: AD calls for an immediate trigger search plus BP check, not delaying positioning for lab work.', true),
  ('ad', 19, 'During an episode of autonomic dysreflexia, a client with a T2 spinal cord injury has BP 184/106 mm Hg, heart rate 48/min, and sweating and flushing of the face. A student nurse asks why the heart rate is slow. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "The slow rate shows that the episode is already resolving"}, {"id": "b", "text": "The slow rate means the trigger is located above the injury"}, {"id": "c", "text": "Parasympathetic compensation above the injury slows the heart"}, {"id": "d", "text": "The slow rate is from vasoconstriction above the injury level"}]'::jsonb, '["c"]', 'Parasympathetic compensation above the injury causes flushing, sweating, and a slowed heart rate, but it cannot correct the dangerous BP rise. Vasoconstriction occurs below, not above, the injury, and the BP of 184/106 shows the episode is not resolving.', false),
  ('ad', 20, 'A client with a T4 spinal cord injury is in active labor. She suddenly reports a severe pounding headache and blurred vision; BP is 158/96 mm Hg (baseline 100/62 mm Hg) and her face is flushed. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The BP rise is a normal response to labor and needs recheck later"}, {"id": "b", "text": "Labor below the injury is triggering autonomic dysreflexia"}, {"id": "c", "text": "Flushing above the injury shows the episode is resolving"}, {"id": "d", "text": "The headache is unrelated because labor is felt below the injury"}]'::jsonb, '["b"]', 'Labor in pregnancy is a listed trigger, and a T4 injury with a pounding headache, blurred vision, flushing, and a systolic rise of 58 mm Hg above baseline indicates AD. Treating the rise as a normal labor response delays care for a medical emergency.', false),
  ('ad', 21, 'A home health nurse reviews the symptom log of a client with a C6 spinal cord injury who has recurrent pounding headaches with BP spikes. Which log entries describe likely triggers of these episodes? Select all that apply.', '[{"id": "a", "text": "Began right after a recent catheterization"}, {"id": "b", "text": "Felt anxious and had a sense of doom"}, {"id": "c", "text": "Blocked / kinked catheter under the cushion"}, {"id": "d", "text": "UTI and bladder spasms the day before"}, {"id": "e", "text": "Tight clothing and a constrictive leg-bag strap"}]'::jsonb, '["a", "c", "d", "e"]', '(a) Correct: recent catheterization is a listed bladder trigger. (c) Correct: a blocked or kinked catheter is a common bladder trigger. (d) Correct: UTI is a listed bladder trigger. (e) Correct: tight clothing and constrictive items can be triggers. (b) Wrong: anxiety or a feeling of doom is a sign of AD, not a trigger.', true),
  ('ad', 22, 'The partner of a client with a C6 spinal cord injury calls the clinic. During sexual activity the client developed a pounding headache and facial sweating. He is now sitting upright and his catheter is draining, but after 10 minutes the headache is worse and BP is 190/110 mm Hg (baseline 100/64 mm Hg). What is the BEST instruction by the nurse?', '[{"id": "a", "text": "Lie him flat and recheck his BP in 30 minutes"}, {"id": "b", "text": "Give him an over-the-counter pain reliever and rest"}, {"id": "c", "text": "Wait to see whether the symptoms settle on their own in an hour"}, {"id": "d", "text": "Seek urgent help now because symptoms are not improving"}]'::jsonb, '["d"]', 'Family teaching is to seek urgent help if symptoms do not improve rapidly; this client is upright with a draining catheter yet the headache and BP are worsening. Waiting or lying flat ignores that AD is an emergency and that sitting upright helps lower BP.', false),
  ('ad', 23, 'A client with a T2 spinal cord injury who is wearing new tight shoes and a snug abdominal binder reports a throbbing headache. BP is 166/98 mm Hg (baseline 98/62 mm Hg). The nurse has raised the HOB to near 90 degrees. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Loosen or remove the binder and the tight shoes"}, {"id": "b", "text": "Check the catheter for kinks before anything else"}, {"id": "c", "text": "Give the prescribed rapid-acting antihypertensive"}, {"id": "d", "text": "Perform a careful digital check for fecal impaction"}]'::jsonb, '["a"]', 'After sitting the patient upright, the next step is to loosen or remove restrictive clothing, because tight clothing, shoes, and waistbands can be triggers. Checking the catheter comes after loosening clothing and starting BP monitoring.', false),
  ('ad', 24, 'A client with a C7 spinal cord injury and an indwelling catheter calls the nurse to the bedside. Which client reports should make the nurse suspect autonomic dysreflexia? Select all that apply.', '[{"id": "a", "text": "A dull headache that has slowly built over several days"}, {"id": "b", "text": "A sudden severe pounding headache"}, {"id": "c", "text": "Nasal congestion and blurred vision"}, {"id": "d", "text": "Warm, flushed skin on both legs"}, {"id": "e", "text": "Chest tightness and a feeling of doom"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: a sudden severe pounding headache is a classic sign. (c) Correct: nasal congestion and blurred vision are part of the classic presentation. (e) Correct: chest tightness and anxiety or a feeling of doom are other signs. (a) Wrong: the AD headache is sudden, not slowly building over days. (d) Wrong: skin below the injury is pale and cool from vasoconstriction; flushing occurs above the injury.', true),
  ('ad', 25, 'A client with a C5 spinal cord injury says, ''I just have a slightly stuffy nose and a mild headache, so I don''t feel that bad.'' BP is 150/90 mm Hg (baseline 96/60 mm Hg). Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure the client and recheck the BP in 1 hour"}, {"id": "b", "text": "Give a decongestant for the nasal congestion"}, {"id": "c", "text": "Treat it as AD, since early episodes can be milder"}, {"id": "d", "text": "Document the findings as a routine vital sign change"}]'::jsonb, '["c"]', 'Some patients have ''silent'' or milder early episodes, and this client''s systolic BP is 54 mm Hg above baseline with nasal congestion and headache, so it must be treated as AD. Reassuring and rechecking later delays treatment and raises the risk of stroke and seizure.', false),
  ('ad', 26, 'After an episode of autonomic dysreflexia caused by a full bladder, a client with a T3 spinal cord injury says, ''I had no idea my bladder could cause these headaches, and I don''t know what to do when one starts.'' Which nursing diagnosis BEST fits this data?', '[{"id": "a", "text": "Acute pain"}, {"id": "b", "text": "Deficient knowledge"}, {"id": "c", "text": "Ineffective tissue perfusion"}, {"id": "d", "text": "Autonomic dysregulation"}]'::jsonb, '["b"]', 'The client''s statement shows a lack of understanding about triggers and the emergency response, which defines deficient knowledge. Acute pain describes the pounding headache during an episode, but the data here focus on the client''s knowledge gap.', false),
  ('ad', 27, 'A client with a C6 spinal cord injury has BP 176/100 mm Hg (baseline 98/64 mm Hg) and a pounding headache. The nurse has raised the HOB to near 90 degrees. Which actions should the nurse take NEXT? Select all that apply.', '[{"id": "a", "text": "Lower the HOB to inspect the sacral skin"}, {"id": "b", "text": "Loosen any restrictive clothing"}, {"id": "c", "text": "Give an antihypertensive before the trigger search"}, {"id": "d", "text": "Monitor BP every 2–3 minutes"}, {"id": "e", "text": "Check the urinary catheter for kinks"}]'::jsonb, '["b", "d", "e"]', '(b) Correct: loosening restrictive clothing is step 2. (d) Correct: BP is monitored every 2–3 minutes while the cause is found. (e) Correct: the urinary catheter is checked as the first priority of the trigger search. (a) Wrong: the patient must stay upright because the orthostatic effect helps lower BP. (c) Wrong: antihypertensive therapy is for BP that stays elevated or a trigger that is not found.', true),
  ('ad', 28, 'Thirty minutes after a kinked catheter was straightened, a client with a T2 spinal cord injury has BP 108/68 mm Hg (baseline 102/64 mm Hg). Which finding in this client requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Urine draining freely into the collection bag"}, {"id": "b", "text": "Client reports feeling tired after the episode"}, {"id": "c", "text": "Heart rate of 64/min with the headache resolved"}, {"id": "d", "text": "New neurologic changes, such as confusion"}]'::jsonb, '["d"]', 'Even after BP stabilizes, the nurse continues monitoring for complications such as neurologic changes, which may signal stroke. Free urine drainage and a resolved headache show the trigger was removed and the episode is resolving.', false),
  ('ad', 29, 'The nurse reviews emergency teaching with a client who has a T1 spinal cord injury and a history of autonomic dysreflexia. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll wait to see if a headache goes away before acting."}, {"id": "b", "text": "I''ll carry a wallet card with my emergency information."}, {"id": "c", "text": "I''ll sit upright right away and check my bladder first."}, {"id": "d", "text": "I''ll report any change in my usual symptoms to the care team."}]'::jsonb, '["a"]', 'AD is an emergency and the patient must not wait to act, so waiting to see if a headache goes away needs correction. Carrying a wallet card, sitting upright and checking the bladder first, and reporting changes in usual symptoms are all correct teaching.', false),
  ('ad', 30, 'A client with a C4 spinal cord injury has a severe pounding headache rated 9/10 and BP 196/112 mm Hg (baseline 96/60 mm Hg); a blocked catheter has not yet been cleared. Which nursing diagnoses BEST match these data? Select all that apply.', '[{"id": "a", "text": "Social isolation"}, {"id": "b", "text": "Imbalanced nutrition: less than body requirements"}, {"id": "c", "text": "Acute pain"}, {"id": "d", "text": "Risk for injury"}, {"id": "e", "text": "Self-care deficit related to hygiene"}]'::jsonb, '["c", "d"]', '(c) Correct: acute pain matches the sudden pounding headache. (d) Correct: risk for injury matches the danger of stroke, seizure, or other severe hypertension complications. (a) Wrong: no data show reduced social interaction. (b) Wrong: no data show inadequate intake. (e) Wrong: no data show difficulty with hygiene; the problem is an acute hypertensive emergency.', true),
  ('ad', 31, 'During an episode of autonomic dysreflexia in a client with a T3 spinal cord injury, BP is 178/104 mm Hg (baseline 100/62 mm Hg). The bladder has been ruled out, and the nurse suspects fecal impaction. Which action by a newly hired nurse requires IMMEDIATE intervention?', '[{"id": "a", "text": "Keeping the client sitting upright while assessing the bowel"}, {"id": "b", "text": "Continuing to check the BP every 2 to 3 minutes"}, {"id": "c", "text": "Vigorous rectal stimulation to empty the rectum fast"}, {"id": "d", "text": "Following emergency guidance for bowel care"}]'::jsonb, '["c"]', 'Bowel care should follow emergency guidance because rectal stimulation itself can worsen AD if not managed carefully, so vigorous stimulation must be stopped. Keeping the client upright and monitoring BP every 2–3 minutes are correct.', false),
  ('ad', 32, 'A client with a T4 spinal cord injury has recurrent episodes of autonomic dysreflexia even though the urinary catheter drains well. Which bowel findings could be triggering the episodes? Select all that apply.', '[{"id": "a", "text": "Soft, formed stool each morning per the bowel program"}, {"id": "b", "text": "Constipation for the past 4 days"}, {"id": "c", "text": "Fecal impaction found on assessment"}, {"id": "d", "text": "Bowel distention on abdominal assessment"}, {"id": "e", "text": "Recent rectal procedures"}]'::jsonb, '["b", "c", "d", "e"]', '(b) Correct: constipation is a bowel trigger. (c) Correct: fecal impaction is a bowel trigger. (d) Correct: bowel distention is a bowel trigger. (e) Correct: rectal procedures are a listed bowel trigger. (a) Wrong: regular stool with an effective bowel program is the prevention goal, not a trigger.', true),
  ('ad', 33, 'A client with a C6 spinal cord injury suddenly develops a pounding headache, facial flushing, and BP 174/102 mm Hg (baseline 98/62 mm Hg). Actions: 1) check the urinary catheter; 2) sit the client upright; 3) assess for bowel impaction; 4) loosen restrictive clothing. Which order of actions is BEST?', '[{"id": "a", "text": "1, 2, 4, 3"}, {"id": "b", "text": "2, 1, 3, 4"}, {"id": "c", "text": "4, 2, 1, 3"}, {"id": "d", "text": "2, 4, 1, 3"}]'::jsonb, '["d"]', 'The emergency steps are to sit the patient upright, loosen clothing, then search for the trigger with the bladder first and bowel second. Starting with the catheter check is tempting because the bladder is the most common trigger, but positioning comes first.', false),
  ('ad', 34, 'A client with a T2 spinal cord injury and his caregiver attend a follow-up visit after two episodes of autonomic dysreflexia. Which statements indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "We can stop his regular bowel programs once episodes stop."}, {"id": "b", "text": "We''ll keep his bladder empty with scheduled emptying."}, {"id": "c", "text": "We''ll avoid tight clothing and constrictive items."}, {"id": "d", "text": "We''ll learn his personal trigger patterns over time."}, {"id": "e", "text": "Nasal congestion and blurred vision don''t need a BP check."}]'::jsonb, '["a", "e"]', '(a) Needs teaching: regular bladder and bowel programs must be maintained to prevent episodes. (e) Needs teaching: nasal congestion and blurred vision are AD symptoms, and BP should be checked quickly if any symptoms begin. (b) Correct teaching: keep the bladder empty with scheduled emptying. (c) Correct teaching: avoid tight clothing and constrictive items. (d) Correct teaching: learn personal trigger patterns over time.', true),
  ('ad', 35, 'A client with a T4 spinal cord injury has BP 180/106 mm Hg (baseline 102/66 mm Hg) and a pounding headache. The nurse has not yet repositioned the client or begun a trigger search. Which action planned by the nurse requires follow-up by the charge nurse?', '[{"id": "a", "text": "Raising the HOB to near 90 degrees right away"}, {"id": "b", "text": "Giving antihypertensive therapy before sitting the patient up"}, {"id": "c", "text": "Loosening the client''s tight waistband and shoe straps"}, {"id": "d", "text": "Checking the catheter for kinks and drainage"}]'::jsonb, '["b"]', 'The first action is to sit the patient upright and then find and remove the trigger; rapid-acting antihypertensive therapy is for BP that stays elevated or a trigger that is not found. Raising the HOB, loosening clothing, and checking the catheter follow the correct sequence.', false),
  ('ad', 36, 'A client with a C5 spinal cord injury has a sacral pressure injury and continues to have episodes of autonomic dysreflexia even though the catheter drains well and the bowel program is effective. Which intervention is MOST likely to prevent further episodes?', '[{"id": "a", "text": "Regular repositioning and pressure injury prevention"}, {"id": "b", "text": "More frequent catheter changes to keep urine flowing"}, {"id": "c", "text": "Adding a second daily bowel program session"}, {"id": "d", "text": "Keeping the HOB flat at night to rest the skin"}]'::jsonb, '["a"]', 'With bladder and bowel controlled, the pressure injury is the likely trigger, and preventing skin breakdown with regular repositioning and pressure injury prevention addresses it. Extra catheter or bowel interventions target causes that have already been ruled out.', false),
  ('ad', 37, 'The nurse is planning autonomic dysreflexia education on a spinal cord injury unit. Which clients should the nurse identify as being at risk for autonomic dysreflexia? Select all that apply.', '[{"id": "a", "text": "A patient with a traumatic C4 injury"}, {"id": "b", "text": "A patient with a traumatic T10 injury"}, {"id": "c", "text": "A patient with a nontraumatic T6 injury"}, {"id": "d", "text": "A patient with a traumatic T2 injury"}, {"id": "e", "text": "A patient with a nontraumatic L2 injury"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: cervical injuries carry the highest risk. (c) Correct: the injury is at T6, and both traumatic and nontraumatic SCI carry risk. (d) Correct: upper thoracic injuries are at or above T6. (b) Wrong: T10 is below T6. (e) Wrong: L2 is below T6.', true),
  ('ad', 38, 'The daughter of a client with a C6 spinal cord injury whose usual BP is about 90/60 mm Hg is learning to monitor her father at home. Which statement by the daughter indicates understanding?', '[{"id": "a", "text": "A reading of 120/76 is normal for most adults, so I won''t worry."}, {"id": "b", "text": "I only need to act if his top number goes above 160."}, {"id": "c", "text": "A reading of 120/76 with a headache means I need to act now."}, {"id": "d", "text": "His low baseline means he can''t really develop high BP."}]'::jsonb, '["c"]', 'A systolic of 120 is 30 mm Hg above this client''s baseline of 90, which exceeds the 20 mm Hg threshold, so with a headache it signals AD. Comparing to average adult values is the tempting error, because baseline BP in high-level SCI is often lower than average.', false),
  ('ad', 39, 'A client with a T1 spinal cord injury has BP 168/100 mm Hg (baseline 104/66 mm Hg) and says, ''It''s just a headache, so why is everyone rushing?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Your BP is high, but this is a routine vital sign change."}, {"id": "b", "text": "We are rushing only because the headache is so painful."}, {"id": "c", "text": "Headaches like this usually pass once you lie down flat."}, {"id": "d", "text": "Untreated, this can cause stroke, seizures, or death."}]'::jsonb, '["d"]', 'A systolic rise of 64 mm Hg with headache indicates AD, which requires immediate treatment because untreated it can cause stroke, seizures, cardiac complications, or death. Calling it a routine vital sign change is wrong; it is a medical emergency.', false),
  ('ad', 40, 'A client with a C5 spinal cord injury who has had two episodes of autonomic dysreflexia is preparing to travel alone for a week. Which plan by the client indicates understanding of safe self-management?', '[{"id": "a", "text": "I''ll skip my bowel program while traveling to save time."}, {"id": "b", "text": "I''ll carry a wallet card with my emergency information."}, {"id": "c", "text": "I''ll wear snug clothes so my catheter stays in place."}, {"id": "d", "text": "I''ll wait until I get home to check any new headache."}]'::jsonb, '["b"]', 'Ongoing education includes carrying emergency information or a wallet card. Skipping the bowel program and wearing snug clothes add triggers, and waiting to check a headache ignores that AD is an emergency.', false),
  ('ad', 41, 'A 24-year-old client with a T3 spinal cord injury asks which everyday situations could set off autonomic dysreflexia. Which situations should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Sitting upright in a wheelchair"}, {"id": "b", "text": "Menstrual cramps"}, {"id": "c", "text": "A sore throat or earache"}, {"id": "d", "text": "Sexual activity or genital irritation"}, {"id": "e", "text": "Heavy sweating above the injury"}]'::jsonb, '["b", "d"]', '(b) Correct: menstrual cramps are a listed trigger below the injury. (d) Correct: sexual activity or genital irritation is a listed trigger. (a) Wrong: sitting upright is the first treatment action, not a trigger. (c) Wrong: triggers are painful stimuli below the injury level; the throat and ear are above it. (e) Wrong: heavy sweating above the injury is a symptom, not a trigger.', true),
  ('ad', 42, 'A client with a C6 spinal cord injury has a pounding headache and BP 170/98 mm Hg (baseline 100/62 mm Hg). The catheter is patent and no stool is present. Skin inspection reveals a wrinkled sheet under the sacrum and tight shoe straps on swollen feet. Which action is BEST?', '[{"id": "a", "text": "Notify the provider before making any changes to the bed"}, {"id": "b", "text": "Lower the HOB flat so the sheet can be fully smoothed"}, {"id": "c", "text": "Remove the trigger: smooth sheets and loosen the shoes"}, {"id": "d", "text": "Document the findings and recheck BP in 1 hour"}]'::jsonb, '["c"]', 'BP remains dangerously high until the trigger is removed, so the nurse eliminates the wrinkled sheet and tight shoes. The provider is notified if BP stays elevated or no trigger is found, and lowering the HOB loses the orthostatic effect.', false),
  ('ad', 43, 'The spouse of a client with a C7 spinal cord injury caused by a tumor says, ''The doctor mentioned dysreflexia, but that only happens after accidents, right?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, it occurs only after a traumatic spinal cord injury."}, {"id": "b", "text": "Nontraumatic SCI at or above T6 also carries risk."}, {"id": "c", "text": "Injuries below T6 carry the greater risk for this problem."}, {"id": "d", "text": "Risk is lower with higher injuries such as cervical ones."}]'::jsonb, '["b"]', 'Both traumatic and nontraumatic SCI at or above T6 carry risk, so a C7 tumor-related injury is at risk. A higher injury level means greater risk, so cervical injuries carry the highest risk, not the lowest.', false),
  ('ad', 44, 'A client with a T2 spinal cord injury had an episode of autonomic dysreflexia that took 25 minutes to resolve. Which findings over the following hours should the nurse report to the provider? Select all that apply.', '[{"id": "a", "text": "New neurologic changes"}, {"id": "b", "text": "Chest pain"}, {"id": "c", "text": "Worsening headache"}, {"id": "d", "text": "Persistent hypertension"}, {"id": "e", "text": "BP back at the client''s baseline"}]'::jsonb, '["a", "b", "c", "d"]', '(a) Correct: neurologic changes are a complication to monitor for. (b) Correct: chest pain is a complication to monitor for. (c) Correct: worsening headache is a listed complication sign. (d) Correct: persistent hypertension is a listed complication sign. (e) Wrong: BP back at baseline shows the episode has resolved.', true),
  ('ad', 45, 'A client with a T1 spinal cord injury has had three episodes of pounding headache with BP spikes this week; the catheter is patent and the bowel program is effective. Which finding MOST likely explains the recurrent episodes?', '[{"id": "a", "text": "Heart rate of 54/min during each episode"}, {"id": "b", "text": "Sweating and flushing above the injury"}, {"id": "c", "text": "Anxiety and a feeling of doom"}, {"id": "d", "text": "Bladder spasms from a confirmed UTI"}]'::jsonb, '["d"]', 'UTI and bladder spasms are listed bladder triggers, which are the most common cause of AD. Bradycardia, sweating and flushing above the injury, and anxiety are signs of the episodes, not their cause.', false),
  ('ad', 46, 'A client with a C6 spinal cord injury had BP 178/102 mm Hg (baseline 100/64 mm Hg) and a pounding headache; a kinked catheter was then straightened. Which finding BEST indicates that the intervention was effective?', '[{"id": "a", "text": "BP 104/66 mm Hg and the headache has resolved"}, {"id": "b", "text": "BP 150/90 mm Hg and the headache is less severe"}, {"id": "c", "text": "Heart rate has dropped from 60/min to 50/min"}, {"id": "d", "text": "Sweating above the injury level has increased"}]'::jsonb, '["a"]', 'Removing the trigger brings the BP down, so a return to near baseline with the headache resolved shows success. A BP of 150/90 is still 50 mm Hg above baseline and remains an AD-level rise.', false),
  ('ad', 47, 'A float nurse caring for a client with a T2 spinal cord injury says, ''His BP is 160/96 and he has a headache, but I''ll just recheck it on the later vital-sign round.'' The client''s baseline is 100/62 mm Hg. Which response by the charge nurse is BEST?', '[{"id": "a", "text": "Agree, since high BP is common in clients with SCI"}, {"id": "b", "text": "Suggest giving a pain reliever for the headache first"}, {"id": "c", "text": "This is an emergency, not a routine vital sign change"}, {"id": "d", "text": "Recheck the BP in 1 hour and then call the provider"}]'::jsonb, '["c"]', 'A systolic rise of 60 mm Hg with headache in a T2 injury indicates AD, which is a medical emergency, not a routine vital sign change. Delaying the recheck or treating the headache alone misses the need to act immediately.', false),
  ('ad', 48, 'Two hours after a rectal procedure, a client with a T3 spinal cord injury reports a sudden throbbing headache and nasal congestion. BP is 160/98 mm Hg (baseline 102/64 mm Hg), heart rate is 52/min, and skin below the injury is pale and cool with goosebumps. What does the nurse recognize is MOST likely happening?', '[{"id": "a", "text": "A parasympathetic response to the procedure below the injury"}, {"id": "b", "text": "Vasodilation below the injury from the rectal procedure"}, {"id": "c", "text": "A massive sympathetic response to a stimulus below the injury"}, {"id": "d", "text": "An expected rise in BP after a procedure that settles on its own"}]'::jsonb, '["c"]', 'A painful stimulus below the injury (a rectal procedure) triggers a massive sympathetic discharge with vasoconstriction below the injury, causing the BP rise, pale cool skin, and goosebumps. The parasympathetic response occurs above the injury, and BP stays high until the trigger is removed.', false),
  ('ad', 49, 'A client with a C6 spinal cord injury had two episodes of autonomic dysreflexia this month, each after skipping scheduled catheterizations while busy at work. Which teaching is the PRIORITY to prevent further episodes?', '[{"id": "a", "text": "Reposition every few hours to protect the skin"}, {"id": "b", "text": "Keep the bladder empty with scheduled emptying"}, {"id": "c", "text": "Avoid tight clothing and constrictive items"}, {"id": "d", "text": "Follow a regular bowel program each day"}]'::jsonb, '["b"]', 'This client''s episodes followed missed catheterizations, so keeping the bladder empty with proper catheter care or scheduled emptying addresses the actual trigger. Skin, clothing, and bowel measures are valid prevention steps but do not target this client''s pattern.', false),
  ('ad', 50, 'The day after a fall from a wheelchair, a client with a T3 spinal cord injury has a swollen, deformed left ankle and repeated pounding headaches with BP spikes. The catheter drains well and the bowel program is effective. Which finding is the MOST likely trigger?', '[{"id": "a", "text": "A likely fracture below the injury level"}, {"id": "b", "text": "Heart rate of 54/min during each spike"}, {"id": "c", "text": "Goosebumps below the injury level"}, {"id": "d", "text": "Flushing above the injury level"}]'::jsonb, '["a"]', 'Fractures below the injury are a listed trigger, and with the bladder and bowel already ruled out, the deformed ankle after a fall is the likely source. Bradycardia, goosebumps below the injury, and flushing above it are signs of the AD episode, not its cause.', false),
  ('brain_tumors', 1, 'A 58-year-old client with no history of seizures is brought to the emergency department after a first-ever tonic-clonic seizure at home. The spouse reports several weeks of headaches that are worse in the morning and when the client bends over. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The seizure most likely resulted from a minor head injury the client had in a fall 2 years ago"}, {"id": "b", "text": "A new-onset seizure in an adult with this headache pattern is a red flag for a brain tumor"}, {"id": "c", "text": "Morning headaches with a single seizure point to a benign process that does not need imaging"}, {"id": "d", "text": "A seizure is a late finding that appears only after Cushing''s triad has already developed"}]'::jsonb, '["b"]', 'A new seizure in an adult with no prior seizure history should raise concern for a brain tumor, and a headache worse in the morning or with bending is ICP-related. Head injury is tempting, but most brain tumors are NOT caused by head injury; trauma can reveal symptoms but is not a common direct cause.', false),
  ('brain_tumors', 2, 'A client with a glioblastoma has these vital signs: at 0800, BP 138/82 mm Hg, heart rate 84/min, respirations 16/min and regular; at 1000, BP 176/64 mm Hg, heart rate 52/min, respirations irregular. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Administer the prescribed analgesic for headache and reassess in 1 hour"}, {"id": "b", "text": "Lower the head of the bed flat to increase blood flow to the brain"}, {"id": "c", "text": "Report the findings immediately as signs of impending brain herniation"}, {"id": "d", "text": "Document the slower heart rate as a sign that the client is resting well"}]'::jsonb, '["c"]', 'Bradycardia, a widened pulse pressure (56 rising to 112 mm Hg), and irregular respirations form Cushing''s triad, a late and dangerous sign of impending brain herniation that must be reported at once. Lowering the bed flat contradicts ICP-safe positioning (HOB about 30 degrees), and an analgesic does not address the emergency.', false),
  ('brain_tumors', 3, 'A 34-year-old woman reports frequent headaches and says she keeps bumping into door frames on both sides. An MRI shows a mass at the base of the brain pressing on the optic chiasm. Which additional findings should the nurse expect to assess? Select all that apply.', '[{"id": "a", "text": "Loss of the outer halves of the visual fields in both eyes"}, {"id": "b", "text": "Ataxia with an unsteady gait"}, {"id": "c", "text": "Menstrual changes"}, {"id": "d", "text": "Galactorrhea unrelated to breastfeeding"}, {"id": "e", "text": "Spatial neglect of one side of the body"}]'::jsonb, '["a", "c", "d"]', 'A mass at the brain base pressing on the optic chiasm points to a pituitary tumor, which causes both pressure effects and hormone effects. (a) Correct: bitemporal hemianopsia is loss of the outer halves of both visual fields from optic chiasm pressure. (c) Correct: menstrual changes are a hormone effect. (d) Correct: galactorrhea (milk production unrelated to breastfeeding) is a hormone effect. (b) Wrong: ataxia and unsteady gait are cerebellum findings. (e) Wrong: spatial neglect is a parietal lobe finding.', true),
  ('brain_tumors', 4, 'The spouse of a 49-year-old accountant reports that over 3 months the client has become careless with money, makes poor decisions, shows little emotion in the face, and now has weakness of the right arm. The nurse recognizes that these findings are MOST consistent with a tumor in which area?', '[{"id": "a", "text": "Frontal lobe"}, {"id": "b", "text": "Parietal lobe"}, {"id": "c", "text": "Temporal lobe"}, {"id": "d", "text": "Cerebellum"}]'::jsonb, '["a"]', 'The frontal lobe controls behavior, judgment, personality, planning, and voluntary movement; tumors there cause personality changes, poor judgment, flat affect, and contralateral weakness. The parietal lobe handles sensation and spatial awareness, and the temporal lobe handles memory, hearing, and language comprehension.', false),
  ('brain_tumors', 5, 'On postoperative day 2 after a craniotomy for a meningioma, the nurse observes clear, watery drainage dripping from one nostril each time the client leans forward. The incision dressing is dry and intact. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Document the drainage as an expected finding after a craniotomy"}, {"id": "b", "text": "Give the prescribed analgesic and reassess the drainage in 4 hours"}, {"id": "c", "text": "Lower the head of the bed flat to decrease the flow of drainage"}, {"id": "d", "text": "Report the clear drainage promptly as a possible CSF leak"}]'::jsonb, '["d"]', 'Clear drainage from the nose after craniotomy may be a CSF leak, which must be reported promptly because it may increase the risk of meningitis. It is not an expected finding, and a dry dressing does not rule it out because CSF can escape through the nose or ear.', false),
  ('brain_tumors', 6, 'A client reports memory problems and episodes of hearing sounds that no one else hears. Imaging shows a tumor in the temporal lobe, and the client had a brief seizure in the emergency department. Which actions should the nurse include when setting up seizure precautions? Select all that apply.', '[{"id": "a", "text": "Apply soft wrist restraints if a seizure begins"}, {"id": "b", "text": "Pad the side rails"}, {"id": "c", "text": "Keep suction and oxygen at the bedside"}, {"id": "d", "text": "Place the bed in the lowest position"}, {"id": "e", "text": "Turn the client to the side during a seizure if possible"}]'::jsonb, '["b", "c", "d", "e"]', 'Temporal lobe tumors cause memory problems, auditory disturbances, and seizures. (b) Correct: padded side rails are part of the seizure safety setup. (c) Correct: suction and oxygen at the bedside are required. (d) Correct: bed in lowest position reduces injury. (e) Correct: turning the patient to the side if possible protects the airway. (a) Wrong: the patient must NOT be restrained during a seizure.', true),
  ('brain_tumors', 7, 'A nurse is caring for a client with a large frontal glioma. Four hours ago the client was alert and oriented; now the client is drowsy, oriented only to person, and slow to respond. Pupils are equal and reactive, and vital signs are unchanged. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Continue routine checks because pupils and vital signs are unchanged"}, {"id": "b", "text": "Report the decreased LOC immediately as a sign of worsening status"}, {"id": "c", "text": "Wait to report until Cushing''s triad confirms that the ICP is rising"}, {"id": "d", "text": "Allow the client to sleep because drowsiness is expected with this tumor"}]'::jsonb, '["b"]', 'Decreasing LOC is often the earliest and most important sign of worsening neurologic status and must be reported immediately, even when pupils and vital signs have not yet changed. Waiting for Cushing''s triad is unsafe because the triad is a late and dangerous sign of impending herniation.', false),
  ('brain_tumors', 8, 'A client who had a craniotomy 6 hours ago rates an incisional headache as 7 on a 0-10 scale. The client is alert with a Glasgow Coma Scale score of 15, and an opioid analgesic is prescribed as needed. Which nursing approach is BEST?', '[{"id": "a", "text": "Withhold the analgesic because any pain medication will mask neurologic changes"}, {"id": "b", "text": "Give the highest prescribed dose so the client can sleep through the night"}, {"id": "c", "text": "Give the analgesic and monitor neuro status to avoid oversedating the client"}, {"id": "d", "text": "Delay the analgesic until the provider rounds and assesses the incision site"}]'::jsonb, '["c"]', 'After craniotomy, pain should be controlled without oversedating the patient, because sedation masks neuro changes; analgesics are used carefully while monitoring neuro status. Withholding pain relief entirely is not the goal, and a high dose to promote sleep risks oversedation.', false),
  ('brain_tumors', 9, 'The nurse is reviewing home care with the family of a client being discharged after treatment for a glioma. The client had one seizure before surgery. Which statements by the family indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "If he has excessive drowsiness, we will let him sleep it off."}, {"id": "b", "text": "We will call the provider right away if he has trouble walking."}, {"id": "c", "text": "We will ask whether he can drive, since he has had a seizure."}, {"id": "d", "text": "If his personality changes, we will mention it at his follow-up visits."}, {"id": "e", "text": "We understand he may need rehabilitation after his treatment."}]'::jsonb, '["a", "d"]', '(a) Needs teaching: excessive drowsiness must be reported to the provider immediately, not slept off. (d) Needs teaching: a personality change must be reported immediately, not saved for the next visit. (b) Correct statement: gait problems are reported immediately. (c) Correct statement: families should ask about driving restrictions when seizures are present. (e) Correct statement: rehabilitation may be needed after treatment.', true),
  ('brain_tumors', 10, 'The nurse receives report on four clients with brain tumors on a neuro-oncology unit. Based on the information given, which client should the nurse assess FIRST?', '[{"id": "a", "text": "Meningioma; morning headache eased after the prescribed analgesic"}, {"id": "b", "text": "Acoustic neuroma; reports tinnitus and balance problems when walking"}, {"id": "c", "text": "Pituitary tumor; has galactorrhea and is scheduled for endocrine testing"}, {"id": "d", "text": "Brain metastases; previously alert, now has decreased LOC"}]'::jsonb, '["d"]', 'Decreased LOC is a major red flag for worsening neurologic status and must be reported immediately, so this client is seen first. Tinnitus and balance problems are expected with an acoustic neuroma, and galactorrhea is an expected hormone effect of a pituitary tumor.', false),
  ('brain_tumors', 11, 'A client with known lung cancer is brought to the emergency department with sudden confusion and decreasing responsiveness. The provider wants to quickly rule out bleeding or hydrocephalus from a brain lesion. Which diagnostic test does the nurse anticipate FIRST?', '[{"id": "a", "text": "CT scan of the head"}, {"id": "b", "text": "MRI of the brain"}, {"id": "c", "text": "Biopsy of the brain lesion"}, {"id": "d", "text": "Endocrine hormone testing"}]'::jsonb, '["a"]', 'CT is useful in urgent situations because it quickly identifies mass effect, bleeding, hydrocephalus, or edema and is faster than MRI. MRI is the best imaging to define many brain tumors in detail, but it is not the first choice in an emergency.', false),
  ('brain_tumors', 12, 'A client with a cerebellar tumor that is partially blocking CSF flow is being monitored closely on the neuro unit. Which new findings would the nurse recognize as signs of increased ICP? Select all that apply.', '[{"id": "a", "text": "Vomiting without nausea"}, {"id": "b", "text": "Papilledema on eye exam"}, {"id": "c", "text": "Posturing"}, {"id": "d", "text": "Pupillary changes"}, {"id": "e", "text": "Rising heart rate with a narrowing pulse pressure"}]'::jsonb, '["a", "b", "c", "d"]', 'Blocked CSF flow can raise ICP. (a) Correct: vomiting, especially without nausea, is a sign of increased ICP. (b) Correct: papilledema is swelling of the optic disc caused by increased ICP. (c) Correct: posturing is a sign of increased ICP. (d) Correct: pupillary changes are a sign of increased ICP. (e) Wrong: with rising ICP, Cushing''s triad brings bradycardia and a widened, not narrowed, pulse pressure.', true),
  ('brain_tumors', 13, 'After an MRI shows a mass in the left temporal lobe, a client asks, ''The scan already found the tumor. Why do I still need a biopsy?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "The biopsy is mainly done to relieve the pressure that the mass is causing."}, {"id": "b", "text": "The MRI already shows the grade, so the biopsy just rules out an infection."}, {"id": "c", "text": "A biopsy gives the definitive diagnosis and grade to guide treatment."}, {"id": "d", "text": "A biopsy is needed when the MRI suggests that the tumor is probably benign."}]'::jsonb, '["c"]', 'A biopsy removes tissue for microscopic exam and is needed for definitive diagnosis; it confirms the tumor grade and guides treatment. MRI defines the tumor in detail but does not provide the grade, which is based on how abnormal the cells look under the microscope.', false),
  ('brain_tumors', 14, 'A client with a meningioma that is compressing nearby brain tissue says, ''My doctor said it is benign, so it can''t really hurt me, and I don''t see why I need surgery.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Benign tumors grow slowly, so there is little risk to you unless the tumor becomes malignant."}, {"id": "b", "text": "Even a benign tumor can compress the brain and raise pressure because the skull cannot expand."}, {"id": "c", "text": "Surgery is recommended because benign brain tumors usually spread to the lungs and other organs."}, {"id": "d", "text": "Most meningiomas turn out to be malignant, so the word benign may not be accurate for your tumor."}]'::jsonb, '["b"]', 'Even a benign brain tumor can be life-threatening: the skull is rigid and cannot expand, so a growing mass compresses tissue, raises ICP, and can lead to herniation. Meningiomas are often benign, but benign does not mean safe in the brain.', false),
  ('brain_tumors', 15, 'A 62-year-old client newly diagnosed with a primary brain tumor asks what might have caused it. The nurse reviews the client''s history. Which findings are recognized risk factors for brain tumors? Select all that apply.', '[{"id": "a", "text": "Neurofibromatosis, an inherited genetic syndrome"}, {"id": "b", "text": "Concussion from a car crash 5 years ago"}, {"id": "c", "text": "Prior exposure to ionizing radiation to the head"}, {"id": "d", "text": "The client''s increasing age"}, {"id": "e", "text": "Repeated minor head injuries from contact sports"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: inherited genetic syndromes such as neurofibromatosis are risk factors. (c) Correct: prior exposure to ionizing radiation is a recognized risk factor. (d) Correct: increasing age is a risk factor for many adult tumors. (b) and (e) Wrong: most brain tumors are NOT caused by head injury; trauma can reveal symptoms but is not a common direct cause.', true),
  ('brain_tumors', 16, 'A client with brain metastases and marked cerebral edema suddenly develops unequal pupils and a drop in LOC. Prescriptions include dexamethasone, an anticonvulsant, an analgesic, and mannitol. Which prescribed medication is MOST appropriate to reduce ICP acutely?', '[{"id": "a", "text": "Dexamethasone"}, {"id": "b", "text": "The anticonvulsant"}, {"id": "c", "text": "The analgesic"}, {"id": "d", "text": "Mannitol"}]'::jsonb, '["d"]', 'Mannitol, an osmotic diuretic, draws fluid out of swollen brain tissue and reduces ICP acutely in critical care ICP crises. Dexamethasone is tempting because it reduces tumor-related cerebral edema, but it is used for ongoing edema management rather than as the acute ICP-crisis drug.', false),
  ('brain_tumors', 17, 'A client in the critical care unit is receiving mannitol for an ICP crisis related to a glioblastoma. Which assessment data are MOST important for the nurse to monitor specifically because of this medication?', '[{"id": "a", "text": "Fluid balance, blood pressure, and kidney function"}, {"id": "b", "text": "Sedation level, because the drug can mask neuro changes"}, {"id": "c", "text": "Tapering needs, because the drug must not be stopped abruptly"}, {"id": "d", "text": "Seizure activity, because the drug is given to prevent seizures"}]'::jsonb, '["a"]', 'Mannitol is used in ICP crises, and the nurse must monitor fluid balance, BP, and kidney function. Not stopping abruptly applies to corticosteroids such as dexamethasone, and seizure prevention is the purpose of anticonvulsants.', false),
  ('brain_tumors', 18, 'A client with a brainstem tumor coughs and chokes when drinking water, and the client''s LOC has decreased slightly since yesterday. Which actions are appropriate for the nurse to take? Select all that apply.', '[{"id": "a", "text": "Continue the regular diet until a swallow study is scheduled"}, {"id": "b", "text": "Assess swallow safety before any oral intake"}, {"id": "c", "text": "Implement aspiration precautions"}, {"id": "d", "text": "Lay the client flat after meals to lower the ICP"}, {"id": "e", "text": "Keep NPO or use enteral feeding if swallow is unsafe"}]'::jsonb, '["b", "c", "e"]', 'Brainstem tumors cause cranial nerve deficits, swallowing problems, and decreased LOC. (b) Correct: when cranial nerves or LOC are affected, assess swallow safety before oral intake. (c) Correct: aspiration precautions may be needed. (e) Correct: NPO or enteral feeding is used if swallow is unsafe. (a) Wrong: oral intake should not continue before swallow safety is assessed. (d) Wrong: ICP-safe positioning is HOB elevated about 30 degrees, not flat.', true),
  ('brain_tumors', 19, 'Eight hours after a craniotomy, a client who had been answering questions appropriately is now difficult to arouse, has snoring respirations, and has a right pupil larger than the left. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Calculate a complete Glasgow Coma Scale score now"}, {"id": "b", "text": "Protect the airway by positioning and suctioning"}, {"id": "c", "text": "Notify the provider about the unequal pupils"}, {"id": "d", "text": "Check the dressing and incision for drainage"}]'::jsonb, '["b"]', 'If LOC decreases, airway protection becomes the immediate priority, and snoring respirations signal a threatened airway. Reporting unequal pupils and decreased LOC is urgent and follows right after, but airway, breathing, and circulation come before neurologic status in the priority order.', false),
  ('brain_tumors', 20, 'A client reports recent memory problems, hearing sounds that others do not hear, and trouble understanding what people are saying. Imaging confirms a tumor in the brain region responsible for these functions. Which intervention is MOST important to add to the plan of care?', '[{"id": "a", "text": "Endocrine testing for hormone imbalance"}, {"id": "b", "text": "Teaching about bitemporal hemianopsia"}, {"id": "c", "text": "Seizure precautions with padded side rails"}, {"id": "d", "text": "Aspiration precautions for swallowing problems"}]'::jsonb, '["c"]', 'Memory problems, auditory disturbances, and language comprehension problems localize to the temporal lobe, where tumors also cause seizures, so seizure precautions are the priority addition. Hormone imbalance and bitemporal hemianopsia belong to pituitary tumors, and swallowing problems belong to brainstem tumors.', false),
  ('brain_tumors', 21, 'A client with a brain tumor ignores the food on the left side of the meal tray, cannot recognize a familiar comb placed in the left hand, and reports numbness of the left arm. The nurse recognizes these findings are MOST consistent with a tumor in which lobe?', '[{"id": "a", "text": "Parietal lobe"}, {"id": "b", "text": "Occipital lobe"}, {"id": "c", "text": "Frontal lobe"}, {"id": "d", "text": "Temporal lobe"}]'::jsonb, '["a"]', 'The parietal lobe controls sensation and spatial awareness; tumors there cause sensory loss, difficulty recognizing objects, and spatial neglect. The occipital lobe is tempting because of the missed food, but occipital tumors cause visual field defects, not sensory loss or trouble recognizing objects by touch.', false),
  ('brain_tumors', 22, 'A client with a large meningioma returns from the ophthalmology clinic, where the provider noted swelling of the optic disc in both eyes. The family asks what this finding means. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The tumor is pressing on the optic chiasm and causing loss of outer vision."}, {"id": "b", "text": "The swelling shows that the tumor has spread from the brain into the eyes."}, {"id": "c", "text": "The tumor is in the occipital lobe, which is the area that processes vision."}, {"id": "d", "text": "Pressure in the skull has been high long enough to affect the optic nerve."}]'::jsonb, '["d"]', 'Swelling of the optic disc is papilledema, caused by increased ICP; it suggests ICP has been elevated long enough to affect the optic nerve. Pressure on the optic chiasm causes bitemporal hemianopsia with pituitary tumors, which is a different finding.', false),
  ('brain_tumors', 23, 'A client returns to the neurosurgical unit after a craniotomy to debulk a glioma. Which actions should the nurse include in the PRIORITY postoperative plan of care? Select all that apply.', '[{"id": "a", "text": "Hold all analgesics so pain cannot mask neuro changes"}, {"id": "b", "text": "Perform frequent neuro checks"}, {"id": "c", "text": "Assess the dressing and incision site"}, {"id": "d", "text": "Watch for clear drainage that may be a CSF leak"}, {"id": "e", "text": "Monitor for signs of infection"}]'::jsonb, '["b", "c", "d", "e"]', '(b) Correct: frequent neuro checks are a post-op priority. (c) Correct: assess dressing and incision site. (d) Correct: watch for CSF leak, which may appear as clear drainage. (e) Correct: monitor for infection. (a) Wrong: pain should be controlled without oversedating the patient; it is sedation, not pain relief itself, that masks neuro changes.', true),
  ('brain_tumors', 24, 'The daughter of a client with a growing meningioma asks how a tumor that is not cancer can cause her father''s worsening symptoms. Which sequence BEST describes how the tumor causes harm?', '[{"id": "a", "text": "Compresses brain tissue, then vasogenic edema, then ICP rises, then cerebral perfusion falls"}, {"id": "b", "text": "Vasogenic edema, then ICP rises, then it compresses brain tissue, then cerebral perfusion falls"}, {"id": "c", "text": "Compresses brain tissue, then cerebral perfusion falls, then ICP rises, then vasogenic edema"}, {"id": "d", "text": "ICP rises, then vasogenic edema, then cerebral perfusion falls, then compresses brain tissue"}]'::jsonb, '["a"]', 'The tumor occupies space in the rigid skull and compresses nearby brain tissue; vasogenic edema then adds swelling, CSF flow may be obstructed, ICP rises, and cerebral perfusion falls so less oxygenated blood reaches brain cells. Falling perfusion is the result of rising ICP, not its cause.', false),
  ('brain_tumors', 25, 'The biopsy report for a 55-year-old client''s astrocytic tumor states ''grade 4.'' The client''s spouse asks the nurse what the grade means for the client. Which response by the nurse is BEST?', '[{"id": "a", "text": "Grade describes the size of the tumor as measured on the MRI."}, {"id": "b", "text": "A grade 4 tumor usually grows more slowly than a grade 1 tumor."}, {"id": "c", "text": "A higher grade usually means faster growth and worse prognosis."}, {"id": "d", "text": "Grade 4 means the tumor spread to the brain from another organ."}]'::jsonb, '["c"]', 'Higher grade (3 or 4) usually means faster growth, more invasion, and a worse prognosis. Grade describes how abnormal the cells look under the microscope, not tumor size, and spread from elsewhere describes a metastatic tumor.', false),
  ('brain_tumors', 26, 'A 64-year-old client treated for lung cancer 1 year ago now reports new headaches and had a seizure. An MRI shows multiple brain lesions with marked cerebral edema. Which statement by the client indicates understanding of the diagnosis?', '[{"id": "a", "text": "These tumors started in my brain and then spread to my lungs."}, {"id": "b", "text": "The cancer from my lung has spread to my brain."}, {"id": "c", "text": "Having several lesions means these are benign tumors from an old injury."}, {"id": "d", "text": "Since there are several lesions, they must be meningiomas from the brain coverings."}]'::jsonb, '["b"]', 'A metastatic brain tumor spreads to the brain from cancer elsewhere, such as the lung, and brain metastases may cause multiple lesions and marked cerebral edema. A tumor that started in the brain would be primary, and meningiomas arise from the meninges.', false),
  ('brain_tumors', 27, 'A new nurse is caring for several clients with different brain tumors. Which statements by the new nurse are inaccurate and require follow-up by the preceptor? Select all that apply.', '[{"id": "a", "text": "Glioblastoma is a highly aggressive astrocytic tumor with the worst prognosis."}, {"id": "b", "text": "A meningioma arises from the meninges, the protective brain coverings."}, {"id": "c", "text": "An acoustic neuroma arises from the vestibulocochlear nerve."}, {"id": "d", "text": "Brain metastases are rare in adults because most tumors start in the brain."}, {"id": "e", "text": "A meningioma is often benign, so it cannot cause serious pressure symptoms."}]'::jsonb, '["d", "e"]', '(d) Inaccurate: brain metastases are very common in adults, more common than many primary malignant tumors. (e) Inaccurate: a meningioma is often benign but can still cause serious pressure symptoms. (a) Accurate: glioblastoma is a highly aggressive, high-grade astrocytic tumor with the worst prognosis in adult primary brain tumors. (b) Accurate: meningiomas arise from the meninges. (c) Accurate: acoustic neuromas arise from the vestibulocochlear nerve.', true),
  ('brain_tumors', 28, 'A 45-year-old client reports gradual hearing loss in one ear, tinnitus in that ear, and worsening balance problems. Imaging shows a usually benign tumor along a cranial nerve. The nurse recognizes the tumor MOST likely arises from which structure?', '[{"id": "a", "text": "The meninges covering the brain"}, {"id": "b", "text": "The cerebellum"}, {"id": "c", "text": "The temporal lobe"}, {"id": "d", "text": "The vestibulocochlear nerve"}]'::jsonb, '["d"]', 'An acoustic neuroma (vestibular schwannoma) arises from the vestibulocochlear nerve, which controls hearing and balance, and causes hearing loss, tinnitus, and balance problems. The cerebellum causes balance problems and the temporal lobe causes auditory disturbances, but neither is a cranial nerve.', false),
  ('brain_tumors', 29, 'A client discharged on dexamethasone for tumor-related cerebral edema calls the clinic and says, ''My headaches are gone, so I stopped taking the dexamethasone 2 days ago.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Steroids should not be stopped abruptly; I will call your provider now."}, {"id": "b", "text": "That is fine, because the steroid was needed only while you had headaches."}, {"id": "c", "text": "Take a double dose today to make up for the doses that you missed."}, {"id": "d", "text": "Switch to an over-the-counter pain reliever if the headaches return."}]'::jsonb, '["a"]', 'Patients must take corticosteroids exactly as prescribed and must NOT stop steroids abruptly unless instructed by the provider. Dexamethasone is given to reduce tumor-related cerebral edema, not only for headache relief, so stopping it on the client''s own is unsafe.', false),
  ('brain_tumors', 30, 'A client with a frontal glioma is being monitored hourly. Since the last check, heart rate has fallen from 82/min to 50/min and BP has changed from 132/80 to 184/70 mm Hg. Which findings in the current assessment require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "The fall in heart rate to 50/min"}, {"id": "b", "text": "The widened pulse pressure"}, {"id": "c", "text": "Respirations that have become irregular"}, {"id": "d", "text": "Flat affect that has been present since admission"}, {"id": "e", "text": "Pupils that were equal and are now unequal"}]'::jsonb, '["a", "b", "c", "e"]', '(a) Correct: bradycardia is part of Cushing''s triad. (b) Correct: pulse pressure widened from 52 to 114 mm Hg, part of Cushing''s triad. (c) Correct: irregular respirations complete Cushing''s triad, which indicates impending brain herniation. (e) Correct: unequal pupils must be reported at once. (d) Wrong: flat affect is an expected frontal lobe finding and has not changed.', true),
  ('brain_tumors', 31, 'A 70-year-old client has a small, slow-growing meningioma found on imaging done after a fall. The client has no symptoms, and the provider recommends surveillance. Which statement by the client indicates understanding of this plan?', '[{"id": "a", "text": "Since nothing is being done right now, I will not need any more scans."}, {"id": "b", "text": "I will keep my scheduled imaging appointments so changes can be found."}, {"id": "c", "text": "This plan means the tumor is malignant and that it cannot be treated."}, {"id": "d", "text": "Surveillance means I will have focused radiation in one or two sessions."}]'::jsonb, '["b"]', 'Surveillance is watchful waiting with serial imaging for slow-growing or asymptomatic tumors, so keeping imaging appointments is essential. Focused radiation in one or a few sessions describes radiosurgery, not surveillance.', false),
  ('brain_tumors', 32, 'A client with two small brain metastases is scheduled for radiosurgery and says, ''I''m scared about them cutting my skull open again like my last surgery.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Radiosurgery opens the skull through a smaller incision than a craniotomy."}, {"id": "b", "text": "Radiosurgery is a type of chemotherapy that is given directly into the brain."}, {"id": "c", "text": "Radiosurgery is highly focused radiation, not traditional open surgery."}, {"id": "d", "text": "Radiosurgery requires daily treatments for several months after surgery."}]'::jsonb, '["c"]', 'Radiosurgery is highly focused radiation delivered in one or a few sessions and is not traditional open surgery; it is used for some tumors or metastases. Chemotherapy is drug therapy that kills or slows cancer cell growth, a different treatment.', false),
  ('brain_tumors', 33, 'A client admitted with a brain tumor had a Glasgow Coma Scale score of 14 at 1600. At 1800 the score is 11, and the client is now harder to arouse and confused. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Recheck the GCS in 4 hours to see whether the trend continues"}, {"id": "b", "text": "Document the score as an expected fluctuation with a brain tumor"}, {"id": "c", "text": "Give the prescribed analgesic because headache can lower the score"}, {"id": "d", "text": "Report the declining GCS score to the provider immediately"}]'::jsonb, '["d"]', 'A declining GCS score is alarming and must be reported immediately, because decreased LOC is a major red flag for worsening neurologic status. Waiting 4 hours or treating it as an expected fluctuation delays care, and analgesics must be used carefully with neuro monitoring.', false),
  ('brain_tumors', 34, 'A nurse on a neuro-oncology unit is deciding which clients need fall precautions. Which clients'' findings increase their fall risk? Select all that apply.', '[{"id": "a", "text": "A client with a frontal lobe tumor who shows poor judgment"}, {"id": "b", "text": "A client with an occipital lobe tumor who has visual field defects"}, {"id": "c", "text": "A client with a pituitary tumor whose only finding is galactorrhea"}, {"id": "d", "text": "A client with a cerebellar tumor who has an unsteady gait"}, {"id": "e", "text": "A client with a brainstem tumor who has new weakness"}]'::jsonb, '["a", "b", "d", "e"]', 'Weakness, visual deficits, poor balance, or altered judgment all increase fall risk. (a) Correct: poor judgment from a frontal lobe tumor is altered judgment. (b) Correct: visual field defects from an occipital tumor are visual deficits. (d) Correct: unsteady gait from a cerebellar tumor is poor balance. (e) Correct: weakness from a brainstem tumor increases fall risk. (c) Wrong: galactorrhea is a hormone effect that does not affect balance, vision, strength, or judgment.', true),
  ('brain_tumors', 35, 'A client with a brain tumor and signs of increased ICP has the head of the bed elevated 30 degrees. Which action by the unlicensed assistive personnel (UAP) requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Positions the head in extreme neck flexion"}, {"id": "b", "text": "Keeps the head midline during a linen change"}, {"id": "c", "text": "Returns the bed to the lowest position after care"}, {"id": "d", "text": "Reports that the client vomited without nausea"}]'::jsonb, '["a"]', 'ICP-safe positioning requires avoiding extreme neck flexion, so sharply flexing the neck must be stopped. Keeping the head midline and the bed low are correct, and reporting vomiting is appropriate because vomiting is a sign of increased ICP.', false),
  ('brain_tumors', 36, 'A client with a large frontal tumor reports a worsening headache, and the nurse notes new vomiting. There is no contraindication to head elevation. While the nurse notifies the provider, which position is BEST for this client?', '[{"id": "a", "text": "Supine and flat, with the head turned toward the tumor side"}, {"id": "b", "text": "Head of bed elevated about 30 degrees with the head midline"}, {"id": "c", "text": "Head of bed elevated 30 degrees with the chin flexed to the chest"}, {"id": "d", "text": "Side-lying and flat, with the head of the bed fully lowered"}]'::jsonb, '["b"]', 'ICP-safe positioning is HOB elevated about 30 degrees unless contraindicated, with the head kept midline. Elevating the bed while flexing the chin to the chest is tempting, but extreme neck flexion must be avoided.', false),
  ('brain_tumors', 37, 'A client with a brain tumor and morning headaches has not had a bowel movement for 3 days and says, ''I''m going to push as hard as I can until something comes out.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Pushing hard is fine as long as you keep the head of the bed flat."}, {"id": "b", "text": "Hold your breath and bear down hard so that you can finish more quickly."}, {"id": "c", "text": "Avoid straining, because bearing down can raise pressure in your skull."}, {"id": "d", "text": "Push as hard as you need to, but call me if you feel dizzy afterward."}]'::jsonb, '["c"]', 'Activities that raise ICP, such as excessive straining and the Valsalva maneuver, should be avoided in a client with a brain tumor. Holding the breath and bearing down is the Valsalva maneuver, and a flat bed contradicts ICP-safe positioning.', false),
  ('brain_tumors', 38, 'A client with a brain tumor has vomited three times this shift and now reports a worsening headache that is worse than at the start of the shift. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Report the repeated vomiting and worsening headache"}, {"id": "b", "text": "Administer the ordered medications for nausea and pain"}, {"id": "c", "text": "Encourage forceful coughing to clear the throat"}, {"id": "d", "text": "Wait to report until the vomiting occurs twice more"}, {"id": "e", "text": "Monitor for dehydration and worsening ICP"}]'::jsonb, '["a", "b", "e"]', '(a) Correct: worsening headache and repeated vomiting are findings to report immediately. (b) Correct: administer ordered medications to manage headache, nausea, and vomiting. (e) Correct: monitor for dehydration and worsening ICP. (c) Wrong: brain tumor headache is often worse with coughing, and ICP-aggravating triggers should be reduced. (d) Wrong: repeated vomiting is already a finding to report immediately, so waiting delays care.', true),
  ('brain_tumors', 39, 'A 41-year-old client with a mass in the pituitary region reports that rings and shoes no longer fit because the hands and feet have enlarged. Which diagnostic test is MOST important for the nurse to anticipate to evaluate the cause of these physical changes?', '[{"id": "a", "text": "A CT scan to look for bleeding"}, {"id": "b", "text": "A neurologic exam to localize a lobe"}, {"id": "c", "text": "A biopsy to confirm the tumor grade"}, {"id": "d", "text": "Endocrine testing of hormone levels"}]'::jsonb, '["d"]', 'Abnormal tissue enlargement (acromegaly) comes from excess growth hormone, so endocrine testing of hormone levels is used when a pituitary tumor is suspected to check for excess or deficient hormone production. A biopsy confirms diagnosis and grade but does not evaluate hormone excess.', false),
  ('brain_tumors', 40, 'A client with a pituitary tumor has several findings, and the family asks which are caused by hormones rather than by pressure. Which findings should the nurse identify as hormone effects of the tumor? Select all that apply.', '[{"id": "a", "text": "Loss of outer vision in both eyes"}, {"id": "b", "text": "Galactorrhea"}, {"id": "c", "text": "Headache that is worse in the morning"}, {"id": "d", "text": "Cushing disease features from excess ACTH"}, {"id": "e", "text": "Swelling of the optic disc on eye exam"}]'::jsonb, '["b", "d"]', 'Pituitary tumors cause both mass effect and endocrine effects. (b) Correct: galactorrhea is a hormone effect. (d) Correct: Cushing disease features occur if ACTH is overproduced. (a) Wrong: bitemporal hemianopsia is a pressure/vision effect from the optic chiasm. (c) Wrong: headache is listed as a pressure effect. (e) Wrong: optic disc swelling is papilledema from increased ICP.', true),
  ('brain_tumors', 41, 'A client with a tumor near the ventricles has had increasing headache, vomiting, and new confusion over 24 hours. A CT scan shows the tumor is now obstructing CSF flow. Which explanation for the client''s worsening condition is MOST likely?', '[{"id": "a", "text": "A CSF leak through the nose"}, {"id": "b", "text": "Hydrocephalus further raising ICP"}, {"id": "c", "text": "Pituitary failure from low hormones"}, {"id": "d", "text": "Effects of the prescribed dexamethasone"}]'::jsonb, '["b"]', 'When a tumor blocks CSF flow, hydrocephalus (abnormal CSF buildup in the ventricles) may develop, further raising ICP and worsening headache, vomiting, and mental status changes. A CSF leak is an escape of fluid after craniotomy, not a blockage.', false),
  ('brain_tumors', 42, 'The nurse is assessing a client on postoperative day 3 after a craniotomy for tumor removal. Which findings require follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "Clear drainage leaking from the left ear"}, {"id": "b", "text": "Mild incisional pain relieved by the analgesic"}, {"id": "c", "text": "New seizure activity"}, {"id": "d", "text": "Excessive drowsiness after an opioid dose"}, {"id": "e", "text": "Asking about rehabilitation after discharge"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: clear drainage from the ear may be a CSF leak, which is reported promptly. (c) Correct: a new seizure must be reported immediately. (d) Correct: excessive drowsiness must be reported, and oversedation masks neuro changes. (b) Wrong: controlled pain without oversedation is the goal. (e) Wrong: rehabilitation may be needed after treatment, so the question is appropriate.', true),
  ('brain_tumors', 43, 'A client with a large brain metastasis from breast cancer is scheduled for a craniotomy. The client says, ''So this surgery will cure my cancer.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, removing a brain tumor cures the cancer that it came from."}, {"id": "b", "text": "The surgery is done to confirm the diagnosis, not to treat symptoms."}, {"id": "c", "text": "It may relieve pressure and symptoms; whether it cures depends on the tumor."}, {"id": "d", "text": "Surgery is not used for metastatic tumors, so radiation will replace it."}]'::jsonb, '["c"]', 'Craniotomy may remove or reduce the tumor, confirm diagnosis, relieve pressure, and improve symptoms, and it may be curative or palliative depending on the tumor. Surgery is not limited to diagnosis, and it can be used for metastatic tumors.', false),
  ('brain_tumors', 44, 'A client with a frontal lobe tumor becomes confused at night, repeatedly tries to climb out of bed, and seems unaware of new right-sided weakness. Which action by the nurse is BEST?', '[{"id": "a", "text": "Use wrist restraints to keep the client in bed"}, {"id": "b", "text": "Raise the bed to the highest position to deter climbing"}, {"id": "c", "text": "Give a sedative so the client sleeps all night"}, {"id": "d", "text": "Use calm reorientation and fall precautions"}]'::jsonb, '["d"]', 'Weakness and altered judgment increase fall risk, so the nurse uses fall precautions and calm reorientation if the client is confused. Sedation is tempting but masks neuro changes, which must be monitored closely in a client with a brain tumor.', false),
  ('brain_tumors', 45, 'A client with a glioma that cannot be safely removed asks the nurse about other treatment options. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Radiation is often used when surgery is not possible."}, {"id": "b", "text": "Radiosurgery is a type of traditional open surgery."}, {"id": "c", "text": "Surveillance is used for fast-growing tumors."}, {"id": "d", "text": "Chemotherapy drugs kill or slow cancer cell growth."}, {"id": "e", "text": "Chemotherapy is the first treatment for every tumor."}]'::jsonb, '["a", "d"]', '(a) Correct: radiation therapy is often used after surgery or when surgery is not possible. (d) Correct: chemotherapy uses drugs that kill or slow cancer cell growth. (b) Wrong: radiosurgery is highly focused radiation, not traditional open surgery. (c) Wrong: surveillance is for slow-growing or asymptomatic tumors. (e) Wrong: chemotherapy is used in selected tumors, and treatment depends on tumor type, grade, size, and location.', true),
  ('brain_tumors', 46, 'A client with a newly diagnosed brain tumor who has never had a seizure is started on an anticonvulsant before surgery. The client asks why. Which response by the nurse is BEST?', '[{"id": "a", "text": "In some cases it is given to prevent seizures before any occur."}, {"id": "b", "text": "It reduces the swelling of the brain tissue that surrounds the tumor."}, {"id": "c", "text": "It draws fluid out of the brain to lower pressure quickly."}, {"id": "d", "text": "It relieves headache without any effect on neuro status."}]'::jsonb, '["a"]', 'Anticonvulsants prevent or treat seizures and may be prophylactic in some cases, even before a seizure has occurred. Reducing cerebral edema describes dexamethasone, and drawing fluid out of swollen brain tissue describes mannitol.', false),
  ('brain_tumors', 47, 'A client with a brainstem tumor is being assessed at the start of the shift. Which finding should the nurse address FIRST?', '[{"id": "a", "text": "Headache rated 5 on a 0-10 scale"}, {"id": "b", "text": "Gurgling respirations with decreasing LOC"}, {"id": "c", "text": "Unsteady gait when walking to the bathroom"}, {"id": "d", "text": "Difficulty recognizing objects by touch"}]'::jsonb, '["b"]', 'Brainstem tumors affect breathing, swallowing, and consciousness, and if LOC decreases, airway protection becomes the immediate priority. Unsteady gait raises fall risk but is addressed after airway, breathing, and circulation.', false),
  ('brain_tumors', 48, 'A 52-year-old client reports several weeks of new symptoms. Which findings should prompt the nurse to suspect a brain tumor? Select all that apply.', '[{"id": "a", "text": "Headache that is worse in the morning and with coughing"}, {"id": "b", "text": "Headache that improves when bending over or straining"}, {"id": "c", "text": "A first-ever seizure at this age"}, {"id": "d", "text": "Seizures since early childhood that have been stable"}, {"id": "e", "text": "Focal neurologic deficits such as new weakness and numbness"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: brain tumor headache is often worse in the morning or with coughing, bending, or straining. (c) Correct: a new-onset seizure in an adult is a red flag for a brain tumor. (e) Correct: focal neurologic deficits such as weakness and numbness are brain tumor findings. (b) Wrong: bending and straining worsen, not improve, the headache. (d) Wrong: the red flag is a new seizure in an adult with no prior seizure history.', true),
  ('brain_tumors', 49, 'The wife of a client with a frontal lobe tumor says tearfully, ''He snaps at me and the kids now. He is not the same person anymore.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Try not to take it personally; his personality will return to normal after surgery."}, {"id": "b", "text": "Behavior changes mean the tumor has spread elsewhere, so you should prepare for the worst."}, {"id": "c", "text": "Personality changes can come from the tumor itself; tell me how you are coping."}, {"id": "d", "text": "I will ask the provider to increase his sedation so that he will be calmer with you."}]'::jsonb, '["c"]', 'Frontal lobe tumors cause personality changes, and brain tumors may alter behavior and cognition, so families need clear teaching and genuine emotional support. Promising a return to normal is false reassurance, and sedation masks neuro changes.', false),
  ('brain_tumors', 50, 'A client with an expanding glioma has a worsening headache, has vomited twice, and is now drowsy and slow to answer questions. The client also has mild leg weakness. Which nursing diagnosis is the PRIORITY?', '[{"id": "a", "text": "Acute pain"}, {"id": "b", "text": "Nausea"}, {"id": "c", "text": "Impaired physical mobility related to weakness"}, {"id": "d", "text": "Ineffective cerebral tissue perfusion"}]'::jsonb, '["d"]', 'Worsening headache, vomiting, and decreased LOC are signs of increased ICP, which lowers cerebral perfusion, so ineffective cerebral tissue perfusion takes priority. Acute pain and nausea are real but are symptoms of the underlying ICP problem.', false),
  ('encephalitis', 1, 'A 34-year-old client was admitted with 2 days of fever and headache. Today the spouse reports the client is disoriented to place and time, is seeing things that are not there, and had a seizure in the car. Nuchal rigidity is absent. Which condition does the nurse suspect is MOST likely developing?', '[{"id": "a", "text": "Meningitis involving only the protective meninges"}, {"id": "b", "text": "Status epilepticus from a single seizure"}, {"id": "c", "text": "A simple viral illness with headache"}, {"id": "d", "text": "Encephalitis involving the brain tissue"}]'::jsonb, '["d"]', 'Confusion, hallucinations, and seizures are brain dysfunction signs, which point to encephalitis (inflammation of the brain tissue). Meningitis is recognized by meningeal signs such as nuchal rigidity and photophobia, and a simple viral illness has no signs that the brain itself is involved.', false),
  ('encephalitis', 2, 'A 45-year-old client with fever, confusion, and lethargy has a lumbar puncture after a CT scan shows no mass effect. Which CSF findings would the nurse recognize as consistent with viral encephalitis? Select all that apply.', '[{"id": "a", "text": "Neutrophils predominate"}, {"id": "b", "text": "Increased lymphocytes"}, {"id": "c", "text": "Normal glucose level"}, {"id": "d", "text": "Mildly increased protein"}, {"id": "e", "text": "Markedly decreased glucose"}]'::jsonb, '["b", "c", "d"]', 'In viral encephalitis the CSF shows increased lymphocytes, mildly increased protein, and normal glucose, so those three findings fit. A markedly decreased glucose contradicts the normal glucose expected, and neutrophil predominance does not fit because the expected cell increase is in lymphocytes.', true),
  ('encephalitis', 3, 'A client with suspected encephalitis is scheduled for a lumbar puncture in 30 minutes. The nurse finds the client newly difficult to arouse, the client has vomited twice without nausea, and the right pupil is now sluggish. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Hold the LP and report signs of increased ICP"}, {"id": "b", "text": "Position the client side-lying with knees flexed for the LP"}, {"id": "c", "text": "Give acetaminophen to treat the fever before the LP"}, {"id": "d", "text": "Encourage oral fluids to replace losses from vomiting"}]'::jsonb, '["a"]', 'Decreasing LOC, vomiting without nausea, and pupil changes suggest increased ICP; a lumbar puncture with high ICP can cause fatal brain herniation, so CT or MRI must be done first. Positioning the client for the procedure is the right action only when increased ICP is not suspected.', false),
  ('encephalitis', 4, 'A client with fever, confusion, and new-onset seizures is suspected of having HSV encephalitis. The CSF HSV PCR result will not return for 24 hours, and the health care provider has prescribed IV acyclovir. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give acyclovir if another seizure occurs"}, {"id": "b", "text": "Begin the IV acyclovir now as prescribed"}, {"id": "c", "text": "Hold the acyclovir until the PCR confirms HSV"}, {"id": "d", "text": "Ask the provider to change to oral acyclovir"}]'::jsonb, '["b"]', 'IV acyclovir is started immediately when HSV encephalitis is suspected; the nurse does not wait for final confirmation because delayed treatment significantly worsens outcomes. Waiting for the PCR result is the classic trap.', false),
  ('encephalitis', 5, 'A nurse is setting up the room for a client admitted with suspected encephalitis who is febrile and lethargic. Which measures should the nurse include in the seizure precautions? Select all that apply.', '[{"id": "a", "text": "Bright overhead lighting for monitoring"}, {"id": "b", "text": "Suction equipment at bedside"}, {"id": "c", "text": "Soft wrist restraints ready for use"}, {"id": "d", "text": "Bed in highest position for observation"}, {"id": "e", "text": "Padded side rails"}]'::jsonb, '["b", "e"]', 'Padded side rails and suction equipment at the bedside are part of the seizure safety setup. Restraints are wrong because the client must NOT be restrained during a seizure; the bed belongs in the lowest position, not the highest; and bright lighting is wrong because a quiet, dim room reduces agitation and ICP elevation.', true),
  ('encephalitis', 6, 'Over 2 hours, a client with encephalitis has these trends: heart rate 92 to 50/min, BP 130/80 to 172/64 mm Hg, and respirations changing from regular to irregular with pauses. What is the nurse''s PRIORITY interpretation and action?', '[{"id": "a", "text": "Fever-related change; apply cooling measures"}, {"id": "b", "text": "Early ICP change; recheck vitals in 1 hour"}, {"id": "c", "text": "Late sign of high ICP; report immediately"}, {"id": "d", "text": "Post-seizure change; keep seizure precautions"}]'::jsonb, '["c"]', 'Bradycardia, a widened pulse pressure (172 - 64 = 108 mm Hg), and irregular respirations form Cushing''s triad, a late sign of severely elevated ICP that must be reported immediately because brain herniation may be imminent. Treating it as an early change to recheck later delays care.', false),
  ('encephalitis', 7, 'A client with fever, confusion, and seizures is admitted with suspected encephalitis; no contagious cause has been identified yet. The UAP asks whether droplet isolation is needed before entering. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, every client with encephalitis needs droplet isolation"}, {"id": "b", "text": "Yes, airborne isolation is needed until the PCR is negative"}, {"id": "c", "text": "No precautions are needed because the cause is likely autoimmune"}, {"id": "d", "text": "Standard precautions apply unless a contagious cause is found"}]'::jsonb, '["d"]', 'Precautions depend on the specific cause; standard precautions apply in most cases and additional precautions are only required if a contagious cause is identified. Assuming all encephalitis requires droplet isolation is a stated trap.', false),
  ('encephalitis', 8, 'A client with HSV encephalitis has become increasingly lethargic, responds only to a loud voice, and has secretions pooling in the mouth. The client is also due for IV acyclovir and has a fever. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Complete a full Glasgow Coma Scale"}, {"id": "b", "text": "Hang the scheduled IV acyclovir dose"}, {"id": "c", "text": "Assess the airway and gag reflex"}, {"id": "d", "text": "Give the prescribed acetaminophen"}]'::jsonb, '["c"]', 'A client with encephalitis and reduced LOC may lose airway protection, so airway is assessed first. Acyclovir must not be delayed, but ABCs come before rapid treatment in the priority order.', false),
  ('encephalitis', 9, 'A nurse is caring for a client on day 2 of treatment for encephalitis. Which new findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Repeated vomiting since the last check"}, {"id": "b", "text": "Weakness of the left arm and leg"}, {"id": "c", "text": "Unequal pupils with a sluggish reaction"}, {"id": "d", "text": "Sudden agitation and worsening confusion"}, {"id": "e", "text": "Ongoing malaise and fatigue"}]'::jsonb, '["a", "b", "c", "d"]', 'New pupillary changes, repeated vomiting, sudden agitation or worsening confusion, and unilateral weakness must be reported at once because they may indicate worsening edema or imminent brain herniation. Malaise and fatigue are early, general symptoms of the illness rather than signs of deterioration.', true),
  ('encephalitis', 10, 'A nurse is supervising a UAP caring for a client with encephalitis who is at risk for increased ICP. Which action by the UAP requires intervention by the nurse?', '[{"id": "a", "text": "Props the head forward on two pillows"}, {"id": "b", "text": "Uses a small roll to keep the head midline"}, {"id": "c", "text": "Keeps the head of bed at about 30 degrees"}, {"id": "d", "text": "Dims the lights and limits extra stimulation"}]'::jsonb, '["a"]', 'Neck flexion should be avoided because it increases venous congestion and ICP; propping the head forward flexes the neck. Elevating the head of bed about 30 degrees, keeping the head midline, and a quiet, dim room are all correct.', false),
  ('encephalitis', 11, 'Over 12 hours, a client with encephalitis has had a urine output well below intake and a weight gain, and the serum sodium has fallen below the normal range. Which complication does the nurse suspect is MOST likely?', '[{"id": "a", "text": "High metabolic demand from fever"}, {"id": "b", "text": "Dehydration from fever and vomiting"}, {"id": "c", "text": "SIADH causing water retention"}, {"id": "d", "text": "Osmotic diuresis from mannitol"}]'::jsonb, '["c"]', 'Brain conditions may trigger SIADH: too much ADH causes water retention and dilutional hyponatremia, matching low output, weight gain, and a falling sodium. Mannitol pulls fluid out of brain tissue and would not explain water retention.', false),
  ('encephalitis', 12, 'A nurse at a clinic reviews the histories of several clients. Which clients have a risk factor for encephalitis? Select all that apply.', '[{"id": "a", "text": "Immunocompromised from chemotherapy"}, {"id": "b", "text": "Adult with controlled hypertension"}, {"id": "c", "text": "9-month-old with a recent viral illness"}, {"id": "d", "text": "Adult with fully current vaccinations"}, {"id": "e", "text": "Hiker with frequent mosquito and tick exposure"}]'::jsonb, '["a", "c", "e"]', 'Infants under 1 year, a recent viral illness, immunocompromise from chemotherapy, and mosquito or tick exposure are listed risk factors. Current vaccinations protect, since lack of vaccination is the risk factor, and controlled hypertension is not a listed risk factor.', true),
  ('encephalitis', 13, 'A client recovering from encephalitis is more alert today but coughs and clears the throat each time the client sips water. The spouse has brought a favorite soup from home. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Hold oral intake and assess swallowing"}, {"id": "b", "text": "Request a large IV fluid bolus"}, {"id": "c", "text": "Help the client eat the soup slowly"}, {"id": "d", "text": "Allow the spouse to feed the client the soup"}]'::jsonb, '["a"]', 'The nurse assesses swallowing before any oral intake; impaired swallowing carries a high aspiration risk and the client may need NPO or enteral feeding. Feeding slowly still exposes the client to aspiration.', false),
  ('encephalitis', 14, 'A client with encephalitis is agitated, reports a severe headache, and squints at the overhead lights. Several family members want to visit together with the television on. Which nursing action is BEST?', '[{"id": "a", "text": "Keep a quiet, dim room and minimize stimulation"}, {"id": "b", "text": "Apply soft restraints to reduce agitation"}, {"id": "c", "text": "Cluster all care before the group visit"}, {"id": "d", "text": "Keep the TV on to help with frequent reorientation"}]'::jsonb, '["a"]', 'A quiet, dim room reduces headache, photophobia, agitation, and ICP elevation, so stimulation is minimized. Clustering many stimulating activities at once is to be avoided.', false),
  ('encephalitis', 15, 'A nurse is planning care for a client with encephalitis who has early signs of rising ICP. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Cluster bath, linen change, and neuro checks"}, {"id": "b", "text": "Avoid hip flexion if it worsens ICP"}, {"id": "c", "text": "Keep the head in a midline position"}, {"id": "d", "text": "Suction the airway hourly on a schedule"}, {"id": "e", "text": "Elevate the head of bed about 30 degrees"}]'::jsonb, '["b", "c", "e"]', 'Elevating the head of bed about 30 degrees, keeping the head midline, and avoiding hip flexion reduce venous congestion and help lower ICP. Suctioning is minimized unless necessary rather than done on a routine schedule, and clustering too many stimulating activities at once is avoided.', true),
  ('encephalitis', 16, 'A nurse receives report on four clients on a neurology unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Encephalitis client due for scheduled levetiracetam"}, {"id": "b", "text": "Encephalitis client with bradycardia and irregular respirations"}, {"id": "c", "text": "Simple viral illness client with fever, malaise, and mild headache"}, {"id": "d", "text": "Encephalitis client with photophobia resting in a dim room"}]'::jsonb, '["b"]', 'Bradycardia with irregular respirations is part of Cushing''s triad, a late and dangerous sign of severely elevated ICP that is reported at once. Fever, malaise, and mild headache without brain involvement fit a simple viral illness and are less urgent.', false),
  ('encephalitis', 17, 'A 19-year-old college student has had 3 days of fever, malaise, and headache. The roommate reports the student has become confused, has had unusual personality changes, and today has difficulty speaking. Which statement BEST explains the nurse''s concern?', '[{"id": "a", "text": "The findings show irritation of the meninges"}, {"id": "b", "text": "These are expected findings of a simple viral illness"}, {"id": "c", "text": "The findings show dehydration from poor intake"}, {"id": "d", "text": "The findings show the brain itself is involved"}]'::jsonb, '["d"]', 'Confusion, personality changes, and speech difficulty are signs that the brain itself is involved, which separates encephalitis from a simple viral illness of fever, malaise, and mild headache. Meningeal irritation is shown by neck stiffness and photophobia, not by personality change.', false),
  ('encephalitis', 18, 'A client with encephalitis has brief episodes of unresponsiveness with abnormal movements, and the team suspects these may be seizures. Which diagnostic test does the nurse anticipate as MOST useful to confirm this?', '[{"id": "a", "text": "MRI"}, {"id": "b", "text": "EEG"}, {"id": "c", "text": "CSF HSV PCR"}, {"id": "d", "text": "Blood tests"}]'::jsonb, '["b"]', 'An EEG records brain electrical activity and is useful when seizures are suspected. MRI is the preferred imaging for brain inflammation but does not record seizure activity.', false),
  ('encephalitis', 19, 'A client with encephalitis has a generalized seizure while in bed. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Restrain the arms to prevent injury"}, {"id": "b", "text": "Raise the bed to the highest position"}, {"id": "c", "text": "Have suction and oxygen ready"}, {"id": "d", "text": "Turn the client to the side if possible"}, {"id": "e", "text": "Keep the padded side rails up"}]'::jsonb, '["c", "d", "e"]', 'Turning the client to the side protects the airway, suction and oxygen should be available, and padded side rails protect from injury. The client must NOT be restrained during a seizure, and the bed should be in the lowest position.', true),
  ('encephalitis', 20, 'A client with fever, confusion, and focal weakness has a CT scan that shows no mass effect or severe swelling. The provider wants the imaging study that will BEST detect brain inflammation. Which test does the nurse anticipate?', '[{"id": "a", "text": "Viral serology"}, {"id": "b", "text": "EEG"}, {"id": "c", "text": "Repeat CT scan"}, {"id": "d", "text": "MRI"}]'::jsonb, '["d"]', 'MRI is more sensitive than CT for detecting brain inflammation and is the preferred imaging for encephalitis. CT is mainly used to rule out mass effect or severe swelling before an LP.', false),
  ('encephalitis', 21, 'The daughter of a client with suspected HSV encephalitis asks which test will confirm whether the herpes virus is the cause. Which response by the nurse is BEST?', '[{"id": "a", "text": "An EEG of the brain''s electrical activity"}, {"id": "b", "text": "An MRI showing brain inflammation"}, {"id": "c", "text": "An HSV PCR test on the spinal fluid"}, {"id": "d", "text": "A blood test for general inflammation"}]'::jsonb, '["c"]', 'HSV PCR in CSF detects viral genetic material and is the definitive test for HSV encephalitis. Blood tests show general signs of infection or inflammation and are not specific for encephalitis.', false),
  ('encephalitis', 22, 'A nurse provides discharge teaching to a client recovering from HSV encephalitis who had seizures during hospitalization. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "I will report worsening confusion or a fever."}, {"id": "b", "text": "I will report any seizure activity to my provider."}, {"id": "c", "text": "Rehabilitation may help my speech and memory."}, {"id": "d", "text": "I can stop the antiviral once my headache is gone."}, {"id": "e", "text": "I will drive to work next week since I feel fine."}]'::jsonb, '["d", "e"]', 'Stopping the antiviral early contradicts completing antiviral therapy as ordered, and driving is avoided after seizures until medically cleared, so both need further teaching. Reporting seizure activity, accepting rehabilitation for speech or cognition, and reporting worsening confusion or fever are all correct.', true),
  ('encephalitis', 23, 'The temperature of a client with encephalitis has climbed steadily over 2 hours, and the client is now restless. The spouse asks why the staff are treating the fever so quickly. Which response by the nurse is BEST?', '[{"id": "a", "text": "Fever is the definitive sign that HSV is causing the illness"}, {"id": "b", "text": "Fever lowers ICP but causes dehydration"}, {"id": "c", "text": "Fever raises metabolic demand and worsens brain injury"}, {"id": "d", "text": "Fever confirms that the client is contagious"}]'::jsonb, '["c"]', 'Fever increases metabolic demand and worsens neurologic injury, so antipyretics and cooling measures are given as ordered. HSV is confirmed by HSV PCR in CSF, not by fever.', false),
  ('encephalitis', 24, 'A client with encephalitis begins a generalized seizure, and the nurse turns the client to the side. Which situation should the nurse report IMMEDIATELY as status epilepticus?', '[{"id": "a", "text": "A single seizure followed by a headache"}, {"id": "b", "text": "A second seizure the next day after full recovery"}, {"id": "c", "text": "A 2-minute seizure, then drowsy but arousable"}, {"id": "d", "text": "Seizure activity lasting longer than 5 minutes"}]'::jsonb, '["d"]', 'Status epilepticus is a seizure lasting more than 5 minutes or repeated seizures without recovery, and it is a medical emergency. A second seizure after full recovery does not meet the ''without recovery'' criterion.', false),
  ('encephalitis', 25, 'A client with encephalitis is lethargic, has a weak gag reflex, and had a seizure overnight. Which actions should the nurse implement? Select all that apply.', '[{"id": "a", "text": "Offer thin liquids hourly to prevent dehydration"}, {"id": "b", "text": "Monitor respiratory rate and oxygen saturation"}, {"id": "c", "text": "Implement fall precautions"}, {"id": "d", "text": "Keep NPO until swallowing is assessed"}, {"id": "e", "text": "Assess gag reflex and swallowing ability"}]'::jsonb, '["b", "c", "d", "e"]', 'Monitoring respiratory rate and oxygen saturation and assessing the gag reflex and swallowing protect the airway; NPO is used when swallowing is impaired because of high aspiration risk; fall precautions address confusion and seizure risk. Offering oral liquids before swallowing is assessed risks aspiration.', true),
  ('encephalitis', 26, 'A 24-year-old client develops psychiatric changes, confusion, seizures, and abnormal movements. Viral studies are negative, and antibodies against NMDA receptors are found. Which treatment does the nurse anticipate as MOST likely?', '[{"id": "a", "text": "IV acyclovir as the main therapy"}, {"id": "b", "text": "IVIG, plasmapheresis, and corticosteroids"}, {"id": "c", "text": "Mannitol as the sole treatment"}, {"id": "d", "text": "Mosquito protection and recommended vaccinations"}]'::jsonb, '["b"]', 'Anti-NMDA receptor encephalitis is autoimmune; autoimmune treatment suppresses the harmful immune response with IVIG, plasmapheresis, corticosteroids, and immunosuppressives. Acyclovir targets a viral cause, especially HSV, which has not been found.', false),
  ('encephalitis', 27, 'A client with encephalitis has a worsening headache and decreasing LOC, and the provider prescribes mannitol. Which finding BEST indicates the medication is having the intended effect?', '[{"id": "a", "text": "CSF viral studies become negative over the week"}, {"id": "b", "text": "Headache eases and level of consciousness rises"}, {"id": "c", "text": "Seizure activity stops within minutes"}, {"id": "d", "text": "Temperature returns toward the normal range"}]'::jsonb, '["b"]', 'Mannitol is an osmotic diuretic that pulls fluid out of brain tissue to reduce edema and ICP, so improving LOC and less headache show effect. Lowering temperature is the purpose of antipyretics such as acetaminophen.', false),
  ('encephalitis', 28, 'A client with encephalitis receiving continuous IV fluids has an intake well above output, a worsening headache, and new lethargy. What is the nurse''s PRIORITY concern?', '[{"id": "a", "text": "A hypersensitivity reaction to acyclovir"}, {"id": "b", "text": "Dehydration reducing cerebral perfusion"}, {"id": "c", "text": "Fluid overload worsening cerebral edema"}, {"id": "d", "text": "Infiltration of the peripheral IV site"}]'::jsonb, '["c"]', 'IV fluids maintain hydration and cerebral perfusion, but fluid overload worsens cerebral edema; excess intake plus worsening headache and lethargy suggest rising ICP. Dehydration does not fit an intake well above output.', false),
  ('encephalitis', 29, 'A client with suspected HSV encephalitis has a fever, has had two seizures, and shows signs of rising ICP. Which prescriptions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Large IV fluid boluses to raise perfusion"}, {"id": "b", "text": "Levetiracetam for seizure control"}, {"id": "c", "text": "Acetaminophen for the fever"}, {"id": "d", "text": "Mannitol to reduce cerebral edema"}, {"id": "e", "text": "IV acyclovir started immediately"}]'::jsonb, '["b", "c", "d", "e"]', 'Acyclovir is started immediately for suspected HSV, levetiracetam is an anticonvulsant to prevent or control seizures, mannitol reduces edema and ICP, and acetaminophen reduces fever, which worsens brain injury. Large fluid boluses are wrong because fluid overload worsens cerebral edema.', true),
  ('encephalitis', 30, 'After a case of West Nile encephalitis is reported in the community, a parent asks the nurse how to protect the family. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Use mosquito protection when outdoors"}, {"id": "b", "text": "Take acyclovir before going outside"}, {"id": "c", "text": "Avoid contact with stray and wild animals"}, {"id": "d", "text": "Avoid people who have cold sores"}]'::jsonb, '["a"]', 'West Nile virus is a mosquito-borne arbovirus, so mosquito protection is the preventive measure. Avoiding infected animals prevents rabies, a different cause spread through animal bites.', false),
  ('encephalitis', 31, 'A client who was bitten by a stray animal several weeks ago now has fever, agitation, hallucinations, and confusion. Which viral cause of encephalitis should the nurse consider MOST likely?', '[{"id": "a", "text": "Varicella-zoster virus"}, {"id": "b", "text": "Rabies virus"}, {"id": "c", "text": "Epstein-Barr virus"}, {"id": "d", "text": "West Nile virus"}]'::jsonb, '["b"]', 'Rabies virus is spread through infected animal bites. West Nile virus is mosquito-borne, and varicella-zoster causes chickenpox and shingles.', false),
  ('encephalitis', 32, 'A nurse is developing a care plan for a client with encephalitis who is febrile, confused, had a seizure, and has a weak gag reflex. Which nursing diagnoses are appropriate? Select all that apply.', '[{"id": "a", "text": "Risk for injury"}, {"id": "b", "text": "Acute confusion"}, {"id": "c", "text": "Risk for aspiration"}, {"id": "d", "text": "Hyperthermia"}, {"id": "e", "text": "Imbalanced nutrition: more than requirements"}]'::jsonb, '["a", "b", "c", "d"]', 'Hyperthermia fits the fever, risk for injury fits seizures, acute confusion fits the disturbance in awareness, and risk for aspiration fits the weak gag reflex. Imbalanced nutrition more than requirements is not supported; the concern is impaired swallowing and aspiration.', true),
  ('encephalitis', 33, 'A 7-year-old recovered from a viral infection 2 weeks ago and now has confusion and seizures; no active virus is found in the CSF. The parent asks how this happened. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The meninges, not the brain tissue, are inflamed"}, {"id": "b", "text": "A mosquito bite has transmitted a new arbovirus"}, {"id": "c", "text": "The immune system became overactive and attacked the brain"}, {"id": "d", "text": "The original virus is still directly infecting the brain tissue"}]'::jsonb, '["c"]', 'Post-infectious encephalitis develops after an infection when the immune system becomes overactive and attacks brain tissue rather than the infection causing it directly. Confusion and seizures are brain dysfunction signs, not meningeal signs.', false),
  ('encephalitis', 34, 'A nurse performs neuro checks on a client with encephalitis. The GCS was 14 at 0800 and is 11 at 1000, and the client now opens the eyes only to voice. Which action is BEST?', '[{"id": "a", "text": "Let the client rest undisturbed in a dim room"}, {"id": "b", "text": "Document an expected fluctuation and recheck at 1200"}, {"id": "c", "text": "Give acetaminophen and reassess in 1 hour"}, {"id": "d", "text": "Report the decreasing GCS to the provider now"}]'::jsonb, '["d"]', 'A decreasing GCS is a bad sign; decreasing LOC is a red flag that may mean worsening cerebral edema or increasing ICP and is reported immediately. Rest in a dim room reduces stimulation but does not address deterioration.', false),
  ('encephalitis', 35, 'A nurse teaches a parent group about preventing encephalitis. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll use mosquito protection outdoors."}, {"id": "b", "text": "Encephalitis only affects people with HIV."}, {"id": "c", "text": "I''ll keep our recommended vaccinations up to date."}, {"id": "d", "text": "I''ll keep the children away from infected animals."}, {"id": "e", "text": "Mild confusion with fever can wait a few days."}]'::jsonb, '["a", "c", "d"]', 'Mosquito protection prevents arbovirus infection, recommended vaccinations prevent vaccine-preventable causes such as measles and mumps, and avoiding infected animals prevents rabies. Encephalitis can affect anyone, with infants and older adults also at risk, and severe neurologic symptoms need early treatment rather than waiting.', true),
  ('encephalitis', 36, 'A client has fever, headache, nuchal rigidity, and photophobia but is alert, fully oriented, and has no seizures or focal deficits. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Cushing''s triad from severe ICP"}, {"id": "b", "text": "A simple viral illness with no brain involvement"}, {"id": "c", "text": "Meningeal irritation, as in meningitis"}, {"id": "d", "text": "Brain dysfunction, as in encephalitis"}]'::jsonb, '["c"]', 'Headache, fever, neck stiffness, and photophobia show meningeal irritation, the pattern of meningitis. Encephalitis is identified by altered brain function signs such as confusion, seizures, and focal deficits, which are absent here.', false),
  ('encephalitis', 37, 'A client admitted with encephalitis has a patent airway, unlabored breathing, and stable circulation. Which nursing action should the nurse take NEXT?', '[{"id": "a", "text": "Begin range-of-motion exercises"}, {"id": "b", "text": "Arrange speech and cognition rehabilitation"}, {"id": "c", "text": "Teach mosquito prevention to the family"}, {"id": "d", "text": "Monitor LOC, pupils, and motor response"}]'::jsonb, '["d"]', 'After airway, breathing, and circulation, the next priority is neurologic status: LOC, pupils, motor response, and seizures are monitored continuously. Teaching and rehabilitation come later in recovery.', false),
  ('encephalitis', 38, 'A client recovering from encephalitis is confused, repeatedly tries to climb out of bed, and keeps asking where he is. Which action by the nurse is BEST?', '[{"id": "a", "text": "Reorient calmly and use fall precautions"}, {"id": "b", "text": "Firmly correct each mistaken belief he states"}, {"id": "c", "text": "Apply restraints and brighten the room"}, {"id": "d", "text": "Leave him alone to limit stimulation"}]'::jsonb, '["a"]', 'Confused or agitated clients need calm communication, reorientation, fall precautions, and family support. Bright lighting increases stimulation, which worsens agitation.', false),
  ('encephalitis', 39, 'A 28-year-old has had 3 days of fever and headache. Which additional findings would indicate the brain itself is involved and require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Fatigue"}, {"id": "b", "text": "A mild headache"}, {"id": "c", "text": "A seizure at home"}, {"id": "d", "text": "Malaise"}, {"id": "e", "text": "New lethargy"}]'::jsonb, '["c", "e"]', 'Lethargy and seizures show that the brain itself is involved, which signals encephalitis rather than a simple viral illness. Malaise, mild headache, and fatigue are general symptoms seen with a simple viral illness.', true),
  ('encephalitis', 40, 'The nurse is reviewing the plan of care for an intubated client with encephalitis and elevated ICP. Which planned action is MOST important for the nurse to change?', '[{"id": "a", "text": "Space out stimulating activities"}, {"id": "b", "text": "Keep the head in a midline position"}, {"id": "c", "text": "Keep the head of bed at about 30 degrees"}, {"id": "d", "text": "Suction the endotracheal tube hourly"}]'::jsonb, '["d"]', 'Suctioning should be minimized unless necessary because it can raise ICP, so routine hourly suctioning must be changed. Head of bed about 30 degrees, midline head position, and spacing stimulating activities all lower ICP.', false),
  ('encephalitis', 41, 'A client with encephalitis who had one seizure is started on levetiracetam and asks why it is needed now that the seizure is over. Which response by the nurse is BEST?', '[{"id": "a", "text": "It helps prevent or control seizures"}, {"id": "b", "text": "It treats the herpes virus directly"}, {"id": "c", "text": "It reduces cerebral edema and ICP"}, {"id": "d", "text": "It lowers the fever to protect the brain"}]'::jsonb, '["a"]', 'Levetiracetam is an anticonvulsant used to prevent or control seizures. Reducing edema and ICP is the purpose of mannitol, and treating HSV is the purpose of acyclovir.', false),
  ('encephalitis', 42, 'A nurse is monitoring a client with encephalitis for increased ICP. Which findings are listed as early and progressive signs rather than the late Cushing''s triad? Select all that apply.', '[{"id": "a", "text": "Widened pulse pressure"}, {"id": "b", "text": "Worsening headache"}, {"id": "c", "text": "Bradycardia"}, {"id": "d", "text": "Vomiting without nausea"}, {"id": "e", "text": "Irregular respirations"}]'::jsonb, '["b", "d"]', 'Worsening headache and vomiting, especially without nausea, are early and progressive signs of increased ICP. Bradycardia, widened pulse pressure, and irregular respirations make up Cushing''s triad, a late and dangerous sign.', true),
  ('encephalitis', 43, 'A client with a history of recurrent cold sores has fever, headache, confusion, and a new seizure. The airway is patent and breathing is unlabored. Which prescription should the nurse implement FIRST?', '[{"id": "a", "text": "Plasmapheresis to remove antibodies"}, {"id": "b", "text": "IV acyclovir without waiting for confirmation"}, {"id": "c", "text": "Oral acyclovir once the HSV PCR result returns"}, {"id": "d", "text": "Droplet isolation before any treatment"}]'::jsonb, '["b"]', 'HSV, the virus that commonly causes oral herpes, is suspected, and IV acyclovir must not be delayed while waiting for confirmation. Droplet isolation is not automatically required; standard precautions apply unless a contagious cause is identified.', false),
  ('encephalitis', 44, 'A client with encephalitis now has a worsening headache, vomiting, and decreasing LOC. The spouse asks what is happening. Which explanation reflects the MOST likely mechanism?', '[{"id": "a", "text": "Fever is causing dehydration and low blood pressure"}, {"id": "b", "text": "Brain swelling inside a rigid skull is raising ICP"}, {"id": "c", "text": "Inflamed meninges are causing stiffness of the neck"}, {"id": "d", "text": "Excess fluid loss is causing low sodium"}]'::jsonb, '["b"]', 'Inflammation causes cerebral edema; the brain swells inside a rigid, fixed skull, so ICP rises and perfusion falls, producing headache, vomiting, and decreasing LOC. Low sodium in brain conditions comes from water retention (SIADH), not fluid loss.', false),
  ('encephalitis', 45, 'The family of a client recovering from HSV encephalitis notices changes 2 weeks after discharge. Which changes should the nurse explain are possible long-term neurologic deficits? Select all that apply.', '[{"id": "a", "text": "Seizure disorder"}, {"id": "b", "text": "Memory loss"}, {"id": "c", "text": "Personality changes"}, {"id": "d", "text": "Nuchal rigidity"}, {"id": "e", "text": "Speech difficulties"}]'::jsonb, '["a", "b", "c", "e"]', 'Memory loss, speech difficulties, weakness, personality changes, and seizure disorder are long-term neurologic deficits of encephalitis. Nuchal rigidity is a sign of meningeal involvement during the acute illness, not a listed long-term deficit.', true),
  ('encephalitis', 46, 'A client with encephalitis has a second generalized seizure 3 minutes after the first one ended and has not regained awareness in between. What is the nurse''s PRIORITY interpretation?', '[{"id": "a", "text": "Status epilepticus requiring emergency care"}, {"id": "b", "text": "Postictal drowsiness expected after seizures"}, {"id": "c", "text": "Two isolated seizures, each under 5 minutes"}, {"id": "d", "text": "A normal response to the anticonvulsant"}]'::jsonb, '["a"]', 'Repeated seizures without recovery meet the definition of status epilepticus even though each seizure was shorter than 5 minutes, and it is a medical emergency. Treating these as separate seizures to document misses the lack of recovery between them.', false),
  ('encephalitis', 47, 'A client with encephalitis has a decreasing LOC and gurgling respirations, and secretions are pooling in the mouth. Which nursing diagnosis is the PRIORITY?', '[{"id": "a", "text": "Acute confusion"}, {"id": "b", "text": "Impaired physical mobility"}, {"id": "c", "text": "Ineffective airway clearance"}, {"id": "d", "text": "Hyperthermia"}]'::jsonb, '["c"]', 'Ineffective airway clearance is the inability to maintain a clear airway; airway protection is nursing priority #1. Hyperthermia and confusion are real problems but follow ABCs.', false),
  ('encephalitis', 48, 'A nurse reviews the medication orders for four clients with encephalitis. For which client is the nurse MOST likely to see corticosteroids prescribed?', '[{"id": "a", "text": "Client with mosquito exposure and malaise"}, {"id": "b", "text": "Client with anti-NMDA receptor encephalitis"}, {"id": "c", "text": "Client with a simple viral illness"}, {"id": "d", "text": "Client who has completed IV acyclovir therapy"}]'::jsonb, '["b"]', 'Corticosteroids reduce cerebral inflammation and are used in autoimmune encephalitis, such as anti-NMDA receptor encephalitis, or in severe cases. A simple viral illness has no brain involvement.', false),
  ('encephalitis', 49, 'A client with encephalitis is being assessed for meningeal involvement. Which findings would suggest the meninges are also inflamed? Select all that apply.', '[{"id": "a", "text": "Hallucinations"}, {"id": "b", "text": "Photophobia"}, {"id": "c", "text": "Weakness on one side"}, {"id": "d", "text": "Personality changes"}, {"id": "e", "text": "Neck stiffness"}]'::jsonb, '["b", "e"]', 'Neck stiffness and photophobia are meningeal irritation signs; meningoencephalitis may show features of both conditions. Hallucinations, one-sided weakness, and personality changes are brain dysfunction signs of encephalitis itself.', true),
  ('encephalitis', 50, 'A client with encephalitis has been unresponsive for 5 days and cannot move independently. Which nursing action is MOST appropriate to prevent pressure injuries and loss of joint mobility?', '[{"id": "a", "text": "Turn regularly and perform range-of-motion exercises"}, {"id": "b", "text": "Restrain the extremities to prevent falls from bed"}, {"id": "c", "text": "Limit repositioning to once each shift to rest the client"}, {"id": "d", "text": "Keep the client flat and still to avoid raising ICP"}]'::jsonb, '["a"]', 'An immobile client is turned regularly, the skin is protected, and range-of-motion exercises are performed to prevent pressure injuries. Keeping the client still is not the stated ICP measure; ICP care uses head of bed about 30 degrees and a midline head position.', false),
  ('hydrocephalus', 1, 'A 4-month-old is brought to the clinic because of poor feeding and irritability. The nurse finds the head circumference has increased rapidly since the last visit, the fontanel is bulging, and the eyes deviate downward with the whites visible above the iris. Which condition does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Dehydration from poor feeding and vomiting"}, {"id": "b", "text": "Hydrocephalus with increased ICP"}, {"id": "c", "text": "Normal-pressure hydrocephalus in infancy"}, {"id": "d", "text": "Expected head growth for the infant''s age"}]'::jsonb, '["b"]', 'Rapidly increasing head circumference, a bulging fontanel, and sun-setting eyes are the classic infant findings of hydrocephalus, and a bulging fontanel is a direct sign of elevated ICP. Normal-pressure hydrocephalus occurs mainly in older adults.', false),
  ('hydrocephalus', 2, 'A nurse is teaching the parents of a 5-month-old who has a VP shunt. Which findings should the parents report to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Bulging fontanel"}, {"id": "b", "text": "Poor feeding"}, {"id": "c", "text": "Sun-setting eyes"}, {"id": "d", "text": "Shuffling gait with incontinence"}, {"id": "e", "text": "Increasing head size"}]'::jsonb, '["a", "b", "c", "e"]', 'Parents of an infant watch for a bulging fontanel, poor feeding, increasing head size, and sun-setting eyes, which can signal a return of hydrocephalus. A shuffling gait with urinary incontinence belongs to the normal-pressure hydrocephalus triad of older adults, not a 5-month-old.', true),
  ('hydrocephalus', 3, 'The mother of a 3-month-old with hydrocephalus asks why her baby''s head is getting bigger when her adult brother with hydrocephalus had headaches and vomiting instead. Which response by the nurse is BEST?', '[{"id": "a", "text": "Infants produce more CSF than adults in the choroid plexus"}, {"id": "b", "text": "Adults develop only the communicating type of hydrocephalus"}, {"id": "c", "text": "Infant skull sutures are not fully fused, so the head expands"}, {"id": "d", "text": "Infants with hydrocephalus do not develop increased ICP at all"}]'::jsonb, '["c"]', 'Infants show different signs because skull sutures are not yet fully fused, so the head can still expand; in older patients the rigid skull makes pressure symptoms dominate. Infants do develop increased ICP, shown by a bulging fontanel.', false),
  ('hydrocephalus', 4, 'A 2-month-old is admitted with suspected hydrocephalus and is awaiting imaging. The infant is feeding fairly well and sleeping between feedings. Which nursing action is MOST important to include in the plan of care?', '[{"id": "a", "text": "Measure and document head circumference serially"}, {"id": "b", "text": "Check fontanel tension once on admission for a baseline"}, {"id": "c", "text": "Offer larger feedings to promote faster weight gain"}, {"id": "d", "text": "Assess gait and balance with each set of vital signs"}]'::jsonb, '["a"]', 'Serial head circumference measurement is a critical pediatric nursing action because increasing circumference is a major clue to worsening hydrocephalus. Fontanel tension is assessed at each assessment, not only once, and gait assessment applies to older patients.', false),
  ('hydrocephalus', 5, 'A nurse is monitoring an adult client who has a VP shunt. Which findings would support a shunt infection? Select all that apply.', '[{"id": "a", "text": "Fever"}, {"id": "b", "text": "Slow, shuffling gait"}, {"id": "c", "text": "Worsening neurologic status"}, {"id": "d", "text": "Redness along the shunt tract"}, {"id": "e", "text": "Sun-setting eyes"}]'::jsonb, '["a", "c", "d"]', 'Shunt infection presents with fever, redness or swelling along the shunt tract, and worsening neurologic status. Sun-setting eyes are an infant sign of hydrocephalus, and a slow, shuffling gait is the gait disturbance of normal-pressure hydrocephalus.', true),
  ('hydrocephalus', 6, 'A 7-year-old with a VP shunt placed in infancy has had a headache and vomiting since this morning and is now drowsy and hard to keep awake. The child has no fever, and there is no redness along the shunt tract. What is the nurse''s PRIORITY interpretation and action?', '[{"id": "a", "text": "Possible shunt infection; obtain a culture first"}, {"id": "b", "text": "Probable stomach virus; encourage oral fluids"}, {"id": "c", "text": "Growth-related headache; give an analgesic"}, {"id": "d", "text": "Possible shunt malfunction; report immediately"}]'::jsonb, '["d"]', 'Return of ICP symptoms (headache, vomiting, decreased LOC) in a child with a shunt means shunt malfunction or infection until proven otherwise and must be reported immediately. Without fever or redness along the tract, malfunction is more likely than infection, and either way reporting comes first.', false),
  ('hydrocephalus', 7, 'A 3-year-old had a VP shunt revision 10 days ago. Today the child has a fever, and the nurse notes redness and swelling along the shunt tract behind the ear and down the neck. Which complication does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Expected post-op healing"}, {"id": "b", "text": "Shunt overdrainage"}, {"id": "c", "text": "Shunt infection"}, {"id": "d", "text": "Normal-pressure hydrocephalus"}]'::jsonb, '["c"]', 'Fever with redness or swelling along the shunt tract points to shunt infection, a major safety concern that can lead to meningitis. Overdrainage is a different shunt complication that does not explain fever and redness.', false),
  ('hydrocephalus', 8, 'The daughter of a 74-year-old reports that over several months her father has developed a slow, shuffling walk, has begun losing bladder control, and has become forgetful. Which condition does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Acute VP shunt malfunction with high ICP"}, {"id": "b", "text": "Noncommunicating hydrocephalus in infancy"}, {"id": "c", "text": "Normal-pressure hydrocephalus"}, {"id": "d", "text": "Dementia that cannot improve with treatment"}]'::jsonb, '["c"]', 'Gait change, urinary incontinence, and cognitive decline in an older adult form the NPH triad (wet, wobbly, wacky). The cognitive impairment of NPH may resemble dementia but can improve with treatment.', false),
  ('hydrocephalus', 9, 'A nurse reviews imaging plans for several clients being evaluated for hydrocephalus. Which plans are appropriate? Select all that apply.', '[{"id": "a", "text": "MRI as the test of choice for a 55-year-old adult"}, {"id": "b", "text": "Cranial ultrasound for a 2-month-old with open fontanels"}, {"id": "c", "text": "CT avoided in urgent cases because it is too slow"}, {"id": "d", "text": "Cranial ultrasound for an adult with a closed skull"}, {"id": "e", "text": "CT chosen for infants because it uses no radiation"}]'::jsonb, '["a", "b"]', 'Cranial ultrasound images the brain through the open fontanel of an infant, and MRI is the test of choice for evaluating adult hydrocephalus. Ultrasound needs an open fontanel, CT is useful in urgent situations because it is fast, and it is ultrasound, not CT, that uses no radiation.', true),
  ('hydrocephalus', 10, 'A nurse is screening older adults at a senior center for normal-pressure hydrocephalus. Which client finding would be MOST consistent with the earliest sign of this condition?', '[{"id": "a", "text": "New slow, shuffling gait"}, {"id": "b", "text": "Bradycardia with irregular breathing"}, {"id": "c", "text": "Headache with vomiting"}, {"id": "d", "text": "Fever with redness behind the ear"}]'::jsonb, '["a"]', 'Gait disturbance is often the earliest and most prominent symptom of NPH, with a slow, shuffling gait. Bradycardia with irregular respirations is part of Cushing''s triad, a late sign of severe ICP elevation.', false),
  ('hydrocephalus', 11, 'An older adult client with gait problems, incontinence, and memory changes has enlarged ventricles, but measured CSF pressure is in the usual range. The family asks whether this rules out hydrocephalus. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes; hydrocephalus is diagnosed only when CSF pressure is high"}, {"id": "b", "text": "No; a normal reading means the problem is a blocked VP shunt"}, {"id": "c", "text": "No; in NPH the pressure may be normal while ventricles enlarge"}, {"id": "d", "text": "Yes; a normal pressure reading rules out any form of hydrocephalus"}]'::jsonb, '["c"]', 'In normal-pressure hydrocephalus, measured CSF pressure may be in the usual range while the ventricles are enlarged and symptoms are present. A normal reading therefore does not exclude NPH.', false),
  ('hydrocephalus', 12, 'A 15-year-old with a VP shunt calls the clinic. Which reports from the teen or parent require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Mild muscle soreness after soccer"}, {"id": "b", "text": "Vomiting and nausea today"}, {"id": "c", "text": "Decline in school performance noted by a teacher"}, {"id": "d", "text": "A new headache that keeps worsening"}, {"id": "e", "text": "Blurry vision since yesterday"}]'::jsonb, '["b", "c", "d", "e"]', 'New or worsening headache, vomiting, visual changes, and a decline in school performance or cognition are all reported to the provider immediately because they can signal shunt malfunction. Muscle soreness after exercise is not a listed warning sign.', true),
  ('hydrocephalus', 13, 'A client with normal-pressure hydrocephalus is scheduled for treatment. The son says, ''Dad''s memory problems are just dementia, so nothing will help that part.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Only the gait problems are expected to improve with treatment"}, {"id": "b", "text": "The cognitive changes may resemble dementia but can improve"}, {"id": "c", "text": "Memory changes in NPH are permanent once they have started"}, {"id": "d", "text": "Treatment is aimed at the bladder control problems alone"}]'::jsonb, '["b"]', 'In NPH the cognitive impairment may resemble dementia but can improve with treatment. Assuming the memory changes are permanent dementia is the trap.', false),
  ('hydrocephalus', 14, 'An MRI shows a tumor blocking CSF flow within the ventricular system of a 48-year-old client, with the ventricles enlarged upstream of the blockage. Which type of hydrocephalus does the nurse recognize as MOST likely?', '[{"id": "a", "text": "Communicating"}, {"id": "b", "text": "Noncommunicating"}, {"id": "c", "text": "Normal-pressure"}, {"id": "d", "text": "Congenital"}]'::jsonb, '["b"]', 'Noncommunicating (obstructive) hydrocephalus results from a blockage within the ventricular system, so fluid builds up behind the blockage and enlarges the upstream ventricles. In communicating hydrocephalus CSF still flows through the ventricles but is not absorbed.', false),
  ('hydrocephalus', 15, 'A 35-year-old developed hydrocephalus after a traumatic brain injury. Which findings would the nurse expect in this client? Select all that apply.', '[{"id": "a", "text": "Rapid head enlargement"}, {"id": "b", "text": "Blurry vision"}, {"id": "c", "text": "Nausea and vomiting"}, {"id": "d", "text": "Drowsiness"}, {"id": "e", "text": "Headache"}]'::jsonb, '["b", "c", "d", "e"]', 'In older children and adults the skull is rigid, so pressure symptoms dominate: headache, nausea and vomiting, blurry vision or visual changes, and drowsiness or decreased alertness. Rapid head enlargement occurs in infants, whose skull can expand.', true),
  ('hydrocephalus', 16, 'A 30-year-old developed hydrocephalus after meningitis scarred the CSF pathways. Imaging shows CSF moves through the ventricles, but it is not reabsorbed after it exits. Which type of hydrocephalus is MOST likely?', '[{"id": "a", "text": "Congenital"}, {"id": "b", "text": "Communicating"}, {"id": "c", "text": "Noncommunicating"}, {"id": "d", "text": "Normal-pressure"}]'::jsonb, '["b"]', 'In communicating hydrocephalus CSF can still flow through the ventricles, but absorption is impaired after it exits; the problem is reabsorption, not internal blockage. Noncommunicating hydrocephalus involves a blockage within the ventricular system.', false),
  ('hydrocephalus', 17, 'A client with obstructive hydrocephalus is told the surgeon will create an opening in the floor of the third ventricle instead of placing a shunt. The client asks how this will help. Which response by the nurse is BEST?', '[{"id": "a", "text": "The skull will be able to expand"}, {"id": "b", "text": "CSF can bypass the obstruction"}, {"id": "c", "text": "CSF will drain to the abdomen"}, {"id": "d", "text": "CSF production will decrease"}]'::jsonb, '["b"]', 'Endoscopic third ventriculostomy creates an opening in the floor of the third ventricle so CSF can bypass an obstruction, an alternative to shunting in selected cases. Draining CSF to the abdomen describes a VP shunt.', false),
  ('hydrocephalus', 18, 'The parents of a 6-week-old with a rapidly enlarging head ask why the baby is having an ultrasound of the head instead of a CT scan. Which response by the nurse is BEST?', '[{"id": "a", "text": "It images the brain through the open fontanel with no radiation"}, {"id": "b", "text": "It measures the CSF pressure directly inside the ventricles"}, {"id": "c", "text": "It is the only test that can show the ventricles are enlarged"}, {"id": "d", "text": "It is the imaging test of choice for adults with hydrocephalus"}]'::jsonb, '["a"]', 'Cranial ultrasound images the brain through the open fontanel using sound waves; it is quick and uses no radiation. MRI, not ultrasound, is the test of choice for adult hydrocephalus.', false),
  ('hydrocephalus', 19, 'A nurse assesses a 2-month-old with congenital hydrocephalus. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Sunken fontanel"}, {"id": "b", "text": "Unusually large head"}, {"id": "c", "text": "Narrow, small head size"}, {"id": "d", "text": "Sun-setting eyes"}, {"id": "e", "text": "Shuffling gait"}]'::jsonb, '["b", "d"]', 'An unusually large head and sun-setting eyes are classic infant findings. The fontanel bulges rather than sinks when ICP is elevated, a shuffling gait belongs to NPH in older adults, and bradycardia is part of the late Cushing''s triad rather than an expected finding.', true),
  ('hydrocephalus', 20, 'A 9-month-old with a VP shunt is being evaluated for abdominal complications. The parent asks how a brain shunt could affect the belly. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It drains CSF from the ventricles into the peritoneal cavity"}, {"id": "b", "text": "It drains CSF from the spinal canal into the bladder wall"}, {"id": "c", "text": "It drains CSF from the ventricles into the third ventricle"}, {"id": "d", "text": "It opens the skull sutures so CSF moves into the abdomen"}]'::jsonb, '["a"]', 'A VP shunt uses tubing and a valve to drain CSF from the brain''s ventricles into the peritoneal cavity (abdomen), which is why abdominal complications can occur. An opening in the third ventricle describes endoscopic third ventriculostomy.', false),
  ('hydrocephalus', 21, 'A nurse on a pediatric neurology unit receives report on four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Adult with a VP shunt who asks about resuming work next month"}, {"id": "b", "text": "6-month-old awaiting ultrasound with a stable head circumference"}, {"id": "c", "text": "Older adult with NPH whose shuffling gait is unchanged today"}, {"id": "d", "text": "8-month-old with a VP shunt, lethargic, with a bulging fontanel"}]'::jsonb, '["d"]', 'Lethargy and a bulging fontanel in an infant with a shunt signal shunt malfunction with rising ICP, which is reported immediately. A stable head circumference and an unchanged NPH gait are not new deterioration.', false),
  ('hydrocephalus', 22, 'The parents of a child scheduled for VP shunt placement ask about possible complications. Which complications should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Abdominal complications"}, {"id": "b", "text": "Underdrainage"}, {"id": "c", "text": "End to developmental follow-up"}, {"id": "d", "text": "Overdrainage"}, {"id": "e", "text": "Shunt infection"}]'::jsonb, '["a", "b", "d", "e"]', 'Overdrainage, underdrainage, abdominal complications of a VP shunt, and shunt infection are listed shunt complications. A shunt does not end the need for follow-up; children may need long-term developmental follow-up.', true),
  ('hydrocephalus', 23, 'A nurse measures the head circumference of a 3-month-old with hydrocephalus each morning: 40.0 cm on day 1, 40.5 cm on day 2, and 41.5 cm on day 3. The fontanel now feels tense. Which action is BEST?', '[{"id": "a", "text": "Plan a cranial ultrasound at the next well visit"}, {"id": "b", "text": "Document the trend and remeasure again tomorrow"}, {"id": "c", "text": "Report the rising head size and tense fontanel"}, {"id": "d", "text": "Increase feedings to support normal head growth"}]'::jsonb, '["c"]', 'Head circumference increased 1.5 cm in 2 days with a growing daily gain, and rapidly increasing head circumference is a major pediatric red flag; with a tense fontanel it suggests worsening hydrocephalus. Simply documenting and remeasuring delays action.', false),
  ('hydrocephalus', 24, 'A new nurse is caring for a 4-month-old with hydrocephalus. Which action by the new nurse is MOST important for the preceptor to correct?', '[{"id": "a", "text": "Monitors feeding tolerance and episodes of vomiting"}, {"id": "b", "text": "Assesses the infant for irritability and lethargy"}, {"id": "c", "text": "Measures and documents head circumference each day"}, {"id": "d", "text": "Checks fontanel tension only at the start of shift"}]'::jsonb, '["d"]', 'Fontanel tension is assessed at each assessment, not just once a shift, because a bulging fontanel is a direct sign of increased ICP. Serial head circumference, feeding tolerance, and irritability versus lethargy are all correct pediatric assessments.', false),
  ('hydrocephalus', 25, 'A nurse teaches the parents of a 4-year-old with a VP shunt. Which statements by the parents indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "We''ll call right away about any seizure."}, {"id": "b", "text": "We''ll report redness along the shunt path."}, {"id": "c", "text": "If she is unusually sleepy, we''ll let her nap."}, {"id": "d", "text": "Vomiting with a headache is probably a stomach bug."}, {"id": "e", "text": "If she has a fever, we''ll wait a few days."}]'::jsonb, '["c", "d", "e"]', 'Fever, vomiting with headache, and unusual sleepiness must be reported immediately because they can signal shunt infection or malfunction, so these three statements need further teaching. Reporting seizures and redness along the shunt path are correct.', true),
  ('hydrocephalus', 26, 'An infant with hydrocephalus who was irritable this morning is now difficult to wake and is feeding poorly. The parent says, ''At least he''s finally calm.'' Which interpretation by the nurse is BEST?', '[{"id": "a", "text": "Calm sleep shows the ICP improved"}, {"id": "b", "text": "Lethargy may signal worsening ICP"}, {"id": "c", "text": "Sleepiness is expected after feeds"}, {"id": "d", "text": "Poor feeding is from overfeeding"}]'::jsonb, '["b"]', 'Irritability and lethargy are both infant signs of hydrocephalus and shunt malfunction; progression to lethargy with poor feeding suggests worsening, not improvement. Mistaking lethargy for calm is the trap.', false),
  ('hydrocephalus', 27, 'A 10-year-old with a VP shunt reports a headache and is becoming more drowsy. Over 1 hour the heart rate falls from 96 to 54/min, BP rises from 108/70 to 150/60 mm Hg, and respirations become irregular. What should the nurse do FIRST?', '[{"id": "a", "text": "Give acetaminophen for the headache"}, {"id": "b", "text": "Recheck the vital signs in 30 minutes"}, {"id": "c", "text": "Report immediately as impending herniation"}, {"id": "d", "text": "Encourage oral fluids and reassess"}]'::jsonb, '["c"]', 'Bradycardia, a widened pulse pressure (150 - 60 = 90 mm Hg), and irregular respirations are Cushing''s triad, a late emergency sign meaning impending brain herniation, so the nurse reports immediately. Rechecking later delays emergency care.', false),
  ('hydrocephalus', 28, 'A 3-week-old who had an intraventricular hemorrhage shortly after birth now has a rapidly enlarging head and is diagnosed with hydrocephalus. How should the nurse BEST classify this hydrocephalus?', '[{"id": "a", "text": "Communicating, because bleeding blocks the ventricles"}, {"id": "b", "text": "Congenital, because the client is a newborn"}, {"id": "c", "text": "Normal-pressure, because the skull can expand"}, {"id": "d", "text": "Acquired, developing after birth from bleeding"}]'::jsonb, '["d"]', 'Acquired hydrocephalus develops after birth from head injury, bleeding, infection, tumors, or stroke and can occur at any age; congenital hydrocephalus is present at birth. A blockage within the ventricles describes noncommunicating, not communicating, hydrocephalus.', false),
  ('hydrocephalus', 29, 'A 78-year-old is evaluated for normal-pressure hydrocephalus. Which findings fit the classic triad? Select all that apply.', '[{"id": "a", "text": "Gait disturbance"}, {"id": "b", "text": "Cognitive impairment"}, {"id": "c", "text": "Urinary incontinence"}, {"id": "d", "text": "Irregular respirations"}, {"id": "e", "text": "Bulging fontanel"}]'::jsonb, '["a", "b", "c"]', 'The NPH triad is wet (urinary incontinence), wobbly (gait disturbance), and wacky (cognitive impairment). A bulging fontanel is an infant sign, and irregular respirations are part of Cushing''s triad of severe ICP.', true),
  ('hydrocephalus', 30, 'A 52-year-old with a known brain tumor reports headaches, vomiting, and blurry vision, and MRI shows enlarged ventricles. Which mechanism does the nurse recognize as MOST likely?', '[{"id": "a", "text": "Open sutures letting the skull expand"}, {"id": "b", "text": "Normal pressure with enlarged ventricles"}, {"id": "c", "text": "Too much CSF being produced"}, {"id": "d", "text": "Tumor blocking CSF flow"}]'::jsonb, '["d"]', 'In adults, tumors blocking CSF flow are a cause of hydrocephalus, and blockage is one of the most important mechanisms. Overproduction of CSF is possible but less important, and open sutures apply only to infants.', false),
  ('hydrocephalus', 31, 'An infant with hydrocephalus vomits after most feedings and has lost weight since admission. Which nursing diagnosis is MOST directly supported by these findings?', '[{"id": "a", "text": "Imbalanced nutrition: less than requirements"}, {"id": "b", "text": "Risk for infection related to the shunt tubing"}, {"id": "c", "text": "Delayed growth and development of motor skills"}, {"id": "d", "text": "Acute pain related to a worsening headache"}]'::jsonb, '["a"]', 'Imbalanced nutrition: less than body requirements describes not taking in enough nutrients due to vomiting or feeding difficulties, matching vomiting and weight loss. Delayed growth and development refers to slower physical or developmental progress, which these data do not show.', false),
  ('hydrocephalus', 32, 'A nurse plans care for an adult client with hydrocephalus and a new VP shunt. Which interventions should be included? Select all that apply.', '[{"id": "a", "text": "Seizure precautions when indicated"}, {"id": "b", "text": "Restrict fluids to reduce CSF production"}, {"id": "c", "text": "Monitor for return of headache and vomiting"}, {"id": "d", "text": "Frequent neuro checks of pupils and speech"}, {"id": "e", "text": "Serial head circumference measurements"}]'::jsonb, '["a", "c", "d"]', 'Monitoring for return of headache, vomiting, and decreased LOC (shunt malfunction), seizure precautions when indicated, and frequent neuro checks of LOC, pupils, speech, and motor are listed for all patients. Serial head circumference is a pediatric action because an adult''s rigid skull cannot expand, and nutrition and hydration are supported rather than restricted.', true),
  ('hydrocephalus', 33, 'The parents of a 2-year-old with a well-functioning VP shunt ask whether they need anything beyond routine shunt checks. Which response by the nurse is BEST?', '[{"id": "a", "text": "Head circumference checks alone are enough at this point"}, {"id": "b", "text": "Therapy services are started once the child reaches school age"}, {"id": "c", "text": "Developmental follow-up and supportive therapies may be needed"}, {"id": "d", "text": "A working shunt means development will follow the usual pattern"}]'::jsonb, '["c"]', 'Children may need long-term developmental follow-up and supportive therapies because hydrocephalus can interfere with brain growth. A working shunt does not remove the risk of developmental delay.', false),
  ('hydrocephalus', 34, 'An adult with a VP shunt has a fever, redness along the shunt tract, and new confusion. The client asks why the provider is so concerned. Which response by the nurse is BEST?', '[{"id": "a", "text": "Shunt infection can lead to meningitis"}, {"id": "b", "text": "These are the signs of normal-pressure type"}, {"id": "c", "text": "The shunt is overdraining the ventricles"}, {"id": "d", "text": "This is an expected reaction to the tubing"}]'::jsonb, '["a"]', 'Fever, redness along the shunt tract, and worsening neurologic status indicate shunt infection, a major safety concern that can lead to meningitis. Overdrainage is a different shunt complication without fever and redness.', false),
  ('hydrocephalus', 35, 'The father of a newborn with hydrocephalus asks how the condition develops. Which mechanisms should the nurse explain are the MOST important? Select all that apply.', '[{"id": "a", "text": "CSF is made outside the ventricles"}, {"id": "b", "text": "The abdomen absorbs too much CSF"}, {"id": "c", "text": "CSF absorption is impaired"}, {"id": "d", "text": "CSF flow is blocked"}, {"id": "e", "text": "Skull sutures fuse too early"}]'::jsonb, '["c", "d"]', 'Blocked CSF flow and impaired CSF absorption are the most important mechanisms. Unfused sutures are why an infant''s head can expand, absorption into the abdomen describes how a VP shunt works, and CSF is produced mainly in the choroid plexus inside the ventricles.', true),
  ('hydrocephalus', 36, 'A nurse receives report on a newly admitted 8-year-old with hydrocephalus and a VP shunt who is alert and stable. Which nursing action is the PRIORITY for this child?', '[{"id": "a", "text": "Plan supportive nutrition and hydration"}, {"id": "b", "text": "Assess the child''s developmental progress"}, {"id": "c", "text": "Frequent neuro checks of LOC, pupils, and motor"}, {"id": "d", "text": "Teach the family how the shunt valve works"}]'::jsonb, '["c"]', 'Nursing priority #1 is frequent neuro checks with monitoring for ICP signs and shunt malfunction or infection. Family teaching, developmental assessment, and nutrition matter but come after neurologic monitoring.', false),
  ('hydrocephalus', 37, 'A 12-year-old with no shunt has 2 weeks of worsening headaches, vomiting, blurred vision, and new balance problems; head circumference is normal. The parent asks why the child''s head is not getting bigger. Which response by the nurse is BEST?', '[{"id": "a", "text": "Older children do not develop hydrocephalus"}, {"id": "b", "text": "The ventricles cannot enlarge after infancy"}, {"id": "c", "text": "CSF is absorbed faster in school-age children"}, {"id": "d", "text": "The skull is rigid, so pressure symptoms dominate"}]'::jsonb, '["d"]', 'In older patients the skull is rigid and cannot expand, so pressure symptoms dominate instead of head enlargement. Hydrocephalus can occur at any age, and the ventricles still enlarge.', false),
  ('hydrocephalus', 38, 'A 66-year-old client is being evaluated for hydrocephalus because of gait problems and memory changes. The provider wants the study that best defines ventricular size and identifies the cause. Which test does the nurse anticipate?', '[{"id": "a", "text": "MRI"}, {"id": "b", "text": "Lumbar puncture"}, {"id": "c", "text": "Cranial ultrasound"}, {"id": "d", "text": "CT scan"}]'::jsonb, '["a"]', 'MRI best defines ventricular enlargement, identifies the cause, and is the imaging of choice for adults. CT is useful mainly in urgent situations, and cranial ultrasound requires an open fontanel.', false),
  ('hydrocephalus', 39, 'A 9-month-old with hydrocephalus vomits after most feeds, is losing weight, and shows slower than expected developmental progress. Which nursing diagnoses are appropriate? Select all that apply.', '[{"id": "a", "text": "Impaired urinary elimination"}, {"id": "b", "text": "Acute confusion related to fever"}, {"id": "c", "text": "Imbalanced nutrition: more than requirements"}, {"id": "d", "text": "Delayed growth and development"}, {"id": "e", "text": "Imbalanced nutrition: less than requirements"}]'::jsonb, '["d", "e"]', 'Vomiting with weight loss supports imbalanced nutrition: less than body requirements, and slower than expected developmental progress supports delayed growth and development. Nutrition more than requirements contradicts weight loss, and acute confusion and urinary elimination are not supported by these data.', true),
  ('hydrocephalus', 40, 'A 6-year-old returns to the unit after VP shunt placement. Which nursing diagnosis is MOST directly related to the new device and postoperative care?', '[{"id": "a", "text": "Imbalanced nutrition"}, {"id": "b", "text": "Acute confusion"}, {"id": "c", "text": "Delayed growth"}, {"id": "d", "text": "Risk for infection"}]'::jsonb, '["d"]', 'Risk for infection applies especially with shunts or postoperative care, and shunt infection is a major safety concern. Imbalanced nutrition relates to vomiting or feeding difficulties, which are not described.', false),
  ('hydrocephalus', 41, 'Two adults have enlarged ventricles. One developed symptoms slowly over years with normal measured pressure; the other developed headache, vomiting, and drowsiness within hours after a brain hemorrhage. Which explanation BEST accounts for the difference?', '[{"id": "a", "text": "Rapid buildup cannot be accommodated by the rigid skull"}, {"id": "b", "text": "Only the slow case involves enlarged ventricles"}, {"id": "c", "text": "Slow buildup raises ICP more because the skull stiffens over time"}, {"id": "d", "text": "Hemorrhage reduces CSF production, causing pressure"}]'::jsonb, '["a"]', 'ICP rises especially when buildup is rapid because the rigid skull cannot accommodate the extra volume. In NPH, ventricles enlarge while measured pressure may stay in the usual range.', false),
  ('hydrocephalus', 42, 'A 16-year-old with obstructive hydrocephalus has BP 168/62 mm Hg, heart rate 48/min, respirations 16/min and regular, and a normal temperature. Which findings in this client are components of Cushing''s triad? Select all that apply.', '[{"id": "a", "text": "Pulse pressure of 106 mm Hg"}, {"id": "b", "text": "Narrowed pulse pressure"}, {"id": "c", "text": "Normal body temperature"}, {"id": "d", "text": "Heart rate of 48/min"}, {"id": "e", "text": "Regular respirations of 16/min"}]'::jsonb, '["a", "d"]', 'A heart rate of 48 is bradycardia and a pulse pressure of 168 - 62 = 106 mm Hg is widened; both are Cushing''s triad components. The third component is irregular respirations, so regular respirations do not fit, temperature is not part of the triad, and the systolic BP is not below the diastolic.', true),
  ('hydrocephalus', 43, 'The parent of a 6-year-old with a VP shunt describes the warning signs to watch for at home. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "I''ll report visual changes to the provider immediately."}, {"id": "b", "text": "Vomiting is expected for a while after a shunt."}, {"id": "c", "text": "Extra sleepiness after school shows the shunt works."}, {"id": "d", "text": "The shunt cured him, so no more follow-up is needed."}]'::jsonb, '["a"]', 'Visual changes must be reported to the provider immediately because they can signal shunt malfunction. Vomiting and unusual sleepiness are also warning signs, not expected effects.', false),
  ('hydrocephalus', 44, 'A nurse receives report on four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Infant with hydrocephalus whose head circumference is unchanged"}, {"id": "b", "text": "Adult with a VP shunt and new headache, vomiting, and lower LOC"}, {"id": "c", "text": "Child with a VP shunt asking when he can return to school soon"}, {"id": "d", "text": "Older adult with NPH reporting ongoing urinary incontinence today"}]'::jsonb, '["b"]', 'Return of ICP symptoms (headache, vomiting, decreased LOC) in a client with a shunt means malfunction or infection until proven otherwise and must be reported immediately. Ongoing incontinence in NPH is a chronic finding, not acute deterioration.', false),
  ('hydrocephalus', 45, 'A nurse reviews the histories of adults newly diagnosed with hydrocephalus. Which histories are recognized causes in older children and adults? Select all that apply.', '[{"id": "a", "text": "Traumatic brain injury"}, {"id": "b", "text": "Long-standing gait disturbance"}, {"id": "c", "text": "Years of urinary incontinence"}, {"id": "d", "text": "Stroke"}, {"id": "e", "text": "Recent brain hemorrhage"}]'::jsonb, '["a", "d", "e"]', 'Brain hemorrhage, traumatic brain injury, and stroke are listed causes of hydrocephalus in older children and adults. Urinary incontinence and gait disturbance are symptoms of normal-pressure hydrocephalus, not causes.', true),
  ('hydrocephalus', 46, 'A newborn is found at birth to have hydrocephalus caused by a problem in fetal brain development. The parents ask how this differs from their nephew''s hydrocephalus that followed a head injury. Which classification by the nurse is BEST?', '[{"id": "a", "text": "Communicating, from a blockage"}, {"id": "b", "text": "Normal-pressure, of older adults"}, {"id": "c", "text": "Acquired, developed after birth"}, {"id": "d", "text": "Congenital, present at birth"}]'::jsonb, '["d"]', 'Congenital hydrocephalus is present at birth and may result from genetic causes or fetal brain development problems, whereas the nephew''s injury-related hydrocephalus is acquired. Communicating hydrocephalus involves impaired absorption, not blockage.', false),
  ('hydrocephalus', 47, 'During assessment of a calm 4-month-old with hydrocephalus, the nurse finds a bulging fontanel. The parent asks what this means. Which interpretation by the nurse is BEST?', '[{"id": "a", "text": "An expected finding when an infant''s head is growing"}, {"id": "b", "text": "A visible sign of increased pressure in the brain"}, {"id": "c", "text": "A sign of normal-pressure hydrocephalus in infancy"}, {"id": "d", "text": "A sign the CSF is being absorbed into the abdomen"}]'::jsonb, '["b"]', 'The fontanel bulges when ICP is elevated; this is a direct, visible sign of increased intracranial pressure in an infant. Normal-pressure hydrocephalus occurs mainly in older adults.', false),
  ('hydrocephalus', 48, 'An adult client with obstructive hydrocephalus asks what the shunt surgery is supposed to accomplish. Which response by the nurse is BEST?', '[{"id": "a", "text": "Increase CSF pressure so the ventricles shrink again"}, {"id": "b", "text": "Divert or drain excess CSF to protect brain tissue"}, {"id": "c", "text": "Allow the skull bones to expand around the ventricles"}, {"id": "d", "text": "Stop the choroid plexus from producing any more CSF"}]'::jsonb, '["b"]', 'The main goal of treatment is to divert or drain excess CSF to reduce ventricular pressure and protect brain tissue. CSF is produced mainly in the choroid plexus, and the VP shunt does not stop production.', false),
  ('hydrocephalus', 49, 'A nurse is caring for a 10-month-old with hydrocephalus. Which pediatric-specific assessments should the nurse perform? Select all that apply.', '[{"id": "a", "text": "Assess fontanel tension"}, {"id": "b", "text": "Monitor feeding tolerance and vomiting"}, {"id": "c", "text": "Assess bladder control problems"}, {"id": "d", "text": "Assess developmental progress"}, {"id": "e", "text": "Assess for a shuffling gait"}]'::jsonb, '["a", "b", "d"]', 'Assessing developmental progress, monitoring feeding tolerance and vomiting, and assessing fontanel tension at each assessment are pediatric-specific priorities. Shuffling gait and bladder control problems are symptoms assessed in older children and adults, especially NPH.', true),
  ('hydrocephalus', 50, 'A 3-year-old who had a VP shunt placed in infancy is behind peers in speech and motor skills on developmental assessment. The shunt is functioning. Which complication does the nurse recognize as MOST likely?', '[{"id": "a", "text": "Normal-pressure type"}, {"id": "b", "text": "Overdrainage"}, {"id": "c", "text": "Developmental delay"}, {"id": "d", "text": "Shunt infection"}]'::jsonb, '["c"]', 'Developmental delay is a neurologic complication because hydrocephalus can interfere with brain growth, even with a functioning shunt. Shunt infection would show fever, redness along the tract, and worsening neuro status.', false),
  ('scleroderma', 1, 'A client with diffuse cutaneous systemic sclerosis whose baseline blood pressure is 118/76 mm Hg reports a new headache and blurred vision. Blood pressure is now 196/112 mm Hg, and urine output has dropped sharply since morning. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Notify the provider immediately and anticipate an ACE inhibitor"}, {"id": "b", "text": "Hold all antihypertensives until the creatinine result is available"}, {"id": "c", "text": "Warm the room and apply gloves to reduce the vasospasm causing the headache"}, {"id": "d", "text": "Recheck the blood pressure in 1 hour to confirm the trend before calling"}]'::jsonb, '["a"]', 'Sudden severe hypertension with new headache/vision changes and oliguria are red flags for scleroderma renal crisis; the action is to notify the provider immediately and anticipate an ACE inhibitor. Waiting an hour to recheck delays BP/renal management, and an ACE inhibitor is used even if creatinine rises.', false),
  ('scleroderma', 2, 'A client admitted with scleroderma renal crisis started captopril yesterday. Today the blood pressure has improved from 204/118 to 166/98 mm Hg, but the creatinine rose from 2.1 to 2.4 mg/dL. The spouse asks whether the drug is harming the kidneys. Which response by the nurse is BEST?', '[{"id": "a", "text": "The captopril will likely be stopped now because the creatinine is rising"}, {"id": "b", "text": "A high-dose steroid will be added to protect the kidneys from more injury"}, {"id": "c", "text": "A calcium channel blocker will replace captopril to protect the kidneys"}, {"id": "d", "text": "The ACE inhibitor is used even if creatinine rises initially"}]'::jsonb, '["d"]', 'In scleroderma renal crisis the ACE inhibitor (often captopril) is used even if creatinine rises initially because it improves outcomes. Stopping it for the early creatinine rise is the tempting but wrong choice, and high-dose steroids can increase SRC risk.', false),
  ('scleroderma', 3, 'A client with diffuse cutaneous systemic sclerosis tests positive for anti–RNA polymerase III antibodies. During a clinic visit, which findings should the nurse report to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Pruritus with hyperpigmented patches"}, {"id": "b", "text": "Sudden severe rise in blood pressure"}, {"id": "c", "text": "New headache with vision changes"}, {"id": "d", "text": "Oliguria with a rising creatinine"}, {"id": "e", "text": "Early satiety and nausea after meals"}]'::jsonb, '["b", "c", "d"]', 'Anti–RNA polymerase III is linked to diffuse disease with renal crisis risk. A new headache/vision change, oliguria with rising creatinine, and a sudden severe rise in BP are SRC red flags that need immediate provider notification. Pruritus with pigment change is an expected skin finding, and early satiety with nausea reflects gastroparesis; neither signals renal crisis.', true),
  ('scleroderma', 4, 'A client with systemic sclerosis has worsening skin and joint inflammation. The provider writes a new prescription for high-dose prednisone. The client''s blood pressure is 124/78 mm Hg. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give the dose because the blood pressure is currently in normal range"}, {"id": "b", "text": "Clarify the order, since high-dose steroids can increase SRC risk"}, {"id": "c", "text": "Give the dose and recheck the skin thickness at the next visit"}, {"id": "d", "text": "Give the dose with food so it does not worsen the client''s reflux"}]'::jsonb, '["b"]', 'High-dose steroids should be avoided in systemic sclerosis because they can increase scleroderma renal crisis risk, so the nurse clarifies the order. A normal BP today does not remove that risk; methotrexate is the note''s agent for skin/joint inflammation.', false),
  ('scleroderma', 5, 'A client diagnosed with diffuse cutaneous systemic sclerosis 1 year ago reports a dry cough and breathlessness when climbing stairs. The nurse hears new fine inspiratory crackles at both bases, and SpO2 has fallen from 97% to 92% since the last visit. These findings are MOST consistent with which complication?', '[{"id": "a", "text": "Aspiration from esophageal dysmotility and reflux"}, {"id": "b", "text": "Interstitial lung disease progression"}, {"id": "c", "text": "Pulmonary arterial hypertension with right heart strain"}, {"id": "d", "text": "Pericarditis from cardiac involvement"}]'::jsonb, '["b"]', 'Worsening dyspnea with a falling SpO2 and new fine inspiratory (Velcro) crackles points to ILD progression, which diffuse disease carries a higher early risk of. PAH presents with exertional syncope, loud P2 and edema rather than new crackles.', false),
  ('scleroderma', 6, 'A client with limited cutaneous systemic sclerosis reports that the fingers turn white, then blue, then red after leaving an air-conditioned store or during stressful meetings. Which instructions should the nurse include in the teaching plan? Select all that apply.', '[{"id": "a", "text": "Stop smoking to prevent nicotine vasoconstriction"}, {"id": "b", "text": "Keep the home environment warm"}, {"id": "c", "text": "Use strategies to manage stress"}, {"id": "d", "text": "Wear gloves and layered clothing in cool places"}, {"id": "e", "text": "Use a decongestant for nasal stuffiness in winter"}]'::jsonb, '["a", "b", "c", "d"]', 'These are Raynaud episodes, triggered by cold or stress. Gloves and layered clothing and a warm environment prevent vasospasm, smoking cessation stops nicotine vasoconstriction, and stress management addresses the second trigger. Decongestants are vasoconstrictors that the client should avoid.', true),
  ('scleroderma', 7, 'A client who has had CREST syndrome for 14 years reports fainting while walking uphill, progressive breathlessness, and fatigue. The nurse auscultates a loud P2 and notes bilateral ankle edema. Which diagnostic test is MOST appropriate to evaluate these findings?', '[{"id": "a", "text": "HRCT chest for detailed lung imaging of interstitial fibrosis"}, {"id": "b", "text": "Creatinine, BUN, and UA with BP monitoring to watch for SRC"}, {"id": "c", "text": "Barium swallow and manometry to assess esophageal motility"}, {"id": "d", "text": "Echocardiogram to screen for PAH and right heart strain"}]'::jsonb, '["d"]', 'Exertional syncope, loud P2 and edema indicate PAH/right heart failure, a later risk in limited (CREST) disease, and an echocardiogram screens for PAH/right heart strain. HRCT is the detailed imaging for ILD, which presents with crackles rather than syncope and a loud P2.', false),
  ('scleroderma', 8, 'A nurse teaches a client with systemic sclerosis who has frequent heartburn and food that sticks when swallowing. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will eat small, frequent meals instead of three big ones."}, {"id": "b", "text": "I will raise the head of my bed and avoid my trigger foods."}, {"id": "c", "text": "I can have late meals as long as they are small meals."}, {"id": "d", "text": "I will stay upright for a while after I finish each meal."}]'::jsonb, '["c"]', 'GERD prevention includes elevating the HOB, small meals, avoiding triggers and no late meals, so planning late meals, even small ones, needs correction. Small frequent meals and staying upright after meals are correct.', false),
  ('scleroderma', 9, 'A client with ANA and anti-centromere antibodies positive and anti–Scl-70 negative has tight skin on the fingers, red pinpoint lesions on the face, and firm calcium nodules on the fingertips. Which additional findings are expected findings for this client''s disease pattern? Select all that apply.', '[{"id": "a", "text": "Raynaud phenomenon triggered by cold"}, {"id": "b", "text": "Skin thickening of the hands and forearms"}, {"id": "c", "text": "Dysphagia from esophageal dysmotility"}, {"id": "d", "text": "Tendon friction rub over the wrist tendons"}, {"id": "e", "text": "Skin thickening of the trunk and thighs"}]'::jsonb, '["a", "b", "c"]', 'Anti-centromere marks the limited/CREST pattern: distal skin (fingers/hands/forearms), Raynaud triggered by cold or stress, and esophageal dysmotility with swallowing/reflux problems. A tendon friction rub suggests diffuse disease, and proximal skin of the trunk/thighs is the diffuse cutaneous distribution.', true),
  ('scleroderma', 10, 'The nurse receives report on four clients with scleroderma. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Morphea with a new thickened skin plaque and a mild headache"}, {"id": "b", "text": "Esophageal dysmotility with heartburn after eating a late dinner"}, {"id": "c", "text": "Diffuse disease with new headache and BP up to 188/110"}, {"id": "d", "text": "CREST pattern with new red pinpoint lesions and BP 138/86"}]'::jsonb, '["c"]', 'Sudden severe hypertension with headache suggests scleroderma renal crisis, so BP/renal management is the priority. A BP of 138/86 is not a sudden severe rise, morphea is usually skin-only and not life-threatening, and new telangiectasias or reflux after a late meal are not emergencies.', false),
  ('scleroderma', 11, 'A client with systemic sclerosis has an ischemic fingertip ulcer. Today the finger is red and swollen with purulent drainage, and the temperature is 38.6°C (101.5°F). Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the redness, drainage, and fever to the provider"}, {"id": "b", "text": "Document it as the red reperfusion phase of Raynaud"}, {"id": "c", "text": "Apply cold compresses to reduce the redness and swelling"}, {"id": "d", "text": "Moisturize the fingertip and continue daily ROM exercises"}]'::jsonb, '["a"]', 'Redness, drainage and fever are infection signs the nurse reports, because digital ulcers can progress to cellulitis or osteomyelitis. The red Raynaud phase is reperfusion after vasospasm and does not cause drainage or fever, and cold exposure triggers vasospasm.', false),
  ('scleroderma', 12, 'A client with systemic sclerosis has dysphagia, a chronic cough, and has been treated for pneumonia twice this year. The client has lost 4 kg (8.8 lb) in 3 months. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Offer one large meal late in the evening"}, {"id": "b", "text": "Offer small bites with upright positioning"}, {"id": "c", "text": "Monitor weight for ongoing loss"}, {"id": "d", "text": "Elevate the HOB after meals"}, {"id": "e", "text": "Swallow eval as ordered"}]'::jsonb, '["b", "c", "d", "e"]', 'Esophageal dysmotility/GERD can cause chronic cough and recurrent pneumonias from aspiration. Dysphagia precautions include a swallow evaluation, small bites and upright positioning; elevating the HOB prevents reflux; and weight loss is part of the GI safety assessment. Late, large meals contradict GERD prevention (small meals, no late meals).', true),
  ('scleroderma', 13, 'The parent of a 9-year-old with a line-like thickened band of skin running down the left leg asks what the nurse will be watching for over time. Which response by the nurse is BEST?', '[{"id": "a", "text": "The band can limit growth and movement of the affected leg"}, {"id": "b", "text": "The band raises the risk of sudden severe high blood pressure"}, {"id": "c", "text": "The band usually appears in older adults, so it should fade"}, {"id": "d", "text": "The band is a sign that the lungs will scar within a few years"}]'::jsonb, '["a"]', 'Linear scleroderma is a line-like thickened band that can limit growth/movement in the affected limb and is more common in children. It is a localized type, so renal crisis and lung fibrosis risks belong to systemic sclerosis.', false),
  ('scleroderma', 14, 'A client has a single plaque of thickened skin on the abdomen. There is no Raynaud phenomenon, BP is 118/74 mm Hg, and there are no swallowing or breathing symptoms. The client asks, "Is this going to damage my organs like my aunt''s scleroderma?" Which response is MOST accurate?', '[{"id": "a", "text": "This type carries a higher risk of early lung disease"}, {"id": "b", "text": "This type carries a higher risk of scleroderma renal crisis"}, {"id": "c", "text": "This type is classically associated with CREST syndrome"}, {"id": "d", "text": "This type is usually skin-only and not life-threatening"}]'::jsonb, '["d"]', 'Localized plaques of thickened skin describe morphea, which is usually skin-only and not life-threatening. Renal crisis and early ILD are higher-risk features of diffuse systemic sclerosis, and CREST is associated with the limited cutaneous form.', false),
  ('scleroderma', 15, 'A client newly diagnosed with systemic sclerosis has skin thickening of the upper arms, thighs, and trunk, and is positive for anti–Scl-70 antibodies. For which complications should the nurse monitor this client closely? Select all that apply.', '[{"id": "a", "text": "Calcinosis as part of CREST syndrome"}, {"id": "b", "text": "Scleroderma renal crisis"}, {"id": "c", "text": "A linear band limiting limb growth"}, {"id": "d", "text": "Morphea plaques limited to the skin"}, {"id": "e", "text": "Early aggressive interstitial lung disease"}]'::jsonb, '["b", "e"]', 'Proximal skin (upper arms/thighs/trunk) is diffuse cutaneous disease, which carries a higher risk of early aggressive ILD and scleroderma renal crisis; anti–Scl-70 adds ILD risk. CREST belongs to the limited pattern, while morphea plaques and a linear band that limits limb growth are localized scleroderma, not systemic sclerosis.', true),
  ('scleroderma', 16, 'A client with CREST syndrome has painful episodes in which the fingers turn white and then blue in cold weather. Nifedipine is prescribed. Which statement by the client indicates understanding of the purpose of this medication?', '[{"id": "a", "text": "It protects my kidneys if my blood pressure rises suddenly."}, {"id": "b", "text": "It is a vasodilator that eases vasospasm in my fingers."}, {"id": "c", "text": "It lowers stomach acid so food will not stick when I swallow."}, {"id": "d", "text": "It is a DMARD that will soften the tight skin on my fingers."}]'::jsonb, '["b"]', 'Nifedipine is a calcium channel blocker used as a vasodilator for Raynaud/digital ischemia. Methotrexate is the DMARD for skin/joint inflammation, PPIs treat reflux, and an ACE inhibitor is used for renal crisis.', false),
  ('scleroderma', 17, 'A client with systemic sclerosis and recurrent digital ulcers says, "I switched from cigarettes to nicotine gum, so my fingers should be fine now." Which response by the nurse is BEST?', '[{"id": "a", "text": "The gum is safe for your fingers once nifedipine has been started."}, {"id": "b", "text": "The gum still contains nicotine, which narrows the blood vessels."}, {"id": "c", "text": "That is a good change, because the gum does not affect blood flow."}, {"id": "d", "text": "The gum is safe for your fingers as long as you also wear gloves."}]'::jsonb, '["b"]', 'Clients should avoid vasoconstrictors, including any nicotine; smoking cessation is critical because it stops nicotine vasoconstriction. Gloves and nifedipine help Raynaud but do not offset continued nicotine exposure.', false),
  ('scleroderma', 18, 'A client has had limited cutaneous systemic sclerosis with CREST features for 12 years. The nurse is screening for the cardiopulmonary complication this disease pattern carries a higher risk of later in its course. Which findings would indicate this complication? Select all that apply.', '[{"id": "a", "text": "Chronic cough after meals"}, {"id": "b", "text": "Velcro crackles at both bases"}, {"id": "c", "text": "Loud P2 on auscultation"}, {"id": "d", "text": "New peripheral edema"}, {"id": "e", "text": "Syncope with exertion"}]'::jsonb, '["c", "d", "e"]', 'Limited (CREST) disease carries a higher risk of PAH later; exertional syncope, a loud P2 and edema indicate PAH/right heart failure. Velcro (fine inspiratory) crackles indicate ILD, and chronic cough linked to meals suggests aspiration from esophageal dysmotility/GERD.', true),
  ('scleroderma', 19, 'While assessing a client recently diagnosed with systemic sclerosis, the nurse places a hand over the client''s wrist and feels a grating sensation over the tendons as the fingers flex and extend. The nurse recognizes this finding MOST likely suggests which pattern?', '[{"id": "a", "text": "Diffuse cutaneous disease"}, {"id": "b", "text": "Limited disease with CREST"}, {"id": "c", "text": "Localized morphea plaque"}, {"id": "d", "text": "Rheumatoid arthritis erosions"}]'::jsonb, '["a"]', 'A tendon friction rub, a grating sensation over tendons, suggests diffuse disease. CREST is the limited cutaneous pattern, and rheumatoid arthritis is characterized by symmetric joint swelling and erosions.', false),
  ('scleroderma', 20, 'A client with systemic sclerosis and severe reflux has a chronic cough and has been admitted for a second pneumonia in 6 months. Lung fields were clear between episodes, and SpO2 at the last visit was 98%. Which factor does the nurse recognize as the MOST likely cause of the recurrent pneumonias?', '[{"id": "a", "text": "Interstitial lung disease from lung fibrosis"}, {"id": "b", "text": "Pulmonary arterial hypertension with heart strain"}, {"id": "c", "text": "Aspiration from esophageal dysmotility and GERD"}, {"id": "d", "text": "Pericarditis from cardiac fibrosis"}]'::jsonb, '["c"]', 'Esophageal dysmotility and GERD raise aspiration risk, which shows up as chronic cough and recurrent pneumonias. ILD presents with progressive exertional dyspnea, Velcro crackles and falling SpO2 rather than clear lungs between episodes.', false),
  ('scleroderma', 21, 'A client with systemic sclerosis has severe Raynaud phenomenon with two ischemic fingertip ulcers. Which medications would the nurse anticipate being prescribed for the digital ischemia? Select all that apply.', '[{"id": "a", "text": "An oral decongestant"}, {"id": "b", "text": "A prostacyclin analog"}, {"id": "c", "text": "Sildenafil, a PDE-5 inhibitor"}, {"id": "d", "text": "Methotrexate, a DMARD"}, {"id": "e", "text": "Nifedipine, a calcium channel blocker"}]'::jsonb, '["b", "c", "e"]', 'For Raynaud/digital ischemia the note lists CCBs such as nifedipine and PDE-5 inhibitors such as sildenafil as vasodilators, and prostacyclin analogs as strong vasodilators/platelet inhibitors for severe cases. Decongestants are vasoconstrictors to avoid, and methotrexate is for skin/joint inflammation.', true),
  ('scleroderma', 22, 'A client with systemic sclerosis reports feeling full after a few bites and being nauseated after most meals. The client denies heartburn and says food does not stick when swallowing. These symptoms are MOST consistent with which GI problem?', '[{"id": "a", "text": "Gastroparesis"}, {"id": "b", "text": "Small intestinal bacterial overgrowth"}, {"id": "c", "text": "Esophageal dysmotility"}, {"id": "d", "text": "Gastroesophageal reflux"}]'::jsonb, '["a"]', 'Gastroparesis causes early satiety and nausea. Esophageal dysmotility causes dysphagia, GERD causes heartburn, and SIBO leads to malabsorption.', false),
  ('scleroderma', 23, 'A client with long-standing systemic sclerosis has unintended weight loss and frequent diarrhea despite eating regular meals without early fullness. Labs suggest poor nutrient absorption. Which GI process does the nurse recognize as the MOST likely cause?', '[{"id": "a", "text": "SIBO causing malabsorption"}, {"id": "b", "text": "Reflux causing heartburn"}, {"id": "c", "text": "Esophageal dysmotility causing dysphagia"}, {"id": "d", "text": "Gastroparesis causing early satiety"}]'::jsonb, '["a"]', 'SIBO (small intestinal bacterial overgrowth) leads to malabsorption, which fits weight loss with diarrhea and poor absorption. Gastroparesis would cause early satiety and nausea, which this client does not have.', false),
  ('scleroderma', 24, 'A client with systemic sclerosis has severe reflux and weak esophageal peristalsis. Which medications would the nurse expect to be prescribed to treat this GERD/esophageal problem? Select all that apply.', '[{"id": "a", "text": "PPIs for reflux"}, {"id": "b", "text": "Prokinetics"}, {"id": "c", "text": "H2 blockers"}, {"id": "d", "text": "An endothelin receptor antagonist"}, {"id": "e", "text": "Cyclophosphamide"}]'::jsonb, '["a", "b", "c"]', 'PPIs, H2 blockers and prokinetics are the GERD/esophageal treatments. Endothelin receptor antagonists treat PAH, and cyclophosphamide is reserved for severe ILD.', true),
  ('scleroderma', 25, 'A client with systemic sclerosis reports that solid food feels stuck midway down the chest and that heartburn has worsened. The provider wants to determine whether weak peristalsis is the cause. Which test should the nurse anticipate as MOST useful?', '[{"id": "a", "text": "HRCT chest"}, {"id": "b", "text": "Echocardiogram"}, {"id": "c", "text": "Renal labs with BP monitoring"}, {"id": "d", "text": "Barium swallow / manometry"}]'::jsonb, '["d"]', 'Barium swallow/manometry assesses esophageal motility, which explains dysphagia from esophageal dysmotility. HRCT is detailed lung imaging for ILD, an echocardiogram screens for PAH/right heart strain, and renal labs with BP monitoring watch for SRC.', false),
  ('scleroderma', 26, 'A client with diffuse cutaneous systemic sclerosis reports new palpitations. The pulse is irregular, BP is 128/80 mm Hg, and there is no headache or change in urine output. The client asks why this is happening. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "This irregular pulse is the first sign of renal crisis"}, {"id": "b", "text": "Esophageal reflux is the usual cause of this irregular pulse"}, {"id": "c", "text": "Fibrosis in the heart can cause arrhythmias like this"}, {"id": "d", "text": "Vasospasm in the fingers is causing this irregular pulse"}]'::jsonb, '["c"]', 'Cardiac involvement in scleroderma includes arrhythmias from fibrosis. Renal crisis presents with sudden severe hypertension, headache/vision changes and oliguria, which this client does not have.', false),
  ('scleroderma', 27, 'A nurse observes an unlicensed assistive personnel (UAP) caring for a client with systemic sclerosis who has Raynaud phenomenon, GERD, and tight skin on the hands. Which actions by the UAP require the nurse to intervene? Select all that apply.', '[{"id": "a", "text": "Assists the client with daily ROM exercises"}, {"id": "b", "text": "Keeps the room cold to relieve pruritus"}, {"id": "c", "text": "Puts gloves on the client before a walk outside"}, {"id": "d", "text": "Lays the client flat right after meals"}, {"id": "e", "text": "Applies moisturizer to the client''s hands"}]'::jsonb, '["b", "d"]', 'A cold room promotes vasospasm (keep warm, warm environment), and lying flat after a meal contradicts staying upright after meals. Moisturizing the hands protects from cracking, daily ROM exercises maintain mobility, and gloves prevent vasospasm, so those actions are correct.', true),
  ('scleroderma', 28, 'A client with sclerodactyly and progressive tightening of the skin on both hands can no longer fully close the fists. The client says, "Moving my fingers hurts, so I just keep them still." Which nursing action is BEST?', '[{"id": "a", "text": "Limit hand use to prevent new ulcers on the fingertips"}, {"id": "b", "text": "Immobilize the hands until the skin tightening improves"}, {"id": "c", "text": "Apply ice packs before exercise to reduce the finger pain"}, {"id": "d", "text": "Encourage ROM exercises daily and use splints as ordered"}]'::jsonb, '["d"]', 'Daily ROM exercises plus splints as ordered maintain ROM and help prevent contractures. Keeping the hands still allows progressive skin tightening to decrease ROM further, and cold triggers vasospasm.', false),
  ('scleroderma', 29, 'A nurse reviews the findings of a client referred for possible systemic sclerosis: a malar rash, photosensitivity, nephritis, and low complement levels. There is no skin tightening. These findings are MOST consistent with which condition?', '[{"id": "a", "text": "Dermatomyositis"}, {"id": "b", "text": "SLE"}, {"id": "c", "text": "Rheumatoid arthritis"}, {"id": "d", "text": "Scleroderma"}]'::jsonb, '["b"]', 'Malar rash, nephritis, photosensitivity and low complements are SLE features. Scleroderma is defined by tight skin, Raynaud, GI dysmotility, lung fibrosis/PAH and renal crisis.', false),
  ('scleroderma', 30, 'A client is being evaluated for an autoimmune disorder. Which findings would support scleroderma rather than another autoimmune condition? Select all that apply.', '[{"id": "a", "text": "Tight skin with Raynaud phenomenon"}, {"id": "b", "text": "Proximal weakness with heliotrope rash"}, {"id": "c", "text": "Symmetric joint swelling with erosions"}, {"id": "d", "text": "Malar rash with low complements"}, {"id": "e", "text": "GI dysmotility with lung fibrosis"}]'::jsonb, '["a", "e"]', 'Scleroderma features tight skin, Raynaud, GI dysmotility, lung fibrosis/PAH and renal crisis. Proximal weakness with heliotrope rash is dermatomyositis, symmetric joint swelling with erosions is rheumatoid arthritis, and malar rash with low complements is SLE.', true),
  ('scleroderma', 31, 'A client reports that both hands looked swollen and puffy for several months. Now the skin over the fingers feels tight and the client cannot make a full fist. Raynaud episodes began last winter. The nurse interprets this hand finding as the MOST likely result of which process?', '[{"id": "a", "text": "Telangiectasia with dilated vessels causing finger swelling"}, {"id": "b", "text": "Calcinosis cutis forming firm nodules that block finger motion"}, {"id": "c", "text": "Early edema progressing to skin tightening with decreased ROM"}, {"id": "d", "text": "Tendon friction rub indicating the limited cutaneous pattern"}]'::jsonb, '["c"]', 'Scleroderma begins with edema of the hands (puffy fingers) and progresses to skin tightening with decreased ROM. A tendon friction rub suggests diffuse, not limited, disease, and telangiectasias are small dilated vessels seen as red pinpoint lesions.', false),
  ('scleroderma', 32, 'A client with systemic sclerosis asks why the fingers turn white and painful when holding a cold drink. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Injury to the vessel lining narrows vessels and reduces blood flow"}, {"id": "b", "text": "Small dilated vessels near the surface leak blood out of the fingers"}, {"id": "c", "text": "Calcium deposits under the skin block the arteries in the fingers"}, {"id": "d", "text": "Excess collagen in the skin squeezes the fingertips when it is cold"}]'::jsonb, '["a"]', 'Endothelial injury leads to vasoconstriction and intimal proliferation, which decreases blood flow and causes ischemia and Raynaud phenomenon. Collagen deposition from fibroblast activation causes skin thickening and organ fibrosis, not the color change.', false),
  ('scleroderma', 33, 'A client has limited cutaneous systemic sclerosis with the classic syndrome associated with this pattern. When assessing the skin and hands, which findings should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Purple heliotrope rash on the upper eyelids"}, {"id": "b", "text": "Red pinpoint lesions from small dilated vessels"}, {"id": "c", "text": "Firm nodules from calcium deposits under the skin"}, {"id": "d", "text": "Tight finger skin with a tapering, claw-like posture"}, {"id": "e", "text": "Episodic white, blue, then red finger color change"}]'::jsonb, '["b", "c", "d", "e"]', 'CREST includes calcinosis (firm nodules from calcium deposits), Raynaud phenomenon (triphasic white-blue-red color change), sclerodactyly (tight thick finger skin with tapering/claw-like posture) and telangiectasia (red pinpoint lesions). A heliotrope rash is a feature of dermatomyositis.', true),
  ('scleroderma', 34, 'A client with diffuse cutaneous systemic sclerosis has an abrupt BP rise to 210/120 mm Hg, a rising creatinine, proteinuria and hematuria on urinalysis, a falling platelet count, and evidence of red blood cell destruction in small vessels. These findings are MOST consistent with which condition?', '[{"id": "a", "text": "SLE nephritis with low complement levels"}, {"id": "b", "text": "PAH with right heart failure"}, {"id": "c", "text": "Scleroderma renal crisis with MAHA"}, {"id": "d", "text": "Pericarditis from cardiac fibrosis"}]'::jsonb, '["c"]', 'SRC presents abruptly with severe hypertension, AKI, proteinuria/hematuria and sometimes MAHA (RBC destruction in small vessels) and thrombocytopenia. SLE nephritis is paired with malar rash, photosensitivity and low complements, not abrupt severe hypertension in diffuse scleroderma.', false),
  ('scleroderma', 35, 'A client with diffuse cutaneous systemic sclerosis who is positive for anti–RNA polymerase III antibodies is preparing for discharge. Which home self-monitoring instruction is MOST important for the nurse to emphasize?', '[{"id": "a", "text": "Check BP regularly and report a sudden rise"}, {"id": "b", "text": "Check your fingertips daily for color change in the cold"}, {"id": "c", "text": "Weigh yourself weekly to monitor for poor absorption"}, {"id": "d", "text": "Track how often heartburn occurs after your meals"}]'::jsonb, '["a"]', 'Anti–RNA polymerase III is associated with diffuse disease and renal crisis risk, so BP trends (sudden rise) are the key self-monitoring focus. Fingertip color change, weight and heartburn matter but do not signal the life-threatening emergency of SRC.', false),
  ('scleroderma', 36, 'A nurse teaches a client with systemic sclerosis who has tight, dry skin on both hands and a healing fingertip ulcer. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "I will report redness, drainage, or a fever around the sore."}, {"id": "b", "text": "I will rest my hands and skip range-of-motion exercises."}, {"id": "c", "text": "I will moisturize my hands to keep the skin from cracking."}, {"id": "d", "text": "I will stop wearing my splints once my fingers loosen."}, {"id": "e", "text": "I will soak my hands in cool water whenever they itch."}]'::jsonb, '["a", "c"]', 'Hand/skin care includes moisturizing to protect from cracking, and wound care includes reporting infection signs (redness, drainage, fever). Cool water exposure can trigger vasospasm, splints are used as ordered, and ROM exercises are done daily to prevent contractures.', true),
  ('scleroderma', 37, 'A client with systemic sclerosis has mask-like facies, microstomia, and dysphagia from esophageal dysmotility. The nurse observes a UAP assisting the client with lunch. Which action by the UAP requires follow-up by the nurse?', '[{"id": "a", "text": "Offers small bites and waits between each spoonful"}, {"id": "b", "text": "Offers large bites to finish the meal faster"}, {"id": "c", "text": "Keeps the client sitting upright after the meal ends"}, {"id": "d", "text": "Positions the client upright before the meal begins"}]'::jsonb, '["b"]', 'Dysphagia precautions call for small bites and upright positioning, so large bites increase aspiration risk in a client with a small mouth and dysmotility. Upright positioning before and after meals is correct.', false),
  ('scleroderma', 38, 'A client with diffuse cutaneous systemic sclerosis has rapidly worsening dyspnea, and HRCT chest shows severe interstitial lung disease. Which medication would the nurse anticipate as MOST appropriate for this severe ILD?', '[{"id": "a", "text": "Nifedipine"}, {"id": "b", "text": "Captopril"}, {"id": "c", "text": "Cyclophosphamide"}, {"id": "d", "text": "Methotrexate"}]'::jsonb, '["c"]', 'Cyclophosphamide is used for severe ILD. Methotrexate targets skin/joint inflammation, nifedipine is a vasodilator for Raynaud, and captopril is the ACE inhibitor for renal crisis.', false),
  ('scleroderma', 39, 'A client newly diagnosed with diffuse cutaneous systemic sclerosis reports a dry cough and dyspnea on exertion. The nurse hears fine inspiratory Velcro crackles. Which diagnostic tests should the nurse anticipate to evaluate this problem? Select all that apply.', '[{"id": "a", "text": "Barium swallow / manometry"}, {"id": "b", "text": "Anti-centromere antibody"}, {"id": "c", "text": "Creatinine, BUN, and UA"}, {"id": "d", "text": "PFTs with DLCO"}, {"id": "e", "text": "HRCT chest"}]'::jsonb, '["d", "e"]', 'Dry cough, exertional dyspnea and Velcro crackles suggest ILD; PFTs with decreased DLCO screen for ILD and HRCT chest gives detailed lung imaging for ILD. Barium swallow/manometry assesses esophageal motility, anti-centromere marks the limited/CREST pattern, and renal labs watch for SRC.', true),
  ('scleroderma', 40, 'A client with systemic sclerosis who has mask-like facies and a beak-like nose says, "I don''t recognize myself anymore, so I stopped seeing my friends." The client also reports chronic pain and fatigue. Which nursing action is BEST?', '[{"id": "a", "text": "Reassure the client that treatment will cure the changes"}, {"id": "b", "text": "Request a swallow evaluation because of the facial changes"}, {"id": "c", "text": "Focus teaching on moisturizing to restore the facial skin"}, {"id": "d", "text": "Provide psychosocial support focused on body image"}]'::jsonb, '["d"]', 'Psychosocial support for body image, chronic pain and fatigue is a core nursing intervention. Reassurance of a cure is inaccurate because there is no single cure; treatment targets individual organs and symptoms.', false),
  ('scleroderma', 41, 'A client with diffuse cutaneous systemic sclerosis asks why a disease that started with tight skin is now scarring the lungs. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Reflux of stomach acid into the lungs is the cause of all lung scarring"}, {"id": "b", "text": "Small dilated surface vessels in the lungs leak and form scar tissue"}, {"id": "c", "text": "Calcium deposits that form under the skin spread into the lung tissue"}, {"id": "d", "text": "Overactive collagen-producing cells deposit collagen in skin and organs"}]'::jsonb, '["d"]', 'Fibroblast activation (collagen-producing cells becoming overactive) causes collagen deposition, resulting in skin thickening and organ fibrosis. Calcium deposits cause calcinosis cutis under the skin, and reflux leads to aspiration rather than explaining fibrosis.', false),
  ('scleroderma', 42, 'A client is admitted with scleroderma renal crisis and has been started on captopril. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Monitor BP trends closely"}, {"id": "b", "text": "Monitor urine output"}, {"id": "c", "text": "Request high-dose steroids for the AKI"}, {"id": "d", "text": "Monitor creatinine, BUN, and UA"}, {"id": "e", "text": "Hold captopril if creatinine rises"}]'::jsonb, '["a", "b", "d"]', 'Nursing care for SRC includes monitoring BP trends, urine output and renal labs (creatinine, BUN, UA). The ACE inhibitor is continued even if creatinine rises initially, and high-dose steroids can increase SRC risk.', true),
  ('scleroderma', 43, 'A client with CREST syndrome has several firm, white nodules under the skin of the elbows and forearms. One nodule has broken open and is draining chalky material. The nurse recognizes this finding as MOST likely which process?', '[{"id": "a", "text": "Tendon friction rub over a joint"}, {"id": "b", "text": "Calcinosis cutis that has ulcerated"}, {"id": "c", "text": "A localized morphea plaque"}, {"id": "d", "text": "Telangiectasia that has bled"}]'::jsonb, '["b"]', 'Calcinosis cutis is calcium deposits under the skin forming firm nodules that can ulcerate. Telangiectasias are small dilated vessels seen as red pinpoint lesions, not firm nodules.', false),
  ('scleroderma', 44, 'A client with limited cutaneous systemic sclerosis has both pulmonary arterial hypertension and severe Raynaud phenomenon. Which drug class would BEST address both problems?', '[{"id": "a", "text": "Endothelin receptor antagonist"}, {"id": "b", "text": "Proton pump inhibitor"}, {"id": "c", "text": "PDE-5 inhibitor such as sildenafil"}, {"id": "d", "text": "Calcium channel blocker such as nifedipine"}]'::jsonb, '["c"]', 'PDE-5 inhibitors such as sildenafil appear as a vasodilator for Raynaud and as a PAH agent. Endothelin receptor antagonists are listed for PAH only, CCBs such as nifedipine for Raynaud only, and PPIs for GERD.', false),
  ('scleroderma', 45, 'A client has had systemic sclerosis for 8 years. During a skin and facial assessment, which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Beak-like nose"}, {"id": "b", "text": "Mask-like facies"}, {"id": "c", "text": "Microstomia (small mouth)"}, {"id": "d", "text": "Heliotrope rash on the eyelids"}, {"id": "e", "text": "Malar rash across the cheeks"}]'::jsonb, '["a", "b", "c"]', 'The classic scleroderma picture includes mask-like facies, microstomia and a beak-like nose. A malar rash is a feature of SLE, and a heliotrope rash is a feature of dermatomyositis.', true),
  ('scleroderma', 46, 'A client with systemic sclerosis and Raynaud phenomenon has a head cold and asks whether an over-the-counter cold tablet containing a decongestant is safe to take. Which response by the nurse is BEST?', '[{"id": "a", "text": "Take it, but wear gloves while it is in your system"}, {"id": "b", "text": "Take it at bedtime, when your hands are warmest"}, {"id": "c", "text": "Avoid decongestants, since they are vasoconstrictors"}, {"id": "d", "text": "Take it, since nifedipine will offset its effect"}]'::jsonb, '["c"]', 'Clients with Raynaud should avoid vasoconstrictors, including decongestants, nicotine and excess caffeine. Gloves and nifedipine help with Raynaud but do not make a vasoconstrictor safe.', false),
  ('scleroderma', 47, 'A nurse is planning care for a client with diffuse cutaneous systemic sclerosis who has Raynaud phenomenon, GERD, a healing digital ulcer, and new exertional dyspnea with a dry cough. Which nursing focus has the HIGHEST priority?', '[{"id": "a", "text": "Assess dysphagia, reflux symptoms, and weight loss"}, {"id": "b", "text": "Protect skin integrity and maintain the client''s ROM"}, {"id": "c", "text": "Assess Raynaud severity, cap refill, and skin temperature"}, {"id": "d", "text": "Assess dyspnea, cough, and crackles and monitor SpO2"}]'::jsonb, '["d"]', 'Airway/breathing is listed first among the nursing priorities, and lung disease is the top cause of mortality in scleroderma. Circulation, GI safety and skin integrity are important but follow airway and breathing.', false),
  ('scleroderma', 48, 'During a Raynaud episode, a client''s fingers turned white, then blue, and are now bright red and throbbing as they rewarm. There is no drainage, and the client is afebrile. How should the nurse interpret the red phase?', '[{"id": "a", "text": "New telangiectasias forming"}, {"id": "b", "text": "Reperfusion after the vasospasm"}, {"id": "c", "text": "Inflamed calcinosis nodules"}, {"id": "d", "text": "Infection of an early digital ulcer"}]'::jsonb, '["b"]', 'Raynaud phenomenon is a triphasic white-blue-red color change from vasospasm and reperfusion; the red phase is reperfusion. Infection signs would include redness with drainage or fever, which are absent here.', false),
  ('scleroderma', 49, 'A client with skin thickening of the upper arms and trunk tests positive for anti–Scl-70 (topoisomerase I) antibodies. At each follow-up visit, which assessment should the nurse PRIORITIZE based on this antibody result?', '[{"id": "a", "text": "Hands for puffy fingers from early edema"}, {"id": "b", "text": "Lung sounds for fine inspiratory crackles and SpO2"}, {"id": "c", "text": "Fingertips for firm calcium nodules that may ulcerate"}, {"id": "d", "text": "Facial skin for red pinpoint lesions of telangiectasia"}]'::jsonb, '["b"]', 'Anti–Scl-70 is associated with diffuse disease and ILD risk, so the nurse prioritizes lung assessment for fine inspiratory (Velcro) crackles and SpO2. Calcinosis and telangiectasia are CREST (limited) features, and puffy fingers are an early skin finding rather than a sign of organ risk.', false),
  ('scleroderma', 50, 'A client with diffuse cutaneous systemic sclerosis, interstitial lung disease, and thickened skin begins mycophenolate mofetil. Which statement by the client indicates understanding of the reason for this medication?', '[{"id": "a", "text": "This is being used for my lung disease and my skin."}, {"id": "b", "text": "This will lower the acid that causes my heartburn."}, {"id": "c", "text": "This is the main treatment if my kidneys go into crisis."}, {"id": "d", "text": "This will widen the blood vessels in my cold fingers."}]'::jsonb, '["a"]', 'Mycophenolate mofetil is often used for ILD/skin. Vasodilators such as nifedipine treat Raynaud, an ACE inhibitor treats renal crisis, and PPIs/H2 blockers treat reflux.', false),
  ('tbi', 1, 'A client is brought to the emergency department after being struck in the head with a baseball bat. A witness says the client was unconscious for about 1 minute, then woke up, talked normally, and refused care. Forty minutes later the client is difficult to arouse and the right pupil is larger than the left. Which condition does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Concussion causing temporary brain dysfunction"}, {"id": "b", "text": "Epidural hematoma from arterial bleeding"}, {"id": "c", "text": "Chronic subdural hematoma from venous bleeding"}, {"id": "d", "text": "Post-concussion syndrome with delayed symptoms"}]'::jsonb, '["b"]', 'Brief LOC, then a lucid interval in which the client appears fine, then rapid decline is the classic picture of an epidural hematoma, which is arterial (rapid) bleeding and a neurosurgical emergency. A subdural hematoma is venous (slower) and its symptoms may be delayed, especially the chronic type, so it does not explain a decline within 40 minutes.', false),
  ('tbi', 2, 'An 82-year-old client struck the head on a nightstand during a fall at home 3 weeks ago and felt fine afterward. The daughter now reports 4 days of increasing confusion and headache. Which type of injury does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Epidural hematoma with a lucid interval"}, {"id": "b", "text": "Diffuse axonal injury from shearing forces"}, {"id": "c", "text": "Concussion with temporary brain dysfunction"}, {"id": "d", "text": "Subdural hematoma from venous bleeding"}]'::jsonb, '["d"]', 'Subdural hematoma is venous (slower) bleeding, is common in older adults because brain shrinkage stretches veins, and its symptoms may be delayed, especially the chronic type. An epidural hematoma is arterial and declines rapidly after a brief lucid interval, not weeks later.', false),
  ('tbi', 3, 'A client who fell from a ladder is admitted, and the CT scan shows a hematoma located between the skull and the dura mater. Which features does the nurse expect with this type of bleed? Select all that apply.', '[{"id": "a", "text": "Usually arterial bleeding that is rapid"}, {"id": "b", "text": "Bleeding located between dura and arachnoid mater"}, {"id": "c", "text": "Often associated with skull fracture"}, {"id": "d", "text": "Emergency surgery may be needed quickly"}, {"id": "e", "text": "Common in older adults due to brain shrinkage"}]'::jsonb, '["a", "c", "d"]', 'A bleed between the skull and dura mater is an epidural hematoma. (a) Correct: it is usually arterial bleeding and rapid. (c) Correct: it is often associated with skull fracture. (d) Correct: emergency surgery may be needed quickly. (b) Wrong: bleeding between the dura and arachnoid mater is a subdural hematoma. (e) Wrong: being common in older adults because brain shrinkage stretches veins describes subdural hematoma.', true),
  ('tbi', 4, 'A client admitted after a motorcycle crash has bilateral periorbital bruising, bruising behind the ears over the mastoid area, and nausea with vomiting. A new nurse shares the plan of care. Which planned action requires IMMEDIATE correction?', '[{"id": "a", "text": "Elevate the head of the bed about 30 degrees"}, {"id": "b", "text": "Keep suction and oxygen available at the bedside"}, {"id": "c", "text": "Insert a nasogastric tube to manage the vomiting"}, {"id": "d", "text": "Keep the bed in the lowest position with padded rails"}]'::jsonb, '["c"]', 'Raccoon eyes and Battle sign indicate a basilar skull fracture, so nothing is inserted into the nose, including a nasogastric tube, unless specifically ordered and cleared because of the risk of entering the brain. Elevating the HOB, keeping suction and oxygen ready, and a low bed with padded rails are all appropriate.', false),
  ('tbi', 5, 'Two hours after a fall, a client with a head injury has a steady drip of clear fluid from the right nostril. When a drop of the blood-tinged drainage is placed on gauze, a pale ring spreads around a central spot of blood. Which action by the nurse is BEST?', '[{"id": "a", "text": "Report it immediately and do not pack the nose"}, {"id": "b", "text": "Pack the nostril loosely with gauze to contain the leak"}, {"id": "c", "text": "Suction the nares gently to keep the airway clear"}, {"id": "d", "text": "Document it as expected drainage after facial bruising"}]'::jsonb, '["a"]', 'A ring pattern on gauze is the halo sign of CSF mixed with blood; a CSF leak raises meningitis risk, so the nose is not packed and clear drainage from the nose is reported at once. Nasal suction is avoided when a basilar skull fracture is suspected, and this drainage is not an expected finding.', false),
  ('tbi', 6, 'A 16-year-old soccer player is going home after a concussion, and the parent asks how to care for the teen during recovery. Which instructions should the nurse include in the discharge teaching? Select all that apply.', '[{"id": "a", "text": "Reduce intense studying and screen use for now"}, {"id": "b", "text": "Avoid alcohol and sedatives unless prescribed"}, {"id": "c", "text": "Return to practice once the headache is gone"}, {"id": "d", "text": "Have a responsible adult observe the teen"}, {"id": "e", "text": "Keep up weight training to maintain fitness"}]'::jsonb, '["a", "b", "d"]', '(a) Correct: cognitive rest means reducing intense studying, screen use, and concentration tasks. (b) Correct: alcohol and sedatives are avoided unless prescribed. (d) Correct: a responsible adult should observe the patient. (c) Wrong: return to activity is gradual and only after medical clearance, not when one symptom resolves. (e) Wrong: physical rest means avoiding strenuous activity.', true),
  ('tbi', 7, 'The nurse reviews discharge teaching with the parents of a 14-year-old who was hit in the head during a football game. The teen was dazed and cannot remember the play but was never unconscious. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "He should rest his brain by cutting back on screens and homework."}, {"id": "b", "text": "He never lost consciousness, so he cannot have a concussion."}, {"id": "c", "text": "We will come back right away if he keeps vomiting or slurs his words."}, {"id": "d", "text": "He cannot go back to football until his provider fully clears him."}]'::jsonb, '["b"]', 'Loss of consciousness is NOT required for a concussion diagnosis; a patient may be fully awake and still have a concussion, and amnesia supports the diagnosis. The other statements reflect correct teaching about cognitive rest, return precautions, and clearance before sports.', false),
  ('tbi', 8, 'A 17-year-old basketball player had a concussion 5 days ago and still has daily headaches and trouble concentrating. The teen asks to play in tomorrow''s championship game, calling the symptoms minor. Which complication is the nurse MOST concerned about if the teen plays?', '[{"id": "a", "text": "Diffuse axonal injury from widespread shearing forces"}, {"id": "b", "text": "Post-concussion syndrome with chronic headaches"}, {"id": "c", "text": "Second impact syndrome with rapid brain swelling"}, {"id": "d", "text": "Chronic subdural hematoma with delayed symptoms"}]'::jsonb, '["c"]', 'The teen is not yet recovered; a second concussion before recovery from the first can cause second impact syndrome, a rapid and often fatal brain swelling, so the patient must not return to sports until fully cleared. Post-concussion syndrome describes persistent symptoms, not the danger of a repeat injury.', false),
  ('tbi', 9, 'A 22-year-old is observed in the emergency department for 6 hours after a concussion from a fall. Which findings during this observation period require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Repeated vomiting after the head injury"}, {"id": "b", "text": "Sensitivity to the bright overhead lights"}, {"id": "c", "text": "Pupils that are now unequal in size"}, {"id": "d", "text": "Reports feeling foggy and tired"}, {"id": "e", "text": "New unilateral weakness of the hand"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: repeated vomiting after head injury is concerning and may suggest increased ICP. (c) Correct: unequal pupils are dangerous and may indicate pressure on cranial nerves or herniation. (e) Correct: unilateral weakness is a finding to report at once. (b) Wrong: sensitivity to light is a mild TBI/concussion symptom. (d) Wrong: feeling foggy and fatigue are also mild concussion symptoms.', true),
  ('tbi', 10, 'A client with a severe TBI had vital signs 2 hours ago of BP 132/80, HR 86, and RR 16 and regular. Which current set of vital signs requires IMMEDIATE intervention?', '[{"id": "a", "text": "BP 140/88, HR 94, RR 20 and regular"}, {"id": "b", "text": "BP 126/78, HR 78, RR 18 and regular"}, {"id": "c", "text": "BP 136/84, HR 100, RR 22 and regular"}, {"id": "d", "text": "BP 186/64, HR 48, RR 10 and irregular"}]'::jsonb, '["d"]', 'Bradycardia, a widened pulse pressure (186 - 64 = 122), and irregular respirations form Cushing''s triad, a late sign of impending herniation and a medical emergency. The other sets keep a normal pulse pressure and regular respirations without bradycardia.', false),
  ('tbi', 11, 'During hourly neuro checks, the nurse noted that a client with a TBI had abnormal flexion of the arms toward the body with extended legs. Now the arms and legs are rigidly extended and the arms are pronated. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Brainstem involvement, which is worse than before"}, {"id": "b", "text": "Improvement in status, since abnormal flexion has resolved"}, {"id": "c", "text": "Injury that is limited to areas above the brainstem"}, {"id": "d", "text": "Expected seizure activity that is common after brain injury"}]'::jsonb, '["a"]', 'The client has progressed from decorticate posturing (injury above the brainstem) to decerebrate posturing, which indicates brainstem involvement and is worse than decorticate. Moving from flexion to extension is deterioration, not improvement.', false),
  ('tbi', 12, 'A client with a moderate TBI is showing signs of increased ICP, and the nurse is repositioning the client after a bed bath. Which positioning actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Place two pillows under the head to flex the neck"}, {"id": "b", "text": "Elevate the head of the bed about 30 degrees"}, {"id": "c", "text": "Keep the head in a midline position"}, {"id": "d", "text": "Turn the head to the side to drain secretions"}, {"id": "e", "text": "Avoid hip flexion when positioning the legs"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: elevate HOB ~30 degrees unless contraindicated. (c) Correct: keep the head midline, which supports venous drainage. (e) Correct: avoid hip flexion if possible. (a) Wrong: neck flexion is avoided. (d) Wrong: the head is kept midline, avoiding turning to either side.', true),
  ('tbi', 13, 'The nurse receives report on four clients on a neurology unit at the start of the shift. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client with a concussion who has a headache and light sensitivity"}, {"id": "b", "text": "A client with a contusion who has sudden restlessness and confusion"}, {"id": "c", "text": "A client with a subdural hematoma who reports fatigue and irritability"}, {"id": "d", "text": "A client with a linear fracture who asks about returning to work soon"}]'::jsonb, '["b"]', 'Sudden restlessness or confusion is a finding to report at once because it can signal rising ICP and deterioration, and a contusion is more serious than a concussion. Headache, light sensitivity, fatigue, and irritability are mild TBI symptoms, and a teaching request can wait.', false),
  ('tbi', 14, 'A client with a severe TBI responds only to pain, has snoring respirations with vomitus pooled in the mouth, and has a falling oxygen saturation. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Perform a full neuro check including pupil size and reaction"}, {"id": "b", "text": "Elevate the head of the bed to about 30 degrees"}, {"id": "c", "text": "Suction the airway and administer oxygen as ordered"}, {"id": "d", "text": "Administer mannitol as ordered to reduce the ICP"}]'::jsonb, '["c"]', 'A decreased LOC can cause loss of airway protection, so maintaining the airway (suction if needed, oxygen as ordered) is always the first priority, ahead of neuro checks and ICP control. Neurologic assessment and mannitol come after airway, breathing, and circulation.', false),
  ('tbi', 15, 'A client is admitted after a motor vehicle crash with diffuse axonal injury and a scalp laceration. The nurse plans care to protect oxygenation, perfusion, and ICP. Which conditions should the nurse work to prevent or limit? Select all that apply.', '[{"id": "a", "text": "Hypotension"}, {"id": "b", "text": "Brain tissue laceration"}, {"id": "c", "text": "Hypoxia"}, {"id": "d", "text": "Infection"}, {"id": "e", "text": "Seizures"}]'::jsonb, '["a", "c", "d", "e"]', 'Secondary injury develops after the trauma and is where nursing care matters most. (a) Correct: hypotension is secondary injury. (c) Correct: hypoxia is secondary injury. (d) Correct: infection is secondary injury. (e) Correct: seizures are secondary injury. (b) Wrong: laceration (tissue tear) is primary injury, immediate damage at the moment of trauma that cannot be undone.', true),
  ('tbi', 16, 'A client with cerebral edema after a TBI is receiving mannitol. Which assessments are the key nursing monitoring points for this specific medication? Select all that apply.', '[{"id": "a", "text": "Fluid balance"}, {"id": "b", "text": "Kidney function"}, {"id": "c", "text": "Serum osmolality"}, {"id": "d", "text": "Seizure frequency"}, {"id": "e", "text": "Blood pressure"}]'::jsonb, '["a", "b", "c", "e"]', 'Mannitol is an osmotic diuretic that draws fluid out of brain tissue. (a) Correct: monitor fluid balance. (b) Correct: monitor kidney function. (c) Correct: monitor serum osmolality. (e) Correct: monitor blood pressure. (d) Wrong: seizure prevention and treatment is the purpose of anticonvulsants, not a mannitol monitoring point.', true),
  ('tbi', 17, 'A client with a moderate TBI rates a headache 8/10 and asks for a stronger pain medicine. The spouse asks why the nurse is cautious about giving pain medicine. Which response by the nurse is BEST?', '[{"id": "a", "text": "Pain medicine is used carefully because it can mask neuro changes."}, {"id": "b", "text": "Pain medicine is avoided because it pulls fluid from brain tissue."}, {"id": "c", "text": "Pain medicine is withheld until all seizures have been controlled."}, {"id": "d", "text": "Pain medicine is limited because it causes water retention and low sodium."}]'::jsonb, '["a"]', 'Analgesics are given for pain relief but used carefully because they can mask neuro changes that signal deterioration. Pulling fluid from brain tissue describes mannitol or hypertonic saline, and water retention with low sodium describes SIADH.', false),
  ('tbi', 18, 'A client with a severe TBI is placed on seizure precautions, and the nurse checks the room set-up at the start of the shift. Which findings indicate the precautions are in place correctly? Select all that apply.', '[{"id": "a", "text": "Side rails are padded"}, {"id": "b", "text": "Soft wrist restraints are ready for use during a seizure"}, {"id": "c", "text": "Suction and oxygen are available at the bedside"}, {"id": "d", "text": "The bed is raised to the nurse''s working height"}, {"id": "e", "text": "A nasogastric tube is at the bedside for a seizure"}]'::jsonb, '["a", "c"]', '(a) Correct: padded side rails are part of seizure safety. (c) Correct: suction and oxygen should be available at the bedside. (b) Wrong: the client is protected from injury during a seizure but not restrained. (d) Wrong: the bed should be in the lowest position. (e) Wrong: a nasogastric tube is not part of the seizure safety setup.', true),
  ('tbi', 19, 'A UAP is assisting with care for a client who has signs of increased ICP after a TBI. Which action by the UAP requires the nurse to intervene IMMEDIATELY?', '[{"id": "a", "text": "Keeping the client''s head in a midline position"}, {"id": "b", "text": "Positioning the client in extreme hip flexion"}, {"id": "c", "text": "Dimming the lights and limiting room visitors"}, {"id": "d", "text": "Keeping the head of the bed elevated 30 degrees"}]'::jsonb, '["b"]', 'Extreme hip flexion is an activity that increases ICP and should be avoided. Keeping the head midline, reducing stimulation, and elevating the HOB about 30 degrees are correct ICP interventions.', false),
  ('tbi', 20, 'Three days after a severe TBI, a client has decreasing urine output, a 2-kg weight gain, new confusion, and a serum sodium below the normal range. The client has not received hypertonic saline. Which complication is MOST likely developing?', '[{"id": "a", "text": "Diabetes insipidus from a lack of ADH effect"}, {"id": "b", "text": "Dehydration from excessive urination"}, {"id": "c", "text": "SIADH causing dilutional hyponatremia"}, {"id": "d", "text": "Increased ICP from an expanding hematoma"}]'::jsonb, '["c"]', 'Too much antidiuretic hormone (SIADH) causes water retention and dilutional hyponatremia, matching the low urine output, weight gain, and low sodium. Diabetes insipidus is the opposite, causing excessive urination and dehydration.', false),
  ('tbi', 21, 'A client with a TBI who is not receiving any diuretics suddenly has a very large urine output with signs of dehydration. Which condition does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Diabetes insipidus from a lack of ADH effect"}, {"id": "b", "text": "SIADH from too much antidiuretic hormone"}, {"id": "c", "text": "Cushing''s triad from impending herniation"}, {"id": "d", "text": "Second impact syndrome from a repeat concussion"}]'::jsonb, '["a"]', 'Lack of ADH effect (diabetes insipidus) causes excessive urination and dehydration, the opposite of SIADH, which causes water retention. Serum sodium, intake and output, and hydration status are monitored.', false),
  ('tbi', 22, 'A client with a severe TBI has a temperature of 39.2°C (102.6°F). BP is 124/78, HR is 96, and the GCS is unchanged from the last neuro check. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Recheck the temperature in 4 hours, since fever is expected"}, {"id": "b", "text": "Lower the head of the bed flat to improve cerebral perfusion"}, {"id": "c", "text": "Restrict fluids to prevent water retention and low sodium"}, {"id": "d", "text": "Monitor and treat the fever promptly as prescribed"}]'::jsonb, '["d"]', 'Fever increases metabolic demand and may worsen brain injury, so it is monitored and treated promptly. Lowering the HOB flat contradicts the ~30 degree elevation used to prevent increased ICP.', false),
  ('tbi', 23, 'A client with a TBI has a BP of 84/50; 1 hour ago it was 128/76. The spouse asks why the nurse is so concerned about the blood pressure when the client''s pupils are unchanged. Which response by the nurse is BEST?', '[{"id": "a", "text": "Low blood pressure raises the risk of a CSF leak from the nose."}, {"id": "b", "text": "Low blood pressure reduces cerebral perfusion and worsens injury."}, {"id": "c", "text": "Low blood pressure is an early sign of Cushing''s triad forming."}, {"id": "d", "text": "Low blood pressure shows that the swelling in the brain is resolving."}]'::jsonb, '["b"]', 'Hypotension is a secondary injury because low blood pressure reduces cerebral perfusion, worsening brain injury. Cushing''s triad involves bradycardia, widened pulse pressure, and irregular respirations, not hypotension.', false),
  ('tbi', 24, 'A client admitted with a cerebral contusion had a mild headache, fatigue, and noise sensitivity on admission. During hourly neuro checks, which findings should the nurse report to the health care provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Bradycardia with irregular respirations"}, {"id": "b", "text": "Fatigue after a morning bath"}, {"id": "c", "text": "Sensitivity to noise from the hallway"}, {"id": "d", "text": "Inability to awaken the client"}, {"id": "e", "text": "Mild headache at the same intensity as earlier"}]'::jsonb, '["a", "d"]', '(a) Correct: bradycardia with irregular respirations is a report-at-once finding (part of Cushing''s triad). (d) Correct: inability to awaken is a report-at-once finding. (b), (c), (e) Wrong: fatigue, sensitivity to noise, and a headache that has not worsened are mild TBI symptoms already present on admission; it is a worsening headache that must be reported.', true),
  ('tbi', 25, 'A client with a TBI has GCS scores of 14 at 0800, 14 at 0900, and 11 at 1000. The pupils remain equal and reactive, and vital signs are stable. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recheck the GCS in 1 hour to confirm the trend"}, {"id": "b", "text": "Document the score, since the pupils remain equal"}, {"id": "c", "text": "Report the falling GCS at once"}, {"id": "d", "text": "Give the prn analgesic to ease the client''s agitation"}]'::jsonb, '["c"]', 'A lower GCS means worse neurologic status, and a falling GCS is alarming and reported immediately; equal pupils do not make a dropping score reassuring. Analgesics are used carefully because they can mask neuro changes.', false),
  ('tbi', 26, 'A client arrives in the emergency department 20 minutes after a car crash with a headache, repeated vomiting, and confusion. Airway, breathing, and circulation are stable. Which diagnostic test should the nurse anticipate FIRST?', '[{"id": "a", "text": "CT scan of the head"}, {"id": "b", "text": "MRI of the brain"}, {"id": "c", "text": "Skull X-rays"}, {"id": "d", "text": "Insertion of an ICP monitoring device"}]'::jsonb, '["a"]', 'CT is the first choice in acute head trauma because it quickly shows bleeding, swelling, fractures, and mass effect. MRI is more detailed but is used for further evaluation after initial stabilization, and X-rays are less informative than CT.', false),
  ('tbi', 27, 'A 19-year-old has remained in a coma since a high-speed rollover crash 3 days ago. There was no lucid interval, and no skull fracture was found. Which type of injury does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Epidural hematoma from arterial bleeding"}, {"id": "b", "text": "Concussion with temporary brain dysfunction"}, {"id": "c", "text": "Basilar skull fracture with CSF leak"}, {"id": "d", "text": "Diffuse axonal injury from shearing forces"}]'::jsonb, '["d"]', 'Diffuse axonal injury is widespread nerve fiber damage from rapid acceleration/deceleration in high-speed trauma and often causes prolonged unconsciousness or coma. Epidural hematoma is often associated with skull fracture and shows a lucid interval before rapid decline.', false),
  ('tbi', 28, 'After a fall, a client has new weakness of the left hand, and imaging shows a bruise on the brain tissue. The daughter says, ''So this is just a concussion, right?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "No, this is a bruise of the brain that can cause localized deficits."}, {"id": "b", "text": "Yes, a contusion is the most common mild form of a brain injury."}, {"id": "c", "text": "No, this is widespread nerve fiber damage from rapid deceleration."}, {"id": "d", "text": "Yes, it causes only temporary changes in brain function, not damage."}]'::jsonb, '["a"]', 'A contusion is a bruise on brain tissue, more serious than concussion, and may cause localized deficits such as the hand weakness. Concussion, not contusion, is the most common mild form of TBI with temporary dysfunction.', false),
  ('tbi', 29, 'A client who fell backward and struck the back of the head on concrete is assessed 6 hours later. Which findings should the nurse recognize as signs of a fracture at the base of the skull? Select all that apply.', '[{"id": "a", "text": "Abnormal flexion of the arms toward the body"}, {"id": "b", "text": "Bruising behind the ears over the mastoid area"}, {"id": "c", "text": "Widened pulse pressure with bradycardia"}, {"id": "d", "text": "Blood behind the eardrum on otoscopic exam"}, {"id": "e", "text": "Bilateral periorbital bruising"}]'::jsonb, '["b", "d", "e"]', '(b) Correct: Battle sign is bruising behind the ears over the mastoid area. (d) Correct: hemotympanum is blood behind the eardrum. (e) Correct: raccoon eyes are bilateral periorbital bruising. (a) Wrong: abnormal flexion of the arms toward the body is decorticate posturing. (c) Wrong: widened pulse pressure with bradycardia is part of Cushing''s triad.', true),
  ('tbi', 30, 'Four hours after admission for a head injury, a client who had been calm becomes restless and confused and vomits suddenly without reporting nausea. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Expected symptoms of a mild concussion"}, {"id": "b", "text": "Dilutional hyponatremia from SIADH"}, {"id": "c", "text": "Early signs of increased ICP"}, {"id": "d", "text": "Onset of post-concussion syndrome"}]'::jsonb, '["c"]', 'Restlessness, confusion, and vomiting, especially without nausea, are signs of increased ICP that develop as bleeding or swelling builds. A concussion can worsen later, so new restlessness and vomiting are not simply expected mild symptoms.', false),
  ('tbi', 31, 'During a neuro check, the nurse finds that a client''s right pupil is 6 mm and sluggish while the left pupil is 3 mm and brisk. One hour ago both pupils were 3 mm and brisk. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report it at once, as it may indicate pressure on cranial nerves"}, {"id": "b", "text": "Recheck in 4 hours, since unequal pupils are expected after trauma"}, {"id": "c", "text": "Hold the next analgesic dose, since the pupils show a drug effect"}, {"id": "d", "text": "Avoid nasal suction, since the pupils suggest a basilar fracture"}]'::jsonb, '["a"]', 'Unequal pupils are dangerous and may indicate pressure on cranial nerves or herniation, so they are reported at once. Basilar skull fracture signs are Battle sign, raccoon eyes, hemotympanum, and CSF leak, not unequal pupils.', false),
  ('tbi', 32, 'The nurse is teaching the spouse of a 40-year-old who is going home after a concussion. Which changes should prompt the spouse to bring the client back for care IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Mild irritability during the first few days"}, {"id": "b", "text": "Unusual drowsiness or inability to wake up"}, {"id": "c", "text": "Clear fluid draining from the nose or ears"}, {"id": "d", "text": "Feeling tired after a full day of activity"}, {"id": "e", "text": "A seizure or new slurred speech"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: unusual drowsiness and inability to wake up are return-immediately signs. (c) Correct: clear fluid from the nose or ears is a return-immediately sign. (e) Correct: seizures and slurred speech are return-immediately signs. (a) Wrong: irritability is a mild concussion symptom. (d) Wrong: fatigue is a mild concussion symptom.', true),
  ('tbi', 33, 'A client is admitted after a nail-gun accident in which a nail penetrated the skull. Which complication should the nurse monitor for MOST closely because of this type of head injury?', '[{"id": "a", "text": "Post-concussion syndrome"}, {"id": "b", "text": "Diabetes insipidus"}, {"id": "c", "text": "Chronic subdural hematoma"}, {"id": "d", "text": "Infection"}]'::jsonb, '["d"]', 'In an open head injury the skull is penetrated, creating a high risk for infection along with direct tissue destruction. Post-concussion syndrome follows concussion, which is a closed head injury.', false),
  ('tbi', 34, 'A client recovering from a severe TBI is now awake but coughs when swallowing saliva. The swallow has not been assessed yet, and the family brings soup and asks to feed the client. Which action by the nurse is BEST?', '[{"id": "a", "text": "Allow small sips of soup with the head of the bed elevated"}, {"id": "b", "text": "Keep the client NPO until the swallow is assessed as safe"}, {"id": "c", "text": "Let the family feed the client, since the client is awake"}, {"id": "d", "text": "Insert a nasogastric tube and give the soup through it"}]'::jsonb, '["b"]', 'If swallow is impaired, the swallow is assessed before any oral intake and the client is kept NPO until safe, preventing aspiration. Being awake does not make oral intake safe, and tube feeding is a later option if needed, not a first step.', false),
  ('tbi', 35, 'A client with a severe TBI has been stabilized in the ICU and has an impaired swallow. Which interventions should the nurse include in the ongoing plan of care? Select all that apply.', '[{"id": "a", "text": "Turn the client regularly to protect the skin"}, {"id": "b", "text": "Perform range-of-motion exercises"}, {"id": "c", "text": "Keep the client flat in bed to promote perfusion"}, {"id": "d", "text": "Monitor bowel and bladder function"}, {"id": "e", "text": "Give tube feeding as prescribed for nutrition"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: protect skin by turning regularly. (b) Correct: perform range-of-motion exercises. (d) Correct: monitor bowel and bladder function. (e) Correct: with an impaired swallow, tube (enteral) feeding may be needed to maintain adequate nutrition. (c) Wrong: the HOB is elevated about 30 degrees to help prevent increased ICP, not kept flat.', true),
  ('tbi', 36, 'A client with a TBI has a decreasing LOC, gurgling respirations with pooled secretions, left-sided weakness, slurred speech, and confusion about the date. Which nursing diagnosis has the HIGHEST priority?', '[{"id": "a", "text": "Impaired physical mobility"}, {"id": "b", "text": "Acute confusion"}, {"id": "c", "text": "Risk for ineffective airway clearance"}, {"id": "d", "text": "Impaired verbal communication"}]'::jsonb, '["c"]', 'A patient with decreasing LOC cannot protect the airway, so airway is always first; pooled secretions show risk of being unable to clear secretions and maintain an open airway. Mobility, confusion, and communication problems are real but rank below airway.', false),
  ('tbi', 37, 'A college student with a concussion remembers the ambulance ride but cannot recall walking onto the field or the play before the collision. The student was never unconscious. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Retrograde amnesia, which supports a concussion diagnosis"}, {"id": "b", "text": "Anterograde amnesia, which supports a concussion diagnosis"}, {"id": "c", "text": "A sign of herniation that requires emergency surgery"}, {"id": "d", "text": "Not a concussion, because there was no loss of consciousness"}]'::jsonb, '["a"]', 'Inability to remember events before the injury is retrograde amnesia, which supports a concussion diagnosis; anterograde amnesia is inability to remember events after the injury. Loss of consciousness is not required for the diagnosis.', false),
  ('tbi', 38, 'Six weeks after a concussion, a 20-year-old reports persistent headache, dizziness, trouble concentrating in class, and irritability. Neuro checks, pupils, and GCS are normal, and there has been no new injury. Which condition does the nurse suspect is MOST likely?', '[{"id": "a", "text": "Second impact syndrome"}, {"id": "b", "text": "Post-concussion syndrome"}, {"id": "c", "text": "Chronic subdural hematoma"}, {"id": "d", "text": "Diffuse axonal injury"}]'::jsonb, '["b"]', 'Persistent headache, dizziness, concentration problems, and irritability after concussion describe post-concussion syndrome. Second impact syndrome requires a second concussion before recovery and causes rapid, often fatal swelling.', false),
  ('tbi', 39, 'A 25-year-old is brought in after a bicycle fall without a helmet. Which findings suggest a moderate to severe TBI rather than a mild TBI? Select all that apply.', '[{"id": "a", "text": "Feeling foggy"}, {"id": "b", "text": "Abnormal posturing"}, {"id": "c", "text": "Sensitivity to light"}, {"id": "d", "text": "Balance problems"}, {"id": "e", "text": "Slurred speech"}]'::jsonb, '["b", "e"]', '(b) Correct: abnormal posturing is a moderate to severe TBI finding. (e) Correct: slurred speech is a moderate to severe TBI finding. (a) Wrong: feeling foggy is a mild TBI/concussion symptom. (c) Wrong: sensitivity to light is a mild symptom. (d) Wrong: balance problems are listed with mild TBI.', true),
  ('tbi', 40, 'A client with cerebral edema after a TBI is receiving hypertonic saline, and LOC has improved slightly since the infusion began. Which laboratory value is MOST important for the nurse to monitor with this therapy?', '[{"id": "a", "text": "Arterial blood gases"}, {"id": "b", "text": "Serum osmolality"}, {"id": "c", "text": "Kidney function tests"}, {"id": "d", "text": "Serum sodium"}]'::jsonb, '["d"]', 'Hypertonic saline is a high-concentration salt solution, so the key nursing point is to monitor sodium levels and neurologic response. Serum osmolality and kidney function are the listed monitoring points for mannitol.', false),
  ('tbi', 41, 'The family of a client with a severe TBI asks why an anticonvulsant was prescribed when the client has not had any seizures. Which response by the nurse is BEST?', '[{"id": "a", "text": "It draws fluid out of brain tissue to reduce the swelling."}, {"id": "b", "text": "It calms agitation so that neuro checks are more accurate."}, {"id": "c", "text": "It relieves pain without masking changes in the neuro exam."}, {"id": "d", "text": "It may be given to prevent seizures after severe brain injury."}]'::jsonb, '["d"]', 'Anticonvulsants prevent or treat seizures and may be given prophylactically in severe TBI. Drawing fluid out of brain tissue describes mannitol, and calming agitation describes sedatives.', false),
  ('tbi', 42, 'A client struck with a hammer has a CT scan showing a portion of the skull pushed inward over the left frontal area. The client is alert and oriented. Which intervention does the nurse anticipate is MOST likely?', '[{"id": "a", "text": "Discharge home with concussion rest teaching"}, {"id": "b", "text": "Packing of the scalp wound to stop a CSF leak"}, {"id": "c", "text": "Possible surgical elevation of the depressed bone"}, {"id": "d", "text": "An MRI before any airway or vital sign checks"}]'::jsonb, '["c"]', 'A portion of skull pushed inward is a depressed fracture, which may need surgical elevation. Packing is avoided with a CSF leak, and airway and vital signs always come before further imaging.', false),
  ('tbi', 43, 'A client was knocked out briefly in a fall from a ladder and is now alert, oriented, and asking to leave. The CT scan shows a linear skull fracture. Which response by the nurse is BEST?', '[{"id": "a", "text": "Since you are awake and talking now, serious bleeding is unlikely."}, {"id": "b", "text": "You may feel fine now, but bleeding can cause a rapid decline later."}, {"id": "c", "text": "A linear fracture is a simple break, so observation is not needed."}, {"id": "d", "text": "You can go home if you avoid alcohol and rest for the evening."}]'::jsonb, '["b"]', 'Brief LOC followed by a lucid interval and then rapid decline is the classic epidural hematoma pattern, which is often associated with skull fracture, so appearing fine is not reassuring. A concussion or head injury may look mild at first but can worsen later if bleeding or swelling develops.', false),
  ('tbi', 44, 'The nurse receives report on four clients with head injuries on a step-down unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client with a chronic subdural hematoma and a stable GCS of 14"}, {"id": "b", "text": "A client with a concussion who vomited once 3 hours ago"}, {"id": "c", "text": "A client with a TBI whose BP has fallen to 86/50 from 130/78"}, {"id": "d", "text": "A client with a concussion who asks when sports can resume"}]'::jsonb, '["c"]', 'Circulation follows airway and breathing in TBI priorities; hypotension reduces cerebral perfusion and worsens brain injury. A single episode of vomiting is not the repeated vomiting that signals concern, and a stable GCS is reassuring.', false),
  ('tbi', 45, 'A client with a TBI has signs of increased ICP, and the nurse is planning care for the shift. Which activities should the nurse help the client avoid? Select all that apply.', '[{"id": "a", "text": "Head kept in a midline position"}, {"id": "b", "text": "Excessive coughing"}, {"id": "c", "text": "Straining during bowel movements"}, {"id": "d", "text": "Head of bed elevated about 30 degrees"}, {"id": "e", "text": "Unnecessary stimulation in the room"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: excessive coughing increases ICP. (c) Correct: straining increases ICP. (e) Correct: unnecessary stimulation increases ICP. (a) Wrong: keeping the head midline supports venous drainage and may lower ICP. (d) Wrong: elevating the HOB about 30 degrees is a recommended ICP intervention.', true),
  ('tbi', 46, 'A client with a concussion had a GCS of 15 at triage. Four hours later the client is harder to arouse and the GCS is 13. The spouse says, ''The doctor said it was only a mild concussion.'' Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure the spouse that a mild concussion often causes drowsiness"}, {"id": "b", "text": "Report the change at once, since a concussion can worsen later"}, {"id": "c", "text": "Let the client sleep and repeat the neuro check at discharge"}, {"id": "d", "text": "Explain that a GCS of 13 is expected because the injury is mild"}]'::jsonb, '["b"]', 'A patient with concussion can worsen later, and worsening LOC is never reassuring because it suggests increasing pressure, bleeding, or worsening injury; a drop in GCS is reported at once. Unusual drowsiness is a return-for-care sign, not an expected mild symptom.', false),
  ('tbi', 47, 'A client with clear drainage from the right ear also has raccoon eyes and bruising behind the ears over the mastoid area. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Pack the ear canal with gauze to absorb drainage"}, {"id": "b", "text": "Avoid nasal suction unless specifically cleared"}, {"id": "c", "text": "Insert a nasogastric tube to prevent aspiration"}, {"id": "d", "text": "Monitor for infection such as meningitis"}, {"id": "e", "text": "Document it as expected and recheck next shift"}]'::jsonb, '["b", "d"]', '(b) Correct: with suspected basilar skull fracture there is no NG tube or nasal suction unless specifically cleared. (d) Correct: a CSF leak raises meningitis risk, and infection is a complication especially with CSF leak. (a) Wrong: do not pack nose or ears. (c) Wrong: a nasogastric tube is not inserted. (e) Wrong: clear drainage from nose or ears is reported immediately.', true),
  ('tbi', 48, 'The nurse explains to the family of a client with a TBI why close monitoring is needed during the first days after the injury. Which sequence BEST describes how the brain injury can worsen?', '[{"id": "a", "text": "Edema → ischemia → hemorrhage → rising ICP → decreased cerebral perfusion"}, {"id": "b", "text": "Rising ICP → hemorrhage → ischemia → edema → decreased cerebral perfusion"}, {"id": "c", "text": "Ischemia → rising ICP → edema → decreased cerebral perfusion → hemorrhage"}, {"id": "d", "text": "Hemorrhage → edema → rising ICP → decreased cerebral perfusion → ischemia"}]'::jsonb, '["d"]', 'After trauma, vessels rupture (hemorrhage), inflamed tissue swells (edema), the rigid skull cannot expand so ICP rises, cerebral perfusion decreases, and ischemia causes more brain damage. The other sequences place ischemia or rising ICP before the bleeding and swelling that cause them.', false),
  ('tbi', 49, 'A client with a severe TBI responds only to pain, has irregular respirations, and has a falling oxygen saturation after initial airway stabilization. Which tests or monitoring does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "CT scan to show bleeding and swelling"}, {"id": "b", "text": "ICP monitoring via an implanted device"}, {"id": "c", "text": "Arterial blood gases"}, {"id": "d", "text": "Skull X-rays in place of a CT scan"}, {"id": "e", "text": "Repeated neurologic checks"}]'::jsonb, '["a", "b", "c", "e"]', '(a) Correct: CT quickly shows bleeding, swelling, fractures, and mass effect. (b) Correct: ICP monitoring via an implanted device is used in severe TBI. (c) Correct: ABGs are ordered if respiratory compromise is present. (e) Correct: neurologic checks are essential and continuous. (d) Wrong: X-rays are less informative than CT for head injury.', true),
  ('tbi', 50, 'A 20-year-old is evaluated 1 hour after a concussion during a rugby match. The GCS is 15, and the pupils are equal and reactive. Which finding is an expected finding for this client?', '[{"id": "a", "text": "Unilateral weakness of the right leg"}, {"id": "b", "text": "Vomiting without nausea and worsening headache"}, {"id": "c", "text": "Difficulty concentrating and feeling foggy"}, {"id": "d", "text": "Decreasing LOC since arrival in the department"}]'::jsonb, '["c"]', 'Difficulty concentrating and feeling foggy are mild TBI/concussion symptoms. Unilateral weakness, vomiting without nausea, worsening headache, and decreasing LOC are signs of deterioration or increased ICP that must be reported.', false),
  ('trigeminal', 1, 'A 68-year-old client reports sudden, electric shock-like pain in the right cheek that lasts about 30 seconds whenever she brushes her teeth. A dental exam found no tooth problem. Which treatment should the nurse anticipate FIRST?', '[{"id": "a", "text": "Carbamazepine, an anticonvulsant that stabilizes nerve firing"}, {"id": "b", "text": "A routine pain medicine taken alone at the onset of pain"}, {"id": "c", "text": "Microvascular decompression to move a blood vessel off the nerve"}, {"id": "d", "text": "Dental treatment to remove the tooth that is triggering pain"}]'::jsonb, '["a"]', 'Brief, one-sided, shock-like pain triggered by brushing teeth with no tooth pathology indicates trigeminal neuralgia, and the first-line treatment is anticonvulsant medication, classically carbamazepine. Microvascular decompression is considered only if medication fails or is not tolerated.', false),
  ('trigeminal', 2, 'A 72-year-old client with suspected trigeminal neuralgia keeps a diary of attacks of one-sided, shock-like facial pain. Which diary entries describe typical triggering activities? Select all that apply.', '[{"id": "a", "text": "Shaving the left cheek"}, {"id": "b", "text": "Talking on the phone with a friend"}, {"id": "c", "text": "Lying asleep in bed at night"}, {"id": "d", "text": "Wind on the face while walking outdoors"}, {"id": "e", "text": "Putting on makeup in the morning"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: shaving is a common trigger. (b) Correct: talking is a common trigger. (d) Correct: wind on the face is a common trigger. (e) Correct: putting on makeup is a common trigger. (c) Wrong: attacks usually occur while awake and are less likely to occur during sleep.', true),
  ('trigeminal', 3, 'A client with trigeminal neuralgia describes stabbing pain along the lower jaw and lower teeth that is set off by chewing. Based on this distribution, which branch of cranial nerve V is MOST likely affected?', '[{"id": "a", "text": "V1 — Ophthalmic branch"}, {"id": "b", "text": "V2 — Maxillary branch"}, {"id": "c", "text": "V3 — Mandibular branch"}, {"id": "d", "text": "Both V1 and V2 branches"}]'::jsonb, '["c"]', 'V3 (mandibular) supplies the lower jaw, lower teeth, part of the tongue sensation, and the chewing muscles. V2 is the most commonly affected branch overall, but it supplies the cheek, upper lip, and upper teeth, not the lower jaw.', false),
  ('trigeminal', 4, 'A 74-year-old client with one-sided, shock-like facial pain has an MRI showing a blood vessel pressing on the trigeminal nerve root at the brainstem. The client asks why a light touch on the cheek causes such severe pain. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Inflammation of the facial muscles makes the cheek tender"}, {"id": "b", "text": "Pressure damaged the myelin, so light touch is misread as pain"}, {"id": "c", "text": "A tumor growing on the nerve pathway is causing the pain signals"}, {"id": "d", "text": "The cheek skin has been injured and is healing abnormally"}]'::jsonb, '["b"]', 'In classical trigeminal neuralgia, vascular compression damages the nerve''s myelin sheath over time, so the nerve fires abnormally and harmless light touch is misread as severe pain. A tumor is a secondary cause, but this MRI shows a blood vessel, and the disorder is not inflammatory.', false),
  ('trigeminal', 5, 'A client with trigeminal neuralgia has frequent attacks triggered by chewing, swallowing, brushing teeth, and talking. For which consequences of trigger avoidance should the nurse assess this client? Select all that apply.', '[{"id": "a", "text": "Weight loss from avoiding eating"}, {"id": "b", "text": "Seizures from nerve hyperexcitability"}, {"id": "c", "text": "Dehydration from avoiding drinking"}, {"id": "d", "text": "Social withdrawal from avoiding talking"}, {"id": "e", "text": "Facial muscle paralysis on the affected side"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: avoiding eating leads to weight loss. (c) Correct: avoiding drinking leads to dehydration. (d) Correct: avoiding talking leads to social withdrawal. (b) Wrong: anticonvulsants are used because they reduce abnormal nerve firing that causes pain; seizures are not a listed complication. (e) Wrong: trigeminal neuralgia is a pain disorder; paralysis is not a listed consequence.', true),
  ('trigeminal', 6, 'A 27-year-old client has new attacks of one-sided, electric shock-like pain in the cheek and jaw triggered by touching the face. Which diagnostic step should the nurse anticipate as MOST important for this client?', '[{"id": "a", "text": "A blood test that confirms trigeminal neuralgia"}, {"id": "b", "text": "A dental x-ray to look for tooth decay or abscess"}, {"id": "c", "text": "No testing, because the diagnosis is purely clinical"}, {"id": "d", "text": "An MRI to rule out multiple sclerosis or a tumor"}]'::jsonb, '["d"]', 'In a younger patient, secondary causes such as multiple sclerosis or a tumor must be considered, and MRI is used to rule them out. Diagnosis is mainly clinical, but imaging is still used to look for an underlying cause, and no specific lab test diagnoses the condition.', false),
  ('trigeminal', 7, 'A client newly diagnosed with trigeminal neuralgia after describing brief, shock-like pain in the jaw triggered by chewing asks, ''Which blood test proved I have this?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "No specific lab test diagnoses it; it is mainly clinical."}, {"id": "b", "text": "A blood test for nerve inflammation confirmed the diagnosis."}, {"id": "c", "text": "Your carbamazepine blood level confirmed the diagnosis."}, {"id": "d", "text": "A lab test is done only after an MRI shows a blood vessel."}]'::jsonb, '["a"]', 'There is usually no specific lab test that diagnoses trigeminal neuralgia; diagnosis is mainly clinical, based on history and symptom pattern, with imaging used to look for an underlying cause. The condition is caused by nerve hyperexcitability, not inflammation.', false),
  ('trigeminal', 8, 'A client is admitted with severe one-sided facial pain. While performing the INITIAL pain assessment for suspected trigeminal neuralgia, which data should the nurse collect? Select all that apply.', '[{"id": "a", "text": "Serum lab values that confirm the diagnosis"}, {"id": "b", "text": "Pain quality, such as shock-like or stabbing"}, {"id": "c", "text": "Pain duration per attack and frequency of attacks"}, {"id": "d", "text": "Response of a single tooth to hot or cold food"}, {"id": "e", "text": "Known triggers and whether pain is one-sided"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: pain quality (shock-like, stabbing) is assessed. (c) Correct: duration per attack and frequency of attacks are assessed. (e) Correct: known triggers and one-sided vs both sides are assessed. (a) Wrong: no specific lab test diagnoses trigeminal neuralgia. (d) Wrong: pain triggered by hot or cold food or tooth pressure points toward dental pain.', true),
  ('trigeminal', 9, 'A client who has seen a dentist twice for lower-jaw pain is referred for further evaluation. Which finding reported by the client MOST strongly suggests trigeminal neuralgia rather than dental pain?', '[{"id": "a", "text": "A constant, throbbing ache in one lower molar"}, {"id": "b", "text": "Brief, shock-like attacks set off by light touch"}, {"id": "c", "text": "Pain that starts when drinking hot or cold liquids"}, {"id": "d", "text": "Pain relieved after treatment of a tooth abscess"}]'::jsonb, '["b"]', 'Trigeminal neuralgia causes sudden, shock-like, brief attacks triggered by light touch or daily activities. Constant or throbbing pain, pain triggered by hot or cold food, and pain that responds to dental treatment point to dental pain.', false),
  ('trigeminal', 10, 'A client with trigeminal neuralgia has been taking carbamazepine for 6 weeks and has had no attacks for 10 days. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will report any medication side effects promptly."}, {"id": "b", "text": "I''ll take the medicine exactly as it was prescribed."}, {"id": "c", "text": "Now that the pain is gone, I can stop the medicine."}, {"id": "d", "text": "I''ll call if my pain changes pattern or gets worse."}]'::jsonb, '["c"]', 'Patients must not stop anticonvulsants abruptly unless instructed by the provider, even when pain is controlled. Reporting side effects, taking the drug exactly as prescribed, and reporting a change in pain pattern are all correct.', false),
  ('trigeminal', 11, 'A client with trigeminal neuralgia has lost 4 kg over 2 months because chewing on the left side of the face triggers attacks. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Offer soft foods that require minimal chewing"}, {"id": "b", "text": "Encourage eating on the right, unaffected side"}, {"id": "c", "text": "Encourage chewing on the left side to desensitize it"}, {"id": "d", "text": "Allow rest periods before meals"}, {"id": "e", "text": "Monitor weight and hydration status"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: soft foods that require minimal chewing reduce triggering. (b) Correct: eating on the unaffected side of the mouth is encouraged. (d) Correct: rest periods before meals reduce fatigue and pain anticipation. (e) Correct: weight and hydration status are monitored. (c) Wrong: chewing on the affected side triggers attacks; the note teaches eating on the unaffected side.', true),
  ('trigeminal', 12, 'During a clinic visit, a client with trigeminal neuralgia states, ''I felt fine, so I stopped my carbamazepine on my own two days ago.'' Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Praise the client for reducing medication use"}, {"id": "b", "text": "Suggest a routine pain medicine if the facial pain returns"}, {"id": "c", "text": "Schedule the client for microvascular decompression"}, {"id": "d", "text": "Notify the provider and teach not to stop it abruptly"}]'::jsonb, '["d"]', 'Anticonvulsants must not be stopped abruptly unless instructed by the provider, so the nurse notifies the provider and reinforces this teaching. Routine pain medicines may not work well by themselves, and surgery is for medication failure, not self-discontinuation.', false),
  ('trigeminal', 13, 'A client with newly diagnosed trigeminal neuralgia is prescribed carbamazepine and says, ''Why am I getting a seizure drug? I''ve never had a seizure.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "It reduces the abnormal nerve firing that causes your pain."}, {"id": "b", "text": "It reduces inflammation in the muscles of your jaw."}, {"id": "c", "text": "It prevents the seizures that facial pain can eventually cause."}, {"id": "d", "text": "It works like a routine pain medicine but is stronger."}]'::jsonb, '["a"]', 'Trigeminal neuralgia is caused by nerve hyperexcitability, and anticonvulsants reduce abnormal nerve firing. It is not typical inflammation, and common pain medicines may not work well by themselves.', false),
  ('trigeminal', 14, 'The nurse reviews medication teaching with a client who has started carbamazepine for trigeminal neuralgia. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "I''ll take it exactly as prescribed, even on good days."}, {"id": "b", "text": "I''ll take it only when an attack starts, like a pain pill."}, {"id": "c", "text": "I''ll report any side effects to my provider promptly."}, {"id": "d", "text": "If I feel better for a week, I''ll stop it on my own."}, {"id": "e", "text": "I''ll report it if my pain pattern changes or worsens."}]'::jsonb, '["b", "d"]', '(b) Needs teaching: anticonvulsants are taken exactly as prescribed, not as needed like a simple pain pill. (d) Needs teaching: anticonvulsants must not be stopped abruptly unless instructed by the provider. (a) Correct statement: take anticonvulsants exactly as prescribed. (c) Correct statement: report side effects promptly. (e) Correct statement: report worsening pain or a change in pain pattern.', true),
  ('trigeminal', 15, 'A client with trigeminal neuralgia has lost 3 kg in a month and says every bite of a sandwich sets off a jolt of pain in the jaw. Which dietary intervention by the nurse is BEST?', '[{"id": "a", "text": "Offer three large meals of regular-texture food"}, {"id": "b", "text": "Offer soft foods that require minimal chewing"}, {"id": "c", "text": "Offer very hot foods to numb the trigger zone"}, {"id": "d", "text": "Encourage crunchy foods to desensitize the jaw"}]'::jsonb, '["b"]', 'Chewing triggers attacks and has caused weight loss, so the nurse offers soft foods that require minimal chewing. Crunchy or regular-texture foods increase chewing and therefore trigger more attacks.', false),
  ('trigeminal', 16, 'A client has trigeminal neuralgia affecting the left cheek and jaw and has been avoiding meals because chewing triggers attacks. Which instruction about eating is MOST appropriate?', '[{"id": "a", "text": "Chew mainly on the left side to build tolerance"}, {"id": "b", "text": "Alternate chewing sides with every bite of food"}, {"id": "c", "text": "Eat on the right, unaffected side of the mouth"}, {"id": "d", "text": "Avoid chewing and take only clear liquids"}]'::jsonb, '["c"]', 'The nurse encourages eating on the unaffected side of the mouth if possible, which here is the right side. Chewing on the affected left side provokes attacks, and avoiding food risks weight loss and poor nutrition.', false),
  ('trigeminal', 17, 'A client reports recurring pain in the upper gums and cheek and asks whether it is ''just a bad tooth.'' Which findings would support trigeminal neuralgia rather than dental pain? Select all that apply.', '[{"id": "a", "text": "Sudden, shock-like, brief attacks"}, {"id": "b", "text": "Pain triggered by direct pressure on one tooth"}, {"id": "c", "text": "Pain triggered by light touch on the cheek"}, {"id": "d", "text": "Tooth decay found on dental examination"}, {"id": "e", "text": "Pain that follows the trigeminal nerve distribution"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: trigeminal neuralgia causes sudden, shock-like, brief attacks. (c) Correct: it is triggered by light touch or daily activities. (e) Correct: it follows the trigeminal nerve distribution. (b) Wrong: direct tooth pressure as a trigger points to dental pain. (d) Wrong: dental pain is linked to tooth pathology such as decay.', true),
  ('trigeminal', 18, 'A client with trigeminal neuralgia has not brushed his teeth for a week because brushing triggers excruciating pain in the upper gums. Which nursing action is BEST?', '[{"id": "a", "text": "Allow the client to skip oral care until the pain is in remission"}, {"id": "b", "text": "Brush the client''s teeth firmly to remove plaque quickly"}, {"id": "c", "text": "Teach the client to brush only on days without attacks"}, {"id": "d", "text": "Offer gentle oral care with cotton swabs and minimal pressure"}]'::jsonb, '["d"]', 'The nurse monitors for inadequate oral hygiene and offers gentle oral care with cotton swabs or a soft-bristle toothbrush with minimal facial pressure. Skipping oral care is tempting because brushing triggers pain, but it leads to poor oral hygiene.', false),
  ('trigeminal', 19, 'The nurse on a medical unit receives shift report on four clients with trigeminal neuralgia. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Has avoided all fluids for a day because swallowing triggers pain"}, {"id": "b", "text": "Reports a 30-second attack of cheek pain while shaving this morning"}, {"id": "c", "text": "Asks when microvascular decompression might become an option"}, {"id": "d", "text": "States the pain has not woken her from sleep in the past week"}]'::jsonb, '["a"]', 'Avoiding drinking leads to dehydration, a physical complication that needs prompt assessment of hydration status. A brief attack while shaving and pain-free sleep are expected features, and the surgery question is not urgent.', false),
  ('trigeminal', 20, 'A 31-year-old client with one-sided, shock-like facial pain is scheduled for an MRI and asks what the scan will show. Which purposes of the MRI should the nurse include in the explanation? Select all that apply.', '[{"id": "a", "text": "To confirm the diagnosis instead of the history"}, {"id": "b", "text": "To look for a blood vessel compressing the nerve"}, {"id": "c", "text": "To rule out multiple sclerosis"}, {"id": "d", "text": "To measure the carbamazepine blood level"}, {"id": "e", "text": "To rule out a tumor affecting the nerve pathway"}]'::jsonb, '["b", "c", "e"]', '(b) Correct: MRI may look for compression of the nerve by a blood vessel. (c) Correct: MRI rules out secondary causes such as multiple sclerosis. (e) Correct: MRI rules out a tumor. (a) Wrong: diagnosis is largely clinical, based on history and symptom pattern. (d) Wrong: an MRI is imaging and does not measure a drug level.', true),
  ('trigeminal', 21, 'A 66-year-old client has had attacks of one-sided facial pain for 3 months and is describing their pattern to the nurse. Which description is an expected finding for this condition?', '[{"id": "a", "text": "Attacks wake the client from deep sleep most nights"}, {"id": "b", "text": "Attacks occur while awake and rarely during sleep"}, {"id": "c", "text": "A constant, dull ache that lasts the entire day"}, {"id": "d", "text": "Pain that is equal on both sides of the face"}]'::jsonb, '["b"]', 'Trigeminal neuralgia usually occurs while awake and is less likely to occur during sleep. Nightly waking pain does not fit, and the pain is brief and one-sided rather than constant or bilateral.', false),
  ('trigeminal', 22, 'A client with right-sided trigeminal neuralgia controlled with carbamazepine for 2 years calls to report that shock-like pain has now started on the left side of the face as well. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "This is expected because attacks become more intense over time."}, {"id": "b", "text": "Increase the carbamazepine dose until the pain stops."}, {"id": "c", "text": "You need an evaluation, since symptoms are now bilateral."}, {"id": "d", "text": "Use a warm compress on the left side and rest."}]'::jsonb, '["c"]', 'Trigeminal neuralgia is usually unilateral, and patients are taught to seek evaluation if symptoms change pattern or become bilateral. Attacks may become more intense over time, but spread to both sides is a change in pattern, not an expected progression.', false),
  ('trigeminal', 23, 'A home health nurse visits a client with trigeminal neuralgia who takes carbamazepine. Which findings should the nurse report to the provider? Select all that apply.', '[{"id": "a", "text": "A change in the usual pain pattern"}, {"id": "b", "text": "A 20-second attack triggered by shaving"}, {"id": "c", "text": "No attacks during sleep last week"}, {"id": "d", "text": "New pain on the other side of the face"}, {"id": "e", "text": "A pain-free period of remission for 2 weeks"}]'::jsonb, '["a", "d"]', '(a) Correct: a change in pain pattern should be reported. (d) Correct: symptoms that become bilateral need evaluation. (b) Wrong: brief attacks lasting seconds up to about 2 minutes triggered by shaving are typical. (c) Wrong: attacks are less likely during sleep. (e) Wrong: periods of remission between episodes may occur.', true),
  ('trigeminal', 24, 'A client admitted with trigeminal neuralgia has had three attacks this morning. The bed is next to an air-conditioning vent that blows cool air across the client''s face. Which action by the nurse is BEST?', '[{"id": "a", "text": "Protect the client''s face from drafts and cold air"}, {"id": "b", "text": "Give a routine pain medicine before each meal"}, {"id": "c", "text": "Apply a cold pack to the cheek to numb the trigger zone"}, {"id": "d", "text": "Have the client wash the face to calm the skin"}]'::jsonb, '["a"]', 'Drafts, cold air, and wind on the face are triggers, so the nurse protects the face from them. A cold pack and face washing add stimulation to the trigger zone and can provoke attacks.', false),
  ('trigeminal', 25, 'A client with trigeminal neuralgia has an order for pain control to be given before meals, and the lunch tray will arrive in 30 minutes. The client reports that eating often triggers attacks. What is the BEST timing for this medication?', '[{"id": "a", "text": "After lunch, once the client reports an attack"}, {"id": "b", "text": "Only if the client reports pain during the meal"}, {"id": "c", "text": "At bedtime, so the client sleeps through the night"}, {"id": "d", "text": "Before eating, as ordered, to control pain"}]'::jsonb, '["d"]', 'The nurse administers pain control before eating if ordered, because eating triggers attacks and pain control supports nutrition. Waiting until an attack occurs during or after the meal defeats the purpose of the order.', false),
  ('trigeminal', 26, 'A client with trigeminal neuralgia is hospitalized after a week of frequent attacks. Which interventions should the nurse use to help the client avoid triggers? Select all that apply.', '[{"id": "a", "text": "Identify and document known personal triggers"}, {"id": "b", "text": "Use gentle face care techniques"}, {"id": "c", "text": "Massage the trigger zone firmly to desensitize it"}, {"id": "d", "text": "Protect the face from drafts and wind"}, {"id": "e", "text": "Place the bed near an open window for fresh air"}]'::jsonb, '["a", "b", "d"]', '(a) Correct: the nurse identifies and documents known personal triggers. (b) Correct: gentle face care techniques reduce stimulation. (d) Correct: the face is protected from drafts, cold air, and wind. (c) Wrong: light touch in a trigger zone provokes attacks, so firm massage would trigger pain. (e) Wrong: an open window exposes the face to drafts and wind.', true),
  ('trigeminal', 27, 'A client with trigeminal neuralgia becomes tearful and says, ''I never know when an attack will hit, and I''m scared to eat or talk.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Try not to think about the pain, and it will occur less."}, {"id": "b", "text": "This pain is severe; let''s involve you in care planning."}, {"id": "c", "text": "Attacks are brief, so the pain is not really serious."}, {"id": "d", "text": "Many people learn to ignore the pain with time."}]'::jsonb, '["b"]', 'Living with unpredictable, severe pain causes anxiety, and the nurse acknowledges the severity of pain and involves the patient in care planning. Minimizing the pain because attacks are brief dismisses the client''s distress.', false),
  ('trigeminal', 28, 'A 62-year-old client with trigeminal neuralgia has had poor pain control despite carbamazepine and another anticonvulsant. An MRI confirms a blood vessel compressing the trigeminal nerve root. Which treatment should the nurse anticipate NEXT?', '[{"id": "a", "text": "Microvascular decompression surgery"}, {"id": "b", "text": "Routine pain medicines taken alone"}, {"id": "c", "text": "An MRI to rule out multiple sclerosis"}, {"id": "d", "text": "Dental treatment of the painful upper teeth"}]'::jsonb, '["a"]', 'When medication fails, procedures or surgery follow, and microvascular decompression is especially relevant when vascular compression is confirmed as the cause. Routine pain medicines may not work well by themselves, and the MRI has already identified the cause.', false),
  ('trigeminal', 29, 'A client with trigeminal neuralgia has lost 5 kg, drinks very little because swallowing triggers pain, and says, ''I''m always afraid of another attack.'' Which nursing diagnoses BEST fit these data? Select all that apply.', '[{"id": "a", "text": "Ineffective tissue perfusion"}, {"id": "b", "text": "Acute confusion related to medication"}, {"id": "c", "text": "Imbalanced nutrition: less than body requirements"}, {"id": "d", "text": "Risk for deficient fluid volume"}, {"id": "e", "text": "Anxiety"}]'::jsonb, '["c", "d", "e"]', '(c) Correct: weight loss from pain with eating fits imbalanced nutrition. (d) Correct: avoiding drinking fits risk for deficient fluid volume. (e) Correct: fear of unpredictable severe pain fits anxiety. (a) Wrong: no data suggest a perfusion problem. (b) Wrong: no data show confusion.', true),
  ('trigeminal', 30, 'A client with trigeminal neuralgia is scheduled for microvascular decompression after medications failed. The client asks, ''What will the surgeon actually do?'' Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Partially damage the trigeminal nerve to block pain transmission"}, {"id": "b", "text": "Inject the nerve to block signals at specific points"}, {"id": "c", "text": "Move a blood vessel away from the nerve to relieve pressure"}, {"id": "d", "text": "Remove the affected teeth that are triggering the pain"}]'::jsonb, '["c"]', 'Microvascular decompression is surgery that moves a blood vessel away from the nerve to relieve pressure. Partially damaging the nerve describes nerve ablation, and blocking signals at specific nerve points describes injections or nerve blocks.', false),
  ('trigeminal', 31, 'A 79-year-old client whose trigeminal neuralgia did not respond to carbamazepine is scheduled for a nerve ablation procedure. Which statement by the client indicates understanding of this procedure?', '[{"id": "a", "text": "It moves a blood vessel off the nerve to relieve pressure."}, {"id": "b", "text": "It partially damages the nerve to block pain transmission."}, {"id": "c", "text": "It replaces my carbamazepine permanently with an injection."}, {"id": "d", "text": "It removes the myelin so the nerve can heal normally."}]'::jsonb, '["b"]', 'Nerve ablation procedures partially damage the nerve to block pain transmission. Moving a blood vessel off the nerve describes microvascular decompression, a different surgery.', false),
  ('trigeminal', 32, 'A client has had severe trigeminal neuralgia for 3 years, lives alone, and recently stopped attending family meals. Which psychosocial complications should the nurse assess for? Select all that apply.', '[{"id": "a", "text": "Social withdrawal"}, {"id": "b", "text": "Sleep disturbance"}, {"id": "c", "text": "Depression related to chronic pain"}, {"id": "d", "text": "Hallucinations during attacks"}, {"id": "e", "text": "Anxiety"}]'::jsonb, '["a", "b", "c", "e"]', '(a) Correct: social withdrawal is a psychosocial complication. (b) Correct: sleep disturbance is a psychosocial complication. (c) Correct: depression related to chronic severe pain is a psychosocial complication. (e) Correct: anxiety is a psychosocial complication. (d) Wrong: hallucinations are not a complication of trigeminal neuralgia.', true),
  ('trigeminal', 33, 'A client has taken an over-the-counter pain reliever for weeks for brief, one-sided, shock-like facial pain triggered by chewing, with little relief. The client asks why it is not working. Which response by the nurse is BEST?', '[{"id": "a", "text": "The dose is too low; doubling it should control the pain."}, {"id": "b", "text": "The pain comes from inflammation, so a stronger anti-inflammatory helps."}, {"id": "c", "text": "Pain medicine works only after a dental cause is treated."}, {"id": "d", "text": "This is nerve pain; anticonvulsants are the first-line treatment."}]'::jsonb, '["d"]', 'Trigeminal neuralgia is caused by nerve hyperexcitability, not typical inflammation, so common pain medicines may not work well by themselves and anticonvulsants are first-line. Increasing the analgesic does not address the cause.', false),
  ('trigeminal', 34, 'A 34-year-old client with multiple sclerosis has developed trigeminal neuralgia and asks whether treatment of the MS matters for the facial pain. Which response by the nurse is BEST?', '[{"id": "a", "text": "Managing your MS may reduce your facial pain episodes."}, {"id": "b", "text": "The two conditions are unrelated, so treat only the pain."}, {"id": "c", "text": "Treating MS will make the facial pain more frequent."}, {"id": "d", "text": "MS treatment should wait until the facial pain is cured."}]'::jsonb, '["a"]', 'When trigeminal neuralgia is caused by another condition such as multiple sclerosis, the underlying disorder also needs treatment, and managing it may reduce episodes. MS is a recognized secondary cause, so the conditions are not unrelated.', false),
  ('trigeminal', 35, 'A client''s attacks of shock-like facial pain are consistently set off by touching the face, and the provider documents involvement of the V2 (maxillary) branch of cranial nerve V. In which areas should the nurse expect the client to report pain? Select all that apply.', '[{"id": "a", "text": "Cheek"}, {"id": "b", "text": "Forehead"}, {"id": "c", "text": "Upper lip"}, {"id": "d", "text": "Upper teeth"}, {"id": "e", "text": "Lower jaw"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: V2 supplies the cheek. (c) Correct: V2 supplies the upper lip. (d) Correct: V2 supplies the upper teeth. (b) Wrong: the forehead is supplied by V1 (ophthalmic). (e) Wrong: the lower jaw is supplied by V3 (mandibular).', true),
  ('trigeminal', 36, 'A client presents with intermittent facial pain, and the nurse suspects trigeminal neuralgia. Which assessment finding would MOST strongly confirm the hallmark pattern of this condition?', '[{"id": "a", "text": "Constant aching pain across both sides of the forehead"}, {"id": "b", "text": "Facial pain that is worst during deep sleep"}, {"id": "c", "text": "Pain in the cheek and jaw triggered by light touch"}, {"id": "d", "text": "Pain relieved by applying hot packs to the face"}]'::jsonb, '["c"]', 'The key assessment point is confirming that the pain follows the trigeminal nerve distribution (face, jaw, cheek, teeth, gums) and that light touch triggers it. Constant bilateral pain and pain worst during sleep do not fit, because attacks are brief, one-sided, and less likely during sleep.', false),
  ('trigeminal', 37, 'A client with trigeminal neuralgia has stopped attending a weekly church group and rarely sees friends because talking triggers attacks. Which nursing diagnosis BEST fits these data?', '[{"id": "a", "text": "Imbalanced nutrition: less than body requirements"}, {"id": "b", "text": "Risk for deficient fluid volume"}, {"id": "c", "text": "Self-care deficit"}, {"id": "d", "text": "Social isolation"}]'::jsonb, '["d"]', 'Social isolation is reduced interaction with others due to pain with talking or eating, which matches this client''s withdrawal from friends and groups. The data do not describe weight loss, reduced fluid intake, or difficulty with hygiene.', false),
  ('trigeminal', 38, 'A client with trigeminal neuralgia says, ''I''m afraid to leave the house because an attack could hit at any moment.'' Which nursing actions are appropriate to reduce this client''s anxiety? Select all that apply.', '[{"id": "a", "text": "Tell the client the pain is likely made worse by stress"}, {"id": "b", "text": "Avoid discussing fears so the client stays calm"}, {"id": "c", "text": "Acknowledge the severity of the client''s pain"}, {"id": "d", "text": "Explain that attacks are too brief to be serious"}, {"id": "e", "text": "Involve the client in planning care when possible"}]'::jsonb, '["c", "e"]', '(c) Correct: the nurse acknowledges the severity of pain. (e) Correct: the nurse involves the patient in care planning when possible. (a) Wrong: the pain comes from nerve hyperexcitability, and blaming stress dismisses it. (b) Wrong: the nurse provides emotional support rather than avoiding the client''s fears. (d) Wrong: the pain is excruciating and seriously affects quality of life, even though attacks are brief.', true),
  ('trigeminal', 39, 'A client with trigeminal neuralgia has stopped shaving and washing the face because these activities set off severe attacks, and the nurse notes poor facial hygiene. Which nursing diagnosis BEST fits these data?', '[{"id": "a", "text": "Self-care deficit"}, {"id": "b", "text": "Chronic pain"}, {"id": "c", "text": "Social isolation"}, {"id": "d", "text": "Risk for deficient fluid volume"}]'::jsonb, '["a"]', 'Self-care deficit is difficulty performing hygiene or daily tasks due to trigger avoidance, which matches the client''s avoidance of shaving and face washing. Chronic pain is present, but these data focus on the hygiene deficit caused by avoiding triggers.', false),
  ('trigeminal', 40, 'A 70-year-old client newly diagnosed with trigeminal neuralgia asks, ''With pain this bad, is this going to kill me?'' Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Yes, untreated attacks can gradually lead to a stroke over time."}, {"id": "b", "text": "Only if the pain spreads to both sides of the face."}, {"id": "c", "text": "It is not usually life-threatening but affects quality of life."}, {"id": "d", "text": "It becomes life-threatening if carbamazepine is stopped."}]'::jsonb, '["c"]', 'Trigeminal neuralgia is not usually life-threatening by itself, but it can seriously affect quality of life through poor nutrition, dehydration, anxiety, and depression. Stroke is not a listed complication of this condition.', false),
  ('trigeminal', 41, 'A client with trigeminal neuralgia could not tolerate carbamazepine or other anticonvulsants. Which treatment options might the provider consider NEXT? Select all that apply.', '[{"id": "a", "text": "Injections or nerve blocks"}, {"id": "b", "text": "Nerve ablation procedures"}, {"id": "c", "text": "Simple analgesics alone"}, {"id": "d", "text": "Microvascular decompression"}, {"id": "e", "text": "Removal of the upper teeth"}]'::jsonb, '["a", "b", "d"]', '(a) Correct: injections or nerve blocks are an option if medication fails. (b) Correct: nerve ablation procedures are an option. (d) Correct: microvascular decompression is a surgical option. (c) Wrong: trigeminal neuralgia is treated with anticonvulsants, not simple analgesics alone. (e) Wrong: no tooth pathology explains trigeminal neuralgia, so removing teeth does not treat it.', true),
  ('trigeminal', 42, 'The nurse is teaching a client who has just started carbamazepine for trigeminal neuralgia. Which statement by the client indicates understanding of the medication plan?', '[{"id": "a", "text": "I''ll take an extra dose whenever I feel an attack starting."}, {"id": "b", "text": "I''ll take it exactly as prescribed and report side effects."}, {"id": "c", "text": "I''ll stop it if my pain is gone for a few days."}, {"id": "d", "text": "I''ll replace it with a routine pain reliever if it upsets me."}]'::jsonb, '["b"]', 'Patients take anticonvulsants exactly as prescribed and report medication side effects promptly. Stopping when pain is gone is unsafe, because anticonvulsants are not stopped abruptly unless instructed by the provider.', false),
  ('trigeminal', 43, 'A client with trigeminal neuralgia developed intolerable side effects after starting carbamazepine and reported them to the nurse promptly. Which plan should the nurse anticipate as MOST likely from the provider?', '[{"id": "a", "text": "Switch to simple analgesics alone for the pain"}, {"id": "b", "text": "Stop all treatment and wait for remission"}, {"id": "c", "text": "Refer for dental treatment of the affected teeth"}, {"id": "d", "text": "Use another anticonvulsant based on tolerance"}]'::jsonb, '["d"]', 'Other anticonvulsants are used depending on response and tolerance when carbamazepine is not ideal. Simple analgesics alone are not the treatment, because the pain comes from nerve hyperexcitability.', false),
  ('trigeminal', 44, 'A 69-year-old client is being evaluated for trigeminal neuralgia. Which features of the client''s pain are expected findings for this condition? Select all that apply.', '[{"id": "a", "text": "Pain that regularly wakes the client from sleep"}, {"id": "b", "text": "Pain on one side of the face"}, {"id": "c", "text": "Attacks lasting seconds up to about 2 minutes"}, {"id": "d", "text": "Attacks that come in clusters or repeated bursts"}, {"id": "e", "text": "Periods of remission between episodes"}]'::jsonb, '["b", "c", "d", "e"]', '(b) Correct: pain is on one side of the face (unilateral). (c) Correct: brief attacks last seconds up to about 2 minutes. (d) Correct: attacks can come in clusters or repeated bursts. (e) Correct: there may be periods of remission between episodes. (a) Wrong: attacks usually occur while awake and are less likely during sleep.', true),
  ('trigeminal', 45, 'A client with trigeminal neuralgia had no attacks for 4 weeks, and then the same shock-like jaw pain returned while chewing. The client asks whether the treatment has failed. Which response by the nurse is BEST?', '[{"id": "a", "text": "Periods of remission between episodes may occur."}, {"id": "b", "text": "The return of the same pain means the diagnosis was wrong."}, {"id": "c", "text": "The return of pain means surgery is needed now."}, {"id": "d", "text": "Pain returning after 4 weeks means a new disorder."}]'::jsonb, '["a"]', 'Trigeminal neuralgia may have periods of remission between episodes, so the return of the same pattern after a pain-free period is consistent with the condition. A return of the same pain does not mean the diagnosis was wrong or that a new disorder is present.', false),
  ('trigeminal', 46, 'The nurse is triaging telephone calls from four clients who report facial pain. Which client''s description is MOST consistent with trigeminal neuralgia?', '[{"id": "a", "text": "A dull, throbbing ache in a back tooth with cold drinks."}, {"id": "b", "text": "A steady burning pain on both sides of the face all day."}, {"id": "c", "text": "Sudden electric shock pain on one side when brushing teeth."}, {"id": "d", "text": "Pain across the forehead that slowly builds over several hours."}]'::jsonb, '["c"]', 'Sudden electric shock pain on one side of the face when brushing teeth is the classic description of trigeminal neuralgia. A throbbing toothache with cold drinks fits dental pain, and constant bilateral pain does not match the brief, one-sided attacks.', false),
  ('trigeminal', 47, 'A client describes attacks of stabbing pain in the right lower jaw that are triggered by chewing. Which description of attack duration would the nurse recognize as an expected finding?', '[{"id": "a", "text": "Each attack lasts several hours before slowly easing"}, {"id": "b", "text": "Each attack lasts seconds up to about 2 minutes"}, {"id": "c", "text": "Each attack lasts all day and fades at bedtime"}, {"id": "d", "text": "Each attack lasts 30 to 60 minutes at a time"}]'::jsonb, '["b"]', 'Trigeminal neuralgia causes brief attacks lasting seconds up to about 2 minutes. Attacks lasting 30 minutes, hours, or all day do not fit the brief paroxysms of this condition.', false),
  ('trigeminal', 48, 'A client with trigeminal neuralgia taking carbamazepine reports that attacks have gone from twice a week to several times a day and have become more intense over the past month. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure the client that worsening is expected and needs no action"}, {"id": "b", "text": "Advise doubling the carbamazepine dose until pain improves"}, {"id": "c", "text": "Advise stopping carbamazepine because it is not working"}, {"id": "d", "text": "Report the worsening pain and change in pattern to the provider"}]'::jsonb, '["d"]', 'Attacks may become more frequent and intense over time, but patients are taught to report worsening pain or a change in pain pattern, and the nurse reports new or worsening symptoms to the provider. Stopping carbamazepine is unsafe because anticonvulsants are not stopped abruptly.', false),
  ('trigeminal', 49, 'A UAP is assisting a client with trigeminal neuralgia of the left cheek with morning care. Which action by the UAP requires immediate intervention by the nurse?', '[{"id": "a", "text": "Scrubbing the client''s face firmly with a cool washcloth"}, {"id": "b", "text": "Letting the client do gentle face care at their own pace"}, {"id": "c", "text": "Offering a soft-bristle toothbrush for oral care"}, {"id": "d", "text": "Closing the window to keep wind off the client''s face"}]'::jsonb, '["a"]', 'Washing and touching the face are triggers, so gentle face care techniques are required; firm scrubbing with a cool cloth can provoke an attack. A soft-bristle toothbrush and protecting the face from wind are correct actions.', false),
  ('trigeminal', 50, 'A client with trigeminal neuralgia is exhausted and very anxious before meals because eating often triggers attacks, and the client eats only a few bites. Which intervention is BEST to add to the meal plan?', '[{"id": "a", "text": "Serve meals immediately after morning care"}, {"id": "b", "text": "Allow rest periods before meals"}, {"id": "c", "text": "Encourage the client to eat quickly before an attack"}, {"id": "d", "text": "Give large meals less often to limit triggers"}]'::jsonb, '["b"]', 'Allowing rest periods before meals reduces fatigue and pain anticipation, which addresses this client''s exhaustion and anxiety before eating. Serving meals right after morning care adds fatigue and facial stimulation before eating.', false)
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale, is_multi)
  JOIN _neuro2_seed_map m USING (source_key)
 CROSS JOIN _neuro2_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _neuro2_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Neurology seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
